/* map q09 (519 mục) — engine-API đợt 1744-1746 Ch.1746 */
window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q09"]=window.__LIBQ["pham-nhan-tu-tien"]["q09"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q09"]["map"]={"updatedAt":"2026-07-24","count":519,"nodes":[{"id":"rung-quai-thu-do-tham","name":"Rừng quái thụ đỏ thẫm","cn":"","capDo":"khac","parentId":"man-hoang-chi-dia","blurb":"Khu rừng có những cây đỏ thẫm với cành vặn vẹo như trường xà.","detail":"Đây là điểm Hàn Lập cùng bốn tu sĩ Hóa Thần hội họp trước khi tiếp tục tiến sâu vào Man Hoang Chi Địa.","theLucLienQuan":["Nhân Tộc","Yêu Tộc"],"nguon":["@c1354"]},{"id":"man-hoang-chi-dia","name":"Man Hoang Chi Địa","cn":"","aliases":["Man Hoang"],"capDo":"vuc","parentId":"linh-gioi","blurb":"Vùng hoang dã rộng lớn mà đội thám sát chuẩn bị tiến sâu vào.","detail":"Du Hồng cảnh báo lộ trình phía trước trong Man Hoang Chi Địa nguy hiểm hơn nhiều so với đoạn đường cả đội đã vượt qua.","theLucLienQuan":["Nhân Tộc","Yêu Tộc"],"nguon":["@c1354"]},{"id":"hac-thach-sam-lam","name":"Hắc Thạch Sâm Lâm","cn":"","capDo":"vuc","parentId":"man-hoang-chi-dia","blurb":"Đích đến của đội thám sát Nhân–Yêu và là khu vực hoạt động của Mộc Linh Tộc.","detail":"Đội năm người phải đến Hắc Thạch Sâm Lâm nằm vùng và thu thập tình báo về Mộc Linh Tộc. Khu vực này được Thiên Mộc Mộng La Lung Tráo bao phủ, khiến người có cảnh giới trên Hóa Thần lập tức bại lộ khi tiến vào.","theLucLienQuan":["Mộc Linh Tộc","Nhân Tộc","Yêu Tộc"],"nguon":["@c1354"]},{"id":"khu-vuc-di-toc","name":"Khu vực Dị Tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực nguy hiểm mà nhóm phi thăng tu sĩ được phái tới thực hiện nhiệm vụ tình báo.","detail":"Nhóm tu sĩ Nhân Tộc và Yêu Tộc được phái tới đây theo một kế hoạch đã thay đổi sau khi Huyền Thiên Trảm Linh Kiếm xuất hiện. Đạo nhân trung niên mặt vàng nhận định nhiệm vụ nguy hiểm hơn vẻ bề ngoài.","theLucLienQuan":["Dị Tộc","Nhân Tộc","Yêu Tộc"],"nguon":["@c1355"]},{"id":"phong-nguyen-dai-luc","name":"Phong Nguyên Đại Lục","cn":"","capDo":"gioi-dien","parentId":"linh-gioi","blurb":"Đại lục nhỏ nhất trong ba đại lục của Linh Giới nhưng tập trung nhiều chủng tộc cường đại.","detail":"Phía tây bắc Phong Nguyên Đại Lục được Dự Ngôn xác định là khu vực Huyền Thiên Trảm Linh Kiếm sẽ xuất hiện trong Nhân Tộc, khiến toàn vùng đứng trước nguy cơ tranh đoạt và huyết tế.","theLucLienQuan":["Nhân Tộc","Yêu Tộc","Mộc Tộc","Ảnh Tộc","Linh Tộc","Hắc Xoa Tộc","Dạ Xoa Tộc"],"nguon":["@c1356","@c1408","@c1548","@c1578"]},{"id":"tay-bac-phong-nguyen-dai-luc","name":"Tây bắc Phong Nguyên Đại Lục","cn":"","capDo":"vuc","parentId":"phong-nguyen-dai-luc","blurb":"Khu vực cư trú của Nhân Tộc và nhiều dị tộc, được dự ngôn là nơi Huyền Thiên Trảm Linh Kiếm xuất hiện.","detail":"Lời dự ngôn đặt khu vực này trước nguy cơ bùng phát đại chiến giữa các chủng tộc. Các thế lực cường đại còn có thể huyết tế sinh linh trong vùng để triệu hoán Huyền Thiên Linh Bảo.","theLucLienQuan":["Nhân Tộc","Yêu Tộc","Mộc Tộc","Ảnh Tộc","Linh Tộc","Hắc Xoa Tộc","Dạ Xoa Tộc"],"nguon":["@c1356"]},{"id":"tien-gioi","name":"Tiên Giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới có tiên nhân, được nhắc tới khi so sánh sức mạnh của Chân Linh.","detail":"Tiên Giới xuất hiện trong lời giải thích về Chân Linh và hiểm họa gắn với Huyền Thiên Linh Bảo.","theLucLienQuan":[],"nguon":["@c1356"]},{"id":"di-toc","name":"Dị Tộc","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Điểm đến của các nhóm nhân thủ được phái đi trong nhiệm vụ hiện tại.","detail":"Thiên Nguyên Thánh Hoàng dự đoán đoàn phi thăng tu sĩ trên đường đến khu vực Dị Tộc sẽ bị Ảnh Tộc tập kích.","theLucLienQuan":["Ảnh Tộc","Nhân Tộc"],"nguon":["@c1357"]},{"id":"khu-vuc-loi-quy-xuat-hien","name":"Khu vực Lôi Quy xuất hiện","cn":"","capDo":"khac","parentId":"man-hoang-chi-dia","blurb":"Một vùng trong Man Hoang Chi Địa nơi đoàn Hàn Lập chạm trán Lôi Quy.","detail":"Khi Lôi Quy hiện thân để hấp thu lôi điện, nơi này xuất hiện mây xám, những vòi lốc nối trời đất và một trận bão sấm chớp lan rộng. Đoàn người phải chạy liền mấy vạn dặm mới thoát khỏi phạm vi thiên tượng.","theLucLienQuan":[],"nguon":["@c1358"]},{"id":"khe-nui-co-cu-thao-tim","name":"Khe núi có cự thảo tím","cn":"","capDo":"khac","parentId":"man-hoang-chi-dia","blurb":"Khoảng trống nằm giữa hai ngọn núi lớn trong Man Hoang Chi Địa.","detail":"Một thằn lằn xanh có sừng đỏ và một cự nhân toàn thân mọc nhiều mắt giằng co tại đây quanh cây cự thảo tím mang chuỗi quả hình tiểu long.","theLucLienQuan":[],"nguon":["@c1359"]},{"id":"khu-vuc-linh-qua","name":"Khu vực linh quả","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực có linh quả được Cự Đại Tích Dịch và Thiên Mục Cự Nhân canh giữ.","detail":"Nhóm Lũng Đông chia người ẩn nấp quanh khu vực, bố trí kế hoạch dùng Ngân Giao Khôi Lỗi khiêu khích hai quái vật rồi để Hàn Lập tiếp cận và đoạt linh quả. Cuối chương, các đòn công kích giả khiến hai quái vật bắt đầu xung đột.","theLucLienQuan":[],"nguon":["@c1361"]},{"id":"dinh-nui-cach-noi-doat-qua-may-van-dam","name":"Đỉnh núi cách nơi đoạt quả mấy vạn dặm","cn":"","capDo":"khac","parentId":"man-hoang-chi-dia","blurb":"Địa điểm Hàn Lập dừng lại sau khi thoát khỏi hai cự thú.","detail":"Tại đỉnh núi này, Hàn Lập kiểm tra xung quanh, uống đan dược hồi phục nguyên khí và chờ các thành viên trong đội tập hợp để chia Chi Long Quả.","theLucLienQuan":[],"nguon":["@c1363"]},{"id":"nam-can-dai-sa-mac","name":"Nam Cấn đại sa mạc","cn":"","capDo":"vuc","parentId":"tay-bac-phong-nguyen-dai-luc","blurb":"Sa mạc nóng bỏng mà đoàn Hàn Lập buộc phải đi qua trên đường tiếp tục hành trình.","detail":"Bên dưới lớp cát vốn là một vùng núi lửa nên nhiệt độ cực cao. Theo truyền thuyết, Thiên Phượng đã dùng bão cát vùi lấp vùng núi lửa sau trận chiến kéo dài với Hỏa Ngạc. Mộc Tộc và Ảnh Tộc thường xuyên qua lại nơi đây.","theLucLienQuan":["Mộc Tộc","Ảnh Tộc"],"nguon":["@c1364"]},{"id":"thai-thu-son-mach","name":"Thái Thú sơn mạch","cn":"","capDo":"vuc","parentId":"tay-bac-phong-nguyen-dai-luc","blurb":"Dãy núi nằm ở một phía của Nam Cấn đại sa mạc.","detail":"Thái Thú sơn mạch có vô số cao giai cổ thú, khiến đoàn tu sĩ Hóa Thần không thể chọn nơi này làm đường vòng an toàn.","theLucLienQuan":[],"nguon":["@c1364"]},{"id":"giao-uyen-dai-hap-coc","name":"Giao Uyên đại hạp cốc","cn":"","capDo":"vuc","parentId":"tay-bac-phong-nguyen-dai-luc","blurb":"Đại hạp cốc nguy hiểm nằm ở phía còn lại của Nam Cấn.","detail":"Nơi đây có nhiều ác giao ngoài Luyện Hư và hơn mười Giao vương Hợp Thể kỳ, vì vậy đoàn Hàn Lập không thể dùng làm tuyến đường vòng.","theLucLienQuan":[],"nguon":["@c1364"]},{"id":"oc-dao-co-thanh-nho","name":"Ốc đảo có thành nhỏ","cn":"","capDo":"thanh","parentId":"nam-can-dai-sa-mac","blurb":"Ốc đảo có một thành trì nhân tộc xuất hiện bất thường giữa Nam Cấn.","detail":"Thành nhỏ nằm trong vùng sa mạc hẻo lánh gần khu vực dị tộc. Hóa thân trinh sát của Lý đạo hữu xác nhận bên trong có nhiều tu sĩ, gồm tám người đạt Hóa Thần kỳ, nhưng không có tu sĩ ngoài Luyện Hư kỳ.","theLucLienQuan":["Nhân Tộc"],"nguon":["@c1364","@c1365"],"aliases":["Thành nhỏ trong ốc đảo","Ốc đảo"]},{"id":"nhat-tuyen-thien","name":"Nhất Tuyến Thiên","cn":"","capDo":"khac","parentId":null,"blurb":"Điểm đến tiếp theo trên hành trình của nhóm Hàn Lập, được Tử Vân thượng nhân cảnh báo là vừa xảy ra biến cố.","detail":"Nhóm thám hiểm dự kiến tiến vào Nhất Tuyến Thiên sau vài ngày. Tử Vân thượng nhân tuyên bố nơi này vừa có biến cố nguy hiểm, nhưng tính xác thực của lời cảnh báo chưa được xác nhận.","theLucLienQuan":[],"nguon":["@c1365","@c1369"]},{"id":"sa-mac-gan-khu-vuc-di-toc-hoat-dong","name":"Sa mạc gần khu vực dị tộc hoạt động","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng sa mạc rộng lớn gần khu vực có dị tộc thường xuyên qua lại.","detail":"Lũng Đông, bạch bào thiếu nữ và Hàn Lập lần lượt xuất hiện tại vùng sa mạc này. Hàn Lập quyết định không kéo dài cuộc truy đuổi vì lo ngại kinh động thêm dị tộc, rồi quay lại giao chiến với người truy sát mình.","theLucLienQuan":["Ảnh tộc"],"nguon":["@c1367"]},{"id":"sa-mac","name":"Sa mạc","cn":"","aliases":[],"capDo":"khac","parentId":"man-hoang-chi-dia","blurb":"Khu vực Hàn Lập vượt qua trên đường trở về Nhất Tuyến Thiên.","detail":"Hàn Lập bí mật phi độn hơn mười ngày qua sa mạc. Trong quãng đường này, thần niệm của hắn hoàn toàn hồi phục và không còn thấy Xích ảnh tiếp tục truy đuổi.","theLucLienQuan":[],"nguon":["@c1369"]},{"id":"di-tich-kien-truc-thuong-co","name":"Di tích kiến trúc thượng cổ","cn":"","aliases":[],"capDo":"khac","parentId":"nhat-tuyen-thien","blurb":"Điểm tập kết của những thành viên còn sống trong đội Hàn Lập.","detail":"Di tích còn lại những cột đá cao lớn, tường đá và hài cốt không suy chuyển giữa cuồng phong. Du Hồng, Lũng Đông và Diệp Dĩnh chờ tại đây trước khi Hàn Lập tìm tới hội hợp.","theLucLienQuan":[],"nguon":["@c1369"]},{"id":"hac-diep-sam-lam","name":"Hắc Diệp Sâm Lâm","cn":"","capDo":"vuc","parentId":"bien-gioi-moc-toc","blurb":"Khu rừng khổng lồ thuộc địa bàn quan trọng của Mộc Tộc và là mục tiêu xâm nhập của đội trinh sát.","detail":"Cây cối trong rừng có lá mang hoa văn khó hiểu, khiến toàn khu vực hiện màu xanh đen. Phần lớn diện tích Hắc Diệp Sâm Lâm nằm trong phạm vi giám sát và điều khiển cây cối của Mộng La Linh Thụ.","theLucLienQuan":["Mộc Tộc","Thiên Uyên Thành","Nhân Tộc"],"nguon":["@c1370","@c1387"]},{"id":"bien-gioi-moc-toc","name":"Biên giới Mộc Tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực nằm cạnh Hắc Diệp Sâm Lâm, nơi Hàn Lập tới sau nhiều tháng vượt qua vùng hoang dã.","detail":"Đây là điểm bắt đầu chặng bí mật xâm nhập địa bàn Mộc Tộc của Hàn Lập sau khi hắn bị thất lạc đồng đội tại Nhất Tuyến Thiên.","theLucLienQuan":["Mộc Tộc","Nhân Tộc","Thiên Uyên Thành"],"nguon":["@c1370"]},{"id":"khu-cam-che-co-ngan-sac-tieu-thu","name":"Khu cấm chế có ngân sắc tiểu thụ","cn":"","capDo":"khac","parentId":"hac-diep-sam-lam","blurb":"Khu vực bí ẩn được cấm chế mạnh bảo vệ trong Hắc Diệp Sâm Lâm. Một nhóm người chưa rõ thân phận tập trung tại đây để tiếp nhận tin tức và truyền tống rời đi.","detail":"Bên trong khu vực có một Ngân sắc tiểu thụ cao sáu bảy trượng. Sau khi nhân ảnh mắt bích lục báo cáo tin tức, bóng người cao lớn ra lệnh cho cả nhóm vây quanh cây rồi kích hoạt các quang trụ truyền tống.","theLucLienQuan":[],"nguon":["@c1371"]},{"id":"dai-son-co-co-thu-nua-chay","name":"Đại sơn có cổ thụ nửa cháy","cn":"","capDo":"khac","parentId":"hac-diep-sam-lam","blurb":"Ngọn núi cao khoảng trăm trượng trong Hắc Diệp Sâm Lâm, nơi Hàn Lập tìm được địa điểm mục tiêu. Điểm chỉ dẫn nằm tại một cổ thụ nửa cháy trên núi.","detail":"Cây cối trên núi khá thưa thớt. Cổ thụ được pháp bàn chỉ tới cao hơn ba mươi trượng, nửa trên cháy đen còn nửa dưới mang màu xanh pha vàng; Hàn Lập bố trí ngân châu và trận kỳ quanh khu vực trước khi tiến vào.","theLucLienQuan":[],"nguon":["@c1371"]},{"id":"diem-cat-giau-tinh-bao-tai-doi-nui","name":"Điểm cất giấu tình báo tại đồi núi","cn":"","capDo":"khac","parentId":null,"blurb":"Khu đồi có cây cổ thụ được dùng làm nơi giấu ngọc giản tình báo của mạng lưới nằm vùng.","detail":"Hàn Lập dùng ảo thuật cấm chế che phủ khu vực này trước khi lấy ngọc giản từ cây cổ thụ. Mộc Tộc đã lần theo nhóm thâm nhập tới đây, bố trí lực lượng trong các thân cây rồi dùng hàng nghìn mộc vượn thú phong tỏa toàn bộ khu đồi.","theLucLienQuan":["Mộc Tộc","Nhân Tộc","Yêu Tộc"],"nguon":["@c1372"]},{"id":"rung-ram-u-toi","name":"Rừng rậm u tối","cn":"","capDo":"khac","parentId":"bien-gioi-moc-toc","blurb":"Khu rừng do lực lượng Mộc Tộc và đàn mộc viên thú hoạt động.","detail":"Sau khi Mộc Thụy phát lệnh, tiếng hô ứng vang lên từ sâu trong rừng và các mộc viên thú chia nhau truy kích những luồng độn quang. Hàn Lập tiếp tục bị ba Mộc Tộc phục kích khi chạy qua khu vực này.","theLucLienQuan":["Mộc Tộc"],"nguon":["@c1373"]},{"id":"toa-nui-nho-ngoai-hac-diep-sam-lam","name":"Tòa núi nhỏ ngoài Hắc Diệp Sâm Lâm","cn":"","capDo":"khac","parentId":"phong-nguyen-dai-luc","blurb":"Một tòa núi nhỏ cách Hắc Diệp Sâm Lâm hơn nghìn dặm. Hàn Lập dừng tại đây để suy tính cách cứu vãn nhiệm vụ và chuẩn bị truy tìm thiếu nữ áo bào trắng.","detail":"Sau khi dùng Thái Nhất Hóa Thanh phù thoát khỏi truy binh, Hàn Lập tới tòa núi nhỏ này, giải trừ phù rồi gọi báo lân thú ra. Hắn dùng pháp bàn cùng nhũ quang để chuẩn bị cho cuộc truy tìm tiếp theo.","theLucLienQuan":[],"nguon":["@c1374"]},{"id":"vung-nuoc-xanh-biec-vo-tan","name":"Vùng nước xanh biếc vô tận","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng mặt nước rộng lớn không thấy bờ, chưa xác định là hồ lớn hay biển rộng.","detail":"Báo lân thú dẫn Hàn Lập đến vùng nước này sau ba ngày ba đêm truy tung Diệp Dĩnh. Mục tiêu cuối cùng dừng trên một hòn đảo nằm giữa vùng nước.","theLucLienQuan":[],"nguon":["@c1375"]},{"id":"tieu-dao-noi-diep-dinh-dung-chan","name":"Tiểu đảo nơi Diệp Dĩnh dừng chân","cn":"","capDo":"khac","parentId":"vung-nuoc-xanh-biec-vo-tan","blurb":"Hòn đảo rộng khoảng mười dặm, cây cối rậm rạp và hiếm có dấu chân người.","detail":"Tại khoảng đất trống có nhiều cự thạch ở trung tâm đảo, Hàn Lập tìm thấy Diệp Dĩnh đang bị thương và gặp Diệp Sở, người nằm vùng của Diệp gia trong Mộc Tộc.","theLucLienQuan":["Diệp gia","Mộc Tộc"],"nguon":["@c1375"]},{"id":"hoang-nguyen-gan-nhat-tuyen-thien","name":"Hoang nguyên gần Nhất Tuyến Thiên","cn":"","capDo":"khac","parentId":"nhat-tuyen-thien","blurb":"Vùng hoang nguyên mà nhóm Hàn Lập đi qua sau một tháng rút khỏi lãnh địa Mộc Tộc.","detail":"Khôi lỗi mộc điểu chở Hàn Lập, Diệp Sở và Bạch Bào Thiếu Nữ tới vùng hoang nguyên trước lối vào Nhất Tuyến Thiên, nơi dị tượng sấm gió bất ngờ xuất hiện.","theLucLienQuan":[],"nguon":["@c1376"]},{"id":"khu-vuc-ngoai-pham-vi-nhan-toc","name":"Khu vực ngoài phạm vi Nhân Tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực nằm ngoài phạm vi kiểm soát của Nhân Tộc, nơi cuộc đối đầu giữa hai chân linh chi phách diễn ra.","detail":"Thiếu nữ áo bào trắng cho rằng Lũng Đông lựa chọn địa điểm này để tránh giao ước cấm các chân linh thế gia công khai tranh đoạt huyết mạch trong phạm vi Nhân Tộc.","theLucLienQuan":["Diệp gia","Lũng gia","Các chân linh thế gia"],"nguon":["@c1377"]},{"id":"khong-trung-chien-truong","name":"Không trung chiến trường","cn":"","capDo":"khac","parentId":null,"blurb":"Không vực nơi kim long và thải phượng giao đấu, sau đó trở thành địa điểm tranh đoạt Huyết Tinh Ma Ha Kiếm.","detail":"Sau khi Huyết Tinh Ma Ha Kiếm xuất hiện và lơ lửng trên không, Lũng Vũ cùng Lũng Lân hiện ra ở hai bên kiếm để ngăn nhóm Diệp Dĩnh tiếp cận.","theLucLienQuan":["Diệp gia","Lũng gia"],"nguon":["@c1378"]},{"id":"khu-vuc-huyet-sac-cu-kiem","name":"Khu vực huyết sắc cự kiếm","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường quanh huyết sắc cự kiếm, nơi các tu sĩ Lũng gia dựng tuyến phòng thủ.","detail":"Tại đây, quầng sáng phù văn bảo vệ huyết sắc cự kiếm trong khi các Xích Quỷ cầm chân Diệp Dĩnh, khiến nàng không thể tiếp cận mục tiêu.","theLucLienQuan":["Lũng gia","Diệp gia"],"nguon":["@c1379"]},{"id":"dia-ban-moc-toc","name":"Địa bàn Mộc Tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực do Mộc Tộc kiểm soát, nơi Diệp Sở từng ẩn mình trong nhiều năm.","detail":"Theo Tiểu Hồng, Mộc Tộc từng cất giữ ba cây Thiên Phượng chi linh tại địa bàn của mình và đã bị người Yêu Tộc thâm nhập làm nội ứng.","theLucLienQuan":["Mộc Tộc","Yêu Tộc"],"nguon":["@c1379"]},{"id":"man-hoang","name":"Man Hoang","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực rộng lớn nơi Hàn Lập dự định tiếp tục lưu lại thay vì trở về Thiên Uyên thành.","detail":"Sau cuộc trao đổi với Diệp gia, Hàn Lập nói rõ sẽ lưu lại Man Hoang một thời gian và chưa có ý định quay về Thiên Uyên thành.","theLucLienQuan":["Mộc tộc"],"nguon":["@c1384"]},{"id":"dinh-nui-nho","name":"Đỉnh núi nhỏ","cn":"","capDo":"khac","parentId":null,"blurb":"Đỉnh núi nơi Hàn Lập dừng lại bố trí kiếm trận để nghênh chiến Ngân giai mộc linh.","detail":"Hàn Lập đáp xuống đỉnh núi, thả bảy mươi hai phi kiếm vào bốn phía và dựng nhiều tầng phòng ngự. Đây trở thành chiến trường nơi Đại Canh kiếm trận vây khốn Ngân giai mộc linh.","theLucLienQuan":[],"nguon":["@c1385"]},{"id":"cao-nguyen-hoang-vu","name":"Cao nguyên hoang vu","cn":"","capDo":"vuc","parentId":null,"blurb":"Một vùng cao nguyên vắng vẻ mà Hàn Lập đặt chân tới sau hai tháng phi hành.","detail":"Hàn Lập chọn một ngọn núi nhỏ trên cao nguyên, mở mật thất, dùng đan dược và bế quan hơn một tháng cho tới khi tinh khí thần khôi phục hoàn toàn.","theLucLienQuan":[],"nguon":["@c1387"]},{"id":"vung-nui-ho-vo-danh","name":"Vùng núi hồ vô danh","cn":"","capDo":"vuc","parentId":"man-hoang","blurb":"Một vùng núi non ẩm ướt, cây cối thấp bé và có nhiều hồ lớn nhỏ trong thế giới hoang dã.","detail":"Hàn Lập mất hơn nửa năm đơn độc vượt qua khu vực này. Trên đường, hắn bị hơn mười dị thú tập kích và phải giao chiến với một man ngư cự thú gần tương đương tu sĩ Hóa Thần kỳ.","theLucLienQuan":[],"nguon":["@c1389"]},{"id":"song-phong-bang-tim","name":"Song phong băng-tím","cn":"","capDo":"khac","parentId":"man-hoang","blurb":"Cặp núi có hình dáng gần giống nhau, một ngọn phủ băng tuyết và ngọn còn lại phủ rừng lá tím.","detail":"Hai ngọn núi cách nhau hơn mười dặm và là dấu hiệu đặc trưng giúp Hàn Lập nhận ra địa điểm hội hợp của nhóm tu sĩ phi thăng.","theLucLienQuan":[],"nguon":["@c1389"]},{"id":"bang-son-hoi-hop","name":"Băng sơn hội hợp","cn":"","capDo":"khac","parentId":"song-phong-bang-tim","blurb":"Ngọn núi phủ băng tuyết được chọn làm điểm hội hợp bí mật của nhóm tu sĩ phi thăng.","detail":"Một tầng ảo trận che giấu lối vào bên trong núi. Khu trú ẩn gồm một gian phòng lớn khoét vào vách núi và nhiều băng ốc nhỏ dành cho các thành viên nghỉ ngơi trước ngày xuất phát.","theLucLienQuan":[],"nguon":["@c1389"]},{"id":"thien-trac-thanh","name":"Thiên Trắc thành","cn":"","capDo":"thanh","parentId":null,"blurb":"Tòa thành nơi nhiều tu sĩ phi thăng từng cư trú và tu luyện.","detail":"Liễu lão giả từng gặp Hàn Lập tại Phi Linh điện ở đây, còn Triệu Đát đã khổ tu trong thành suốt nhiều năm.","theLucLienQuan":["Phi Linh điện"],"nguon":["@c1389"]},{"id":"bang-dien-tren-nui","name":"Băng điện trên núi","cn":"","capDo":"khac","parentId":null,"blurb":"Đại điện bằng băng rộng khoảng trăm trượng, được dựng trên ngọn núi làm nơi tập hợp đoàn săn Chân Thiềm.","detail":"Bên trong có các băng trụ chống đỡ, một đài băng cao ở trung tâm và pháp trận có thể hiện hóa ghế ngọc. Gần hai mươi tu sĩ tập trung tại đây để nghe tình báo và phân công nhiệm vụ.","theLucLienQuan":[],"nguon":["@c1390"]},{"id":"sao-huyet-bich-nhan-chan-thiem","name":"Sào huyệt Bích Nhãn Chân Thiềm","cn":"","capDo":"khac","parentId":null,"blurb":"Sào huyệt nằm sâu dưới lòng đất tại khu vực có địa hình bất lợi cho việc vây diệt.","detail":"Khoảng mười Bích Nhãn Chân Thiềm sinh sống tại đây cùng hơn trăm Hắc Huyết Nghĩ và hơn trăm Ảnh Trùng Thú. Ba giống cổ thú nương tựa lẫn nhau, khiến việc thanh tiễu phải được tiến hành theo kế hoạch chia cắt.","theLucLienQuan":[],"nguon":["@c1390"]},{"id":"ho-lon-phia-tay","name":"Hồ lớn phía tây","cn":"","capDo":"khac","parentId":null,"blurb":"Hồ lớn nằm cách nơi tập kết ba ngày ba đêm phi hành về phía tây, bị màn sương mù dày đặc bao phủ.","detail":"Không khí quanh hồ ẩm lạnh khác thường và tầm nhìn bị sương mù che khuất. Đoàn tu sĩ dừng ngoài màn sương để đề phòng cổ thú ẩn nấp tập kích.","theLucLienQuan":[],"nguon":["@c1390"]},{"id":"ho-suong-mu","name":"Hồ sương mù","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng hồ rộng lớn bị sương mù trắng bao phủ và là nơi sinh sống của vô số quái cầm.","detail":"Đoàn săn phải dùng cuồng phong mở thông đạo qua màn sương. Quái cầm màu trắng trong hồ có thể phun thủy tiễn chứa toan dịch ăn mòn pháp bảo và liên tục tổ chức nhiều đợt tập kích.","theLucLienQuan":[],"nguon":["@c1391"]},{"id":"cu-son-giua-ho","name":"Cự sơn giữa hồ","cn":"","capDo":"khac","parentId":"ho-suong-mu","blurb":"Ngọn núi cao khoảng vạn trượng nằm giữa hồ sương mù, che giấu hệ thống động ngầm dưới chân núi.","detail":"Chân núi cắm xuống đáy hồ, phần lộ ra có màu hắc lục và gần như trơ trụi. Khu vực này có Hắc Huyết Nghĩ canh giữ, còn hệ thống động ngầm bên dưới là nơi đoàn săn xác định có Chân Thiềm Thú.","theLucLienQuan":[],"nguon":["@c1391"]},{"id":"hang-chan-thiem-thu","name":"Hang Chân Thiềm Thú","cn":"","capDo":"khac","parentId":"cu-son-giua-ho","blurb":"Hang động thuộc hệ thống động ngầm thiên nhiên dưới chân cự sơn giữa hồ.","detail":"Đây là mục tiêu chính của đoàn săn Chân Thiềm Thú. Trước khi tiến vào thăm dò, đoàn tu sĩ phải xử lý đàn Hắc Huyết Nghĩ hoạt động ở khu vực bên ngoài.","theLucLienQuan":[],"nguon":["@c1391"]},{"id":"thong-dao-ngam-trong-cu-son","name":"Thông đạo ngầm trong cự sơn","cn":"","capDo":"khac","parentId":"cu-son-giua-ho","blurb":"Hệ thống đường hầm tự nhiên dẫn sâu xuống lòng cự sơn.","detail":"Thông đạo ẩm ướt, âm u và quanh co, có chung nhũ, rêu xanh, đá phát ánh sáng nhạt cùng nhiều độc trùng. Một đoạn phía trước mở rộng thành khu vực có hai Huyền Qua Thú đang bám trên vách đá ăn rêu.","theLucLienQuan":[],"nguon":["@c1392"]},{"id":"linh-tu-thach-mach","name":"Linh Từ Thạch Mạch","cn":"","capDo":"khac","parentId":"cu-son-giua-ho","blurb":"Mạch đá đặc biệt nằm tại một vị trí chưa xác định trong cự sơn.","detail":"Mạch đá có thể hút mạnh linh lực của sinh vật dùng Thổ Độn Thuật tiến vào núi đá, khiến đội thám hiểm không thể vòng qua Huyền Qua Thú bằng cách độn thổ.","theLucLienQuan":[],"nguon":["@c1392"]},{"id":"song-ngam","name":"Sông ngầm","cn":"","capDo":"khac","parentId":"cu-son-giua-ho","blurb":"Dòng sông ngầm nằm trên đường tiến sâu vào sào huyệt Chân Thiềm Thú.","detail":"Sông rộng hơn mười trượng, nước chảy khá xiết và tỏa hơi lạnh đậm đặc. Theo Chúc tiền bối, vượt qua dòng sông này có thể đi thẳng tới sào huyệt Chân Thiềm Thú.","theLucLienQuan":[],"nguon":["@c1393"]},{"id":"ngoai-cu-son","name":"Ngoài cự sơn","cn":"","capDo":"khac","parentId":"cu-son-giua-ho","blurb":"Khu vực cảnh giới bên ngoài cự sơn, nơi hai thành viên đội săn bị tập kích.","detail":"Triệu lão và Tuần đạo hữu ẩn trong mây trắng tại đây để làm nhiệm vụ cảnh giới. Hai sinh vật có cánh thịt bất ngờ xuất hiện, giết Triệu lão và bắt Nguyên Anh của Tuần đạo hữu.","theLucLienQuan":[],"nguon":["@c1393"]},{"id":"son-coc-xa-la","name":"Sơn cốc xa lạ","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn cốc ba mặt có núi bao quanh và chỉ có một lối ra.","detail":"Hàn Lập trồi lên tại đây sau khi độn ngầm hàng nghìn dặm, rồi phát hiện hai Dạ Xoa cấp cao đứng trên một cây đại thụ. Thiếu nữ họ Tiêu sau đó cũng cưỡi Ngũ sắc tiểu thuyền xuất hiện gần hắn.","theLucLienQuan":["Dạ Xoa tộc","Nhân tộc"],"nguon":["@c1395"]},{"id":"chien-truong-cach-xa-hai-da-xoa-vuong","name":"Chiến trường cách xa hai Dạ Xoa Vương","cn":"","capDo":"khac","parentId":"man-hoang","blurb":"Nơi Hàn Lập và nữ tử họ Tiêu chủ động chọn để giao chiến với hai Xương Nô.","detail":"Hai người kéo đối phương bay thêm mấy nghìn dặm trước khi dừng lại. Vị trí này đủ xa khu vực hai Dạ Xoa Vương quan sát trực tiếp nhưng không vượt quá giới hạn có thể khiến họ can thiệp.","theLucLienQuan":["Dạ Xoa tộc"],"nguon":["@c1397"]},{"id":"bai-loan-thach-trong-suong-xam","name":"Bãi loạn thạch trong sương xám","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng đất xa lạ nơi Hàn Lập tỉnh lại sau lần truyền tống cự ly cực xa.","detail":"Mặt đất phủ đầy đá tròn xám trắng và bị sương xám bao quanh. Tại đây, thần niệm của Hàn Lập tạm thời không thể rời khỏi thân thể.","theLucLienQuan":[],"nguon":["@c1399"]},{"id":"dong-suoi-trong-vung-suong-xam","name":"Dòng suối trong vùng sương xám","cn":"","capDo":"khac","parentId":"bai-loan-thach-trong-suong-xam","blurb":"Dòng suối rộng vài trượng nằm trong vùng sương xám xa lạ.","detail":"Nước suối trong, có vị ngọt và có thể uống được. Hàn Lập nghỉ ngơi tại đây, chạm trán Vương bát trư yêu và gặp đàn thú giống hươu lẫn ngựa.","theLucLienQuan":[],"nguon":["@c1399"]},{"id":"bien-xich-hong","name":"Biển xích hồng","cn":"","capDo":"vuc","parentId":null,"blurb":"Hải vực rộng lớn có nước biển đỏ, nằm về phía bắc nơi Hàn Lập xuất hiện sau truyền tống.","detail":"Ven biển có bãi cát nơi hơn nghìn cự quy nghỉ ngơi và nhiều quy xác nằm rải rác. Ngoài khơi có đàn quái điểu đỏ, yêu vật hình mực cùng một yêu thú mang khí tức cấp Hóa Thần.","theLucLienQuan":["Yêu tộc"],"nguon":["@c1400"]},{"id":"bai-bien-cu-quy","name":"Bãi biển cự quy","cn":"","capDo":"khac","parentId":"bien-xich-hong","blurb":"Bãi cát ven biển xích hồng, nơi hơn nghìn cự quy tập trung nghỉ ngơi.","detail":"Nhiều quy xác nằm trên mặt bãi cát, trong khi một số quy xác mang ngân văn quý hiếm bị chôn sâu bên dưới. Hàn Lập tìm được ba quy xác ngân văn tại đây.","theLucLienQuan":[],"nguon":["@c1400"]},{"id":"son-mach-phia-nam","name":"Sơn mạch phía nam","cn":"","capDo":"vuc","parentId":null,"blurb":"Dãy núi xanh lớn nằm về phía nam vùng loạn thạch.","detail":"Sơn mạch liên miên không dứt, cách nơi Hàn Lập khảo sát ban đầu hơn ba mươi dặm. Hàn Lập chuyển tới đây sau khi từ bỏ việc truy bắt yêu vật ngoài biển.","theLucLienQuan":[],"nguon":["@c1400"]},{"id":"bien-sau-xich-hong","name":"Biển sâu","cn":"","capDo":"khac","parentId":"bien-xich-hong","blurb":"Khu vực ngoài khơi biển xích hồng, nơi có yêu thú cấp cao ẩn náu.","detail":"Yêu vật hình mực chạy vào khu vực này và hội hợp với một tồn tại tỏa yêu khí không kém tu sĩ Hóa Thần. Hai yêu thú sau đó cùng tiến sâu vào biển.","theLucLienQuan":["Yêu tộc"],"nguon":["@c1400"]},{"id":"cu-dao","name":"Cự đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng đất cực lớn có dãy núi giàu linh khí, bờ biển nước đỏ và một khu vực rộng lớn bị biển sương đen bao phủ.","detail":"Sau khi khảo sát nhiều hướng và không thể tìm được đường vòng qua biển sương, Hàn Lập kết luận nơi này là một cự đảo rất lớn, dù vẫn để ngỏ khả năng đây là bán đảo. Một nửa vùng đất vẫn nằm dưới biển sương đen.","theLucLienQuan":[],"nguon":["@c1401"]},{"id":"bien-suong-den","name":"Biển sương đen","cn":"","capDo":"vuc","parentId":"cu-dao","blurb":"Biển sương màu đen bao phủ vô số ngọn núi và kéo dài qua một phần rất lớn của cự đảo.","detail":"Đất đá ở rìa biển sương đều đen và khô nứt, hoàn toàn không có cỏ cây. Một cây nhỏ vừa bị ném vào màn sương đã đổi màu, khô héo rồi hóa thành bụi đất, cho thấy nơi đây có khả năng hủy hoại sinh cơ rất mạnh.","theLucLienQuan":[],"nguon":["@c1401"]},{"id":"day-nui-tren-cu-dao","name":"Dãy núi trên cự đảo","cn":"","capDo":"vuc","parentId":"cu-dao","blurb":"Dãy núi hiểm trở và giàu linh khí, trải dài đến mức Hàn Lập bay suốt hai tháng vẫn chưa vượt qua.","detail":"Trong dãy núi có rất nhiều linh thảo, linh mộc cấp thấp, các đàn thú và những yêu thú cấp sáu, cấp bảy. Khí tức hung ác bao trùm khu vực nhưng nguồn linh khí tại đây rất nồng đậm.","theLucLienQuan":[],"nguon":["@c1401"]},{"id":"vach-nui-ba-van-tu-do","name":"Vách núi ba văn tự đỏ","cn":"","capDo":"khac","parentId":"bien-suong-den","blurb":"Vách núi phẳng nhẵn sát biển sương đen, trên mặt khắc ba văn tự dị tộc màu đỏ.","detail":"Ba văn tự đã bị thời gian làm mờ một phần nhưng vẫn tỏa ra sát khí mạnh. Hàn Lập không thể nhận diện chúng dù từng nghiên cứu văn tự cổ của Nhân tộc, Yêu tộc và một số dị tộc lân cận.","theLucLienQuan":[],"nguon":["@c1401"]},{"id":"bo-bien-nuoc-do","name":"Bờ biển nước đỏ","cn":"","capDo":"khac","parentId":"cu-dao","blurb":"Bờ biển nằm ngoài dãy núi trên cự đảo, có nước biển mang màu đỏ.","detail":"Hàn Lập gặp bờ biển này sau khi bay ra khỏi dãy núi. Nước biển đỏ liên tục vỗ vào những bãi đá gần bờ.","theLucLienQuan":[],"nguon":["@c1401"]},{"id":"dong-phu-trong-cu-son","name":"Động phủ trong cự sơn","cn":"","capDo":"khac","parentId":"cu-dao","blurb":"Động phủ do Hàn Lập mở trong ngọn cự sơn có linh khí tốt nhất trên đảo.","detail":"Hàn Lập đào rỗng một nửa lòng núi để dựng động phủ lớn, sau đó bố trí cấm chế và trồng số linh dược mang theo. Nơi này nằm bên ngoài dãy núi và cách biển sương đen hơn mười ngày đường.","theLucLienQuan":[],"nguon":["@c1401"]},{"id":"khu-vuc-mot-tram-dam-quanh-dong-phu","name":"Khu vực một trăm dặm quanh động phủ","cn":"","capDo":"khac","parentId":"dong-phu-cua-han-lap","blurb":"Vùng hoang dã bao quanh động phủ Hàn Lập.","detail":"Sau khi bốn yêu thú đầu lĩnh cùng thú đàn bị cấm chế đánh lui, yêu vật hoàn toàn tránh xa khu vực này. Trong phạm vi một trăm dặm quanh động phủ không còn thấy chim bay hay thú chạy.","theLucLienQuan":[],"nguon":["@c1402"]},{"id":"day-hac-an-son","name":"Dãy Hắc Ẩn sơn","cn":"","capDo":"vuc","parentId":null,"blurb":"Dãy núi có nhiều linh sơn nằm dưới sự khống chế của Thiên Bằng tộc. Những yêu vật còn sống tại đây phải hợp sức tìm vật cung phụng.","detail":"Tam đại trưởng lão Thiên Bằng tộc từng thanh trừng những yêu vật có tu vi cao tại Hắc Ẩn sơn, chỉ giữ lại nhóm có thiên phú tìm kiếm vật cần thiết. Linh sơn do Hàn Lập chiếm giữ hiện là nơi duy nhất trong vùng còn Hoa Mộc Linh.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1403"]},{"id":"vung-bien-san-ho","name":"Vùng biển san hô","cn":"","capDo":"khac","parentId":"bien-sau-xich-hong","blurb":"Vùng biển có nhiều cụm san hô lớn nhỏ, nằm cách hòn đảo của Hàn Lập vài trăm dặm.","detail":"Động phủ của Bảo Quang tôn giả nằm tại đây. Cuối chương, Hàn Lập dùng Nguyên Từ thần Sơn và Nguyên Từ Thần quang bao phủ bề mặt biển san hô rộng vài mẫu.","theLucLienQuan":[],"nguon":["@c1404"]},{"id":"suong-mu-den","name":"Sương mù đen","cn":"","capDo":"khac","parentId":"cu-dao","blurb":"Khu vực cổ xưa và nguy hiểm trên cự đảo, khiến ngay cả Thiên Bằng tộc cũng kiêng kỵ.","detail":"Vị tiền bối Hạo Thú tộc nửa quỷ nửa yêu chỉ có thể sống ở vòng ngoài của sương mù. Sinh linh có tu vi thấp tiến vào có nguy cơ bị hút sạch máu thịt và hóa thành xương khô.","theLucLienQuan":["Hạo Thú tộc","Thiên Bằng tộc"],"nguon":["@c1404"]},{"id":"vung-san-ho-tren-bien","name":"Vùng san hô trên biển","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng san hô che giấu động phủ của Bảo Quang tôn giả dưới đáy biển.","detail":"Nguyên Từ thần sơn khuấy đảo khu vực này, nghiền đá ngầm thành bột, tạo sóng cao và một xoáy nước khổng lồ trên mặt biển.","theLucLienQuan":[],"nguon":["@c1405"]},{"id":"dong-phu-bao-quang-ton-gia","name":"Động phủ Bảo Quang tôn giả","cn":"","capDo":"khac","parentId":"vung-san-ho-tren-bien","blurb":"Động phủ ẩn trong núi dưới vùng san hô, thuộc về Bảo Quang tôn giả.","detail":"Động phủ có cấm chế vàng lam, cửa san hô trắng và hành lang màu xanh dài gần trăm trượng. Bên trong là gian phòng lớn lát ngọc, khảm dạ minh châu và treo san hô đỏ tỏa nhiệt.","theLucLienQuan":[],"nguon":["@c1405"]},{"id":"gian-phong-dat-thach-don","name":"Gian phòng đặt thạch đôn","cn":"","capDo":"khac","parentId":"dong-phu-bao-quang-ton-gia","blurb":"Gian phòng xa hoa trong động phủ Bảo Quang tôn giả, nơi Hàn Lập phát hiện thạch đôn kỳ dị.","detail":"Căn phòng rộng khoảng năm, sáu mươi trượng, có nền lát ngọc và một bàn ngọc. Thạch đôn được đặt trước bàn, chìm sâu gần nửa thân vào lớp nền Huyền Thiết tinh nằm dưới gạch ngọc.","theLucLienQuan":[],"nguon":["@c1405"]},{"id":"dong-phu-hac-an-son-mach","name":"Động phủ Hắc Ẩn sơn mạch","cn":"","capDo":"khac","parentId":"day-hac-an-son","blurb":"Động phủ nơi Hàn Lập nghiên cứu khối thạch đôn mang về và tiếp bốn yêu quái đến giao dịch.","detail":"Hàn Lập mang một trong ba khối thạch đôn về đây, thử nhiều phương pháp luyện hóa rồi phát hiện hàng nghìn Phệ Kim Trùng trưởng thành đang ngủ say với dấu hiệu biến dị. Đúng kỳ hạn bảy ngày, hai yêu thú đầu trâu, Kim Mao cự viên và Dã trư khổng lồ tới động phủ để trao đổi vật phẩm với hắn.","theLucLienQuan":[],"nguon":["@c1406"]},{"id":"xich-ma-hai","name":"Xích Ma Hải","cn":"","capDo":"vuc","parentId":"phong-nguyen-dai-luc","blurb":"Hải vực nơi Hắc Minh đảo tọa lạc.","detail":"Xích Ma Hải nằm cạnh Phong Nguyên đại lục và có nhiều yêu thú bị Phi Linh tộc đuổi từ đại lục xuống biển.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1408"]},{"id":"hac-minh-dao","name":"Hắc Minh đảo","cn":"","capDo":"khac","parentId":"phong-nguyen-dai-luc","blurb":"Địa vực mang tên đảo nhưng thực chất là một bán đảo nối với Phong Nguyên đại lục.","detail":"Hắc Minh đảo là nơi Hàn Lập đang tạm trú, phần lớn diện tích bị sương đen bao phủ và nằm trong khu vực do Phi Linh tộc khống chế.","theLucLienQuan":["Phi Linh tộc","Thiên Bằng tộc"],"nguon":["@c1408"]},{"id":"dong-phu-thu-dau-trau","name":"Động phủ thú đầu trâu","cn":"","capDo":"khac","parentId":"hac-minh-dao","blurb":"Động phủ nằm sau thạch môn xanh trong lớp sương trắng ở núi trúc.","detail":"Đây là nơi bốn yêu thú tiếp đón ba sứ giả Thiên Bằng và bàn việc giao nộp cống vật. Hàn Lập bí mật lẻn vào ngay khi cửa động phủ sắp đóng.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1408"]},{"id":"thien-nguyen-dai-luc","name":"Thiên Nguyên đại lục","cn":"","capDo":"chau","parentId":null,"blurb":"Đại lục Hàn Lập trở lại sau hơn hai tháng bám theo ba người Thiên Bằng qua hải vực.","detail":"Hàn Lập nhìn thấy bờ biển Thiên Nguyên đại lục sau hành trình dài. Khu vực nối với bờ có địa hình đồi núi phức tạp.","theLucLienQuan":["Nhân tộc","Thiên Bằng tộc","Phi Linh tộc"],"nguon":["@c1409","@c1577"]},{"id":"hai-vuc-gan-ban-dao","name":"Hải vực gần bán đảo","cn":"","capDo":"vuc","parentId":null,"blurb":"Tuyến đường biển mà ba người Thiên Bằng bay liên tục hơn hai tháng trước khi tới Thiên Nguyên đại lục.","detail":"Hàn Lập ẩn thân bám theo đoàn Thiên Bằng xuyên qua vùng biển này để xác định đường trở lại đại lục.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1409"]},{"id":"dia-ban-ven-bo-cua-thien-bang-toc","name":"Địa bàn ven bờ của Thiên Bằng tộc","cn":"","capDo":"vuc","parentId":"thien-nguyen-dai-luc","blurb":"Khu vực đồi núi ven biển thuộc quyền quản hạt của Thiên Bằng tộc, nơi đội Xích Dung tổ chức phục kích.","detail":"Phong Khiếu xác nhận vùng này thuộc địa bàn Thiên Bằng tộc. Thiên Minh cùng đồng tộc bao vây ba người Thiên Bằng tại đây và dùng Khốn Ma Võng phong tỏa chiến trường.","theLucLienQuan":["Thiên Bằng tộc","Xích Dung tộc"],"nguon":["@c1409"]},{"id":"day-nui-lanh-dia-thien-bang-toc","name":"Dãy núi lãnh địa Thiên Bằng tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Dãy núi mênh mông thuộc lãnh địa của Thiên Bằng tộc.","detail":"Đoàn Hàn Lập tới nơi này sau một tháng vượt đồi núi, thảo nguyên và rừng rậm. Càng tiến sâu, họ càng gặp nhiều tộc nhân Thiên Bằng và cuối cùng chạm mặt một đội tuần tra hơn ba mươi người.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1412"]},{"id":"thien-bang-thanh-dia","name":"Thiên Bằng Thánh địa","cn":"","capDo":"vuc","parentId":"day-nui-lanh-dia-thien-bang-toc","blurb":"Khu vực trọng yếu của Thiên Bằng tộc nằm sau một lớp cấm chế huyễn thuật.","detail":"Thánh địa có các khu vực cấm, nơi tiếp đãi khách và một thành trì khổng lồ dựng giữa những cự sơn. Lối vào được ngụy trang thành núi non phủ mây đen và lôi quang.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1412"]},{"id":"thanh-thanh-thien-bang-toc","name":"Thánh thành Thiên Bằng tộc","cn":"","aliases":["Thánh thành","Thành thánh Thiên Bằng","Thành thánh Thiên Bằng tộc"],"capDo":"thanh","parentId":"thien-bang-thanh-dia","blurb":"Tòa thành khổng lồ nằm giữa các cự sơn trong Thiên Bằng Thánh địa.","detail":"Thành được xây giữa những ngọn núi cao khoảng vạn trượng, có tường gạch trắng và màn sáng bao phủ. Nhiều cột lớn đủ màu tạo thành các lối ra vào trên không cho tộc nhân Thiên Bằng.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1412","@c1422"]},{"id":"van-bang-cac","name":"Vạn Bằng các","cn":"","capDo":"khac","parentId":"thien-bang-thanh-dia","blurb":"Nơi các trưởng lão Thiên Bằng triệu những người vừa trở về tới gặp.","detail":"Phong Khiếu, Bạch Lôi và người đồng hành được lệnh phải lập tức tới Vạn Bằng các sau khi gặp đội tuần tra trong lãnh địa.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1412"]},{"id":"phong-linh-thap","name":"Phong Linh tháp","cn":"","capDo":"khac","parentId":"thanh-thanh-thien-bang-toc","blurb":"Cấm địa hình cự tháp bát lăng nằm trong Thánh thành Thiên Bằng tộc.","detail":"Tòa tháp cao khoảng sáu bảy trăm trượng, trên bề mặt có những ký hiệu tỏa hắc khí. Một khối tinh thể trên đỉnh phát hào quang bảy màu phong tỏa hắc khí, còn khu vực hơn trăm trượng quanh màn sáng không có Thiên Bằng nhân nào dám tới gần.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1413"]},{"id":"khai-thien-tru","name":"Khai Thiên trụ","cn":"","capDo":"khac","parentId":"thanh-thanh-thien-bang-toc","blurb":"Cự trụ nằm gần lối vào Thánh thành Thiên Bằng tộc.","detail":"Khu vực quanh trụ chịu ảnh hưởng của cấm chế phòng hộ. Khi cách trụ khoảng bốn năm mươi trượng, người bay không còn bị cấm chế tác động và có thể ra vào Thánh thành.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1413"]},{"id":"quy-tan-quan","name":"Quý Tân quán","cn":"","capDo":"khac","parentId":"thanh-thanh-thien-bang-toc","blurb":"Nơi chuyên tiếp đón khách quý trong Thánh thành Thiên Bằng tộc.","detail":"Quý Tân quán được bố trí tại nhiều khu vực trong thành, cung cấp chỗ ở và bản đồ đặc chế cho khách. Hàn Lập được Hóa Vũ đưa tới một cơ sở và giao cho Bạch Thúy tiếp đãi.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1413","@c1428"]},{"id":"dai-dien-giao-dich-thanh-thanh","name":"Đại điện giao dịch","cn":"","capDo":"khac","parentId":"thanh-thanh-thien-bang-toc","blurb":"Khu trao đổi hàng hóa nằm trong lòng một ngọn núi ở rìa Thánh thành.","detail":"Phương thức mua bán tại đây không khác nhiều so với Nhân tộc. Hàn Lập chọn nơi này làm điểm đến đầu tiên để thu thập tài liệu về Phi Linh tộc.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1413"]},{"id":"truyen-linh-dien","name":"Truyện Linh điện","cn":"","capDo":"khac","parentId":"thanh-thanh-thien-bang-toc","blurb":"Điện đường cung cấp công pháp cho tầng lớp tộc nhân cao cấp của Thiên Bằng tộc.","detail":"Địa điểm này được đánh dấu trên bản đồ Thánh thành và thu hút sự chú ý của Hàn Lập trong quá trình tìm kiếm tài liệu quý.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1413"]},{"id":"phong-hinh-tru-cua-dai-truong-lao","name":"Phòng hình trụ của đại trưởng lão","cn":"","aliases":[],"capDo":"khac","parentId":"thanh-thanh-thien-bang-toc","blurb":"Nơi Kim Duyệt tiếp xúc riêng với Hàn Lập và giải thích tình thế của Thiên Bằng tộc.","detail":"Gian phòng cao khoảng mười trượng, đứng riêng lẻ trong Thánh thành Thiên Bằng tộc và chỉ bày ghế đá cùng bàn đá. Tại đây Kim Duyệt vạch trần thân phận Hàn Lập, kiểm tra Phong Lôi Sí và đề nghị hắn làm Thánh tử.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1415"]},{"id":"nha-sach-trong-thanh-thanh","name":"Nhà sách trong thành thánh","cn":"","capDo":"khac","parentId":"thanh-thanh-thien-bang-toc","blurb":"Một kiến trúc cao lớn trong thành thánh Thiên Bằng tộc, lưu giữ lượng lớn sách vở.","detail":"Hàn Lập ở đây suốt một ngày một đêm và đọc gần nửa lượng sách nhằm tìm hiểu tình hình Thiên Bằng tộc trước khi trả lời đề nghị của Kim Duyệt.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1416"]},{"id":"quang-truong-giao-dich-thien-bang","name":"Quảng trường giao dịch Thiên Bằng","cn":"","capDo":"khac","parentId":null,"blurb":"Quảng trường giao dịch rộng vài trăm trượng của Thiên Bằng tộc.","detail":"Xung quanh quảng trường có nhiều cửa tiệm, còn chính giữa đặt cột đá dùng để đăng và tra cứu tin mua bán vật phẩm.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1417"]},{"id":"tang-chin-dai-dien-giao-dich","name":"Tầng thứ chín đại điện giao dịch","cn":"","capDo":"khac","parentId":"dai-dien-giao-dich-thanh-thanh","blurb":"Tầng cao của đại điện giao dịch, nơi đặt Vạn Lôi Phường.","detail":"Khu vực này thưa người hơn các tầng dưới, chỉ có khoảng hai ba mươi người Thiên Bằng khi Hàn Lập tới tìm địa điểm liên quan đến Thanh La quả.","theLucLienQuan":["Thiên Bằng tộc","Vạn Lôi Phường"],"nguon":["@c1417"]},{"id":"van-loi-phuong-map","name":"Vạn Lôi Phường","cn":"","capDo":"khac","parentId":"tang-chin-dai-dien-giao-dich","blurb":"Cửa hàng hai tầng nằm tại góc tầng thứ chín của đại điện giao dịch.","detail":"Cửa tiệm có quầng sáng xanh che lối vào. Gian ngoài rộng khoảng ba bốn mươi trượng, bố trí bàn gỗ đen, ghế vàng và các giá gỗ bày ít hàng hóa.","theLucLienQuan":["Vạn Lôi Phường","Thiên Bằng tộc"],"nguon":["@c1417"]},{"id":"cua-tiem-ngu-huynh","name":"Cửa tiệm của Ngư huynh","cn":"","capDo":"khac","parentId":"dai-dien-giao-dich-thanh-thanh","blurb":"Cửa tiệm do Điếm chủ họ Ngư trông coi trong đại điện giao dịch.","detail":"Nơi bày Tử Tiên Mộc và Thanh La Quả, đồng thời là địa điểm Điếm chủ họ Ngư hẹn Hàn Lập quay lại sau bốn ngày để hỗ trợ thu phục linh thú.","theLucLienQuan":[],"nguon":["@c1418"]},{"id":"lau-cac-cua-kim-duyet","name":"Lầu các của Kim Duyệt","cn":"","capDo":"khac","parentId":"thanh-thanh-thien-bang-toc","blurb":"Nơi ở và nghị sự của đại trưởng lão Kim Duyệt trong thánh thành Thiên Bằng tộc.","detail":"Hàn Lập thương lượng tại đây với Kim Duyệt, Tư trưởng lão và mỹ phụ về điều kiện giúp Thiên Bằng tộc vượt qua thí luyện.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1419"]},{"id":"quang-truong-khai-linh-trong-thanh-thanh","name":"Quảng trường khai linh trong thánh thành","cn":"","capDo":"khac","parentId":"thanh-thanh-thien-bang-toc","blurb":"Quảng trường tròn rộng vài dặm, nơi Thiên Bằng tộc tổ chức nghi thức khai linh cho Hàn Lập.","detail":"Quảng trường được bao quanh bởi tường đá cao khoảng trăm trượng và hàng trăm tượng Ô Bằng phát ra ánh sáng bảy màu. Chính giữa quảng trường đặt một ngọc đài dùng cho nghi thức dung hợp chân huyết và luyện hóa xá lợi.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1419"]},{"id":"ngoc-dai-bach-ngoc","name":"Ngọc đài bạch ngọc","cn":"","capDo":"khac","parentId":"quang-truong-khai-linh-trong-thanh-thanh","blurb":"Tế đàn nằm ở trung tâm quảng trường khai linh của Thiên Bằng tộc.","detail":"Hàn Lập được đưa tới đây gặp Kim Duyệt cùng các trưởng lão để chuẩn bị dung hợp Côn Bằng chân huyết, luyện hóa Côn Bằng xá lợi và học thuật biến thân.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1419"]},{"id":"dia-uyen","name":"Địa uyên","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực nguy hiểm có yêu vật là sinh tử đại địch của Phi Linh tộc.","detail":"Tình trạng địa uyên gần đây không ổn định được các phân chi dùng làm lý do đề nghị đẩy sớm kỳ thí luyện.","theLucLienQuan":["Phi Linh tộc","Thiên Bằng tộc"],"nguon":["@c1420","@c1447","@c1474","@c1519"]},{"id":"khu-vuc-quan-hat-cua-thien-bang-toc","name":"Khu vực quản hạt của Thiên Bằng tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Địa bàn do Thiên Bằng tộc quản lý.","detail":"Người của các tộc khác đang xâm nhập khu vực này để bắt người và cướp của, khiến Kim Duyệt ra lệnh chia quân truy sát toàn bộ những kẻ lợi dụng lúc Thiên Bằng tộc suy yếu.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1420"]},{"id":"kien-truc-bi-mat-cua-diem-chu-ho-ngu","name":"Kiến trúc bí mật của điếm chủ họ Ngư","cn":"","capDo":"khac","parentId":"thanh-thanh-thien-bang-toc","blurb":"Một kiến trúc biệt lập trong khu vực hẻo lánh của thánh thành, do hai đệ tử Kết Đan canh giữ.","detail":"Tòa nhà có hai tầng và cao hơn ba mươi trượng. Căn phòng bên trong treo nhiều cổ họa yêu thú và sơn thủy; một bức sơn thủy được dùng làm lối vào động thiên khi kết hợp với Tu Di Động Thiên Đồ.","theLucLienQuan":["Vạn Lôi Phường"],"nguon":["@c1422"]},{"id":"dong-thien-trong-tu-di-dong-thien-do","name":"Động thiên trong Tu Di Động Thiên Đồ","cn":"","aliases":["Tu Di không gian","Tu Di không gian trong Tu Di Động Thiên Đồ"],"capDo":"gioi-nho","parentId":null,"blurb":"Không gian độc lập nằm trong Tu Di Động Thiên Đồ có tỳ vết của điếm chủ họ Ngư.","detail":"Điếm chủ bố trí linh thú cần hàng phục bên trong động thiên. Hàn Lập, thanh niên sắc mặt âm nhu và đại hán hắc giáp được đưa vào đây để hợp sức thi triển thần thông lôi điện.","theLucLienQuan":["Vạn Lôi Phường","Ngũ Quang Tộc"],"nguon":["@c1422"]},{"id":"cac-lau-giam-loi-thu","name":"Các lâu giam Lôi thú","cn":"","capDo":"khac","parentId":"dong-thien-trong-tu-di-dong-thien-do","blurb":"Tòa lầu cổ ba tầng nằm trong động thiên của Tu Di Động Thiên Đồ, được dùng làm nơi giam giữ Lôi thú.","detail":"Tòa các lâu cao hơn trăm trượng. Tầng hai rộng khoảng ba trăm trượng, có tám mươi mốt cột đồng tạo thành Phược Lôi Tiêu Quang đại trận và lưới điện màu đen bao quanh Lôi thú.","theLucLienQuan":[],"nguon":["@c1423"]},{"id":"noi-toa-hoa-cua-cao-nhan-di-toc","name":"Nơi tọa hóa của cao nhân dị tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm điếm chủ họ Ngư tìm thấy một phần bí thuật bồi dục linh thú được truyền xuống từ Chân Tiên giới.","detail":"Tại nơi tọa hóa của một cao nhân dị tộc, điếm chủ họ Ngư tình cờ thu được một phần truyền thừa bồi dục linh thú. Lôi thú thôi sinh bí thuật là nội dung nguyên vẹn duy nhất còn lại trong phần truyền thừa này.","theLucLienQuan":[],"nguon":["@c1424"]},{"id":"chan-tien-gioi","name":"Chân Tiên giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện được nhắc đến như nguồn gốc của phần bí thuật bồi dục linh thú mà điếm chủ họ Ngư thu được.","detail":"Một phần bí thuật bồi dục linh thú từ Chân Tiên giới đã được lưu truyền xuống và rơi vào tay điếm chủ họ Ngư tại nơi tọa hóa của một cao nhân dị tộc.","theLucLienQuan":[],"nguon":["@c1424","@c1718"]},{"id":"tang-hai-dia-diem-giam-loi-thu","name":"Tầng hai của địa điểm giam Lôi thú","cn":"","capDo":"khac","parentId":"cac-lau-giam-loi-thu","blurb":"Tầng đặt đồng trụ và cấm chế dùng để giam giữ Lôi thú.","detail":"Ngũ sắc điện hồ có thể đánh xuyên mặt đất tầng này. Hàn Lập phá đồng trụ cùng các cấm chế tại đây rồi chủ động áp sát lối ra ngoài để giữ đường lui.","theLucLienQuan":[],"nguon":["@c1426"]},{"id":"toa-thanh-co-bang-bach-thach","name":"Tòa thành cổ bằng bạch thạch","cn":"","capDo":"thanh","parentId":"thanh-thanh-thien-bang-toc","blurb":"Tòa thành cổ xây bằng bạch thạch, nơi Bạch Bích đưa Hàn Lập tới gặp các trưởng lão và Thánh tử.","detail":"Sau vài canh giờ di chuyển, Bạch Bích dẫn Hàn Lập tới tòa thành cổ này. Bên trong có đại điện dùng cho cuộc tập trung bàn về Uyên thí luyện và kế hoạch lập Thánh tử thứ ba.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1428"]},{"id":"cu-phong","name":"Cự phong","cn":"","capDo":"khac","parentId":null,"blurb":"Ngọn núi khổng lồ có sân đá xanh trên đỉnh, nơi hơn một trăm người Phi Linh tộc tụ tập.","detail":"Sau ba tháng kể từ khi Hàn Lập rời Thánh thành, các thành viên nhiều chi Phi Linh tộc tập trung trên sân đá xanh ở đỉnh cự phong và chứng kiến một cuộc giao đấu.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1429"]},{"id":"ngoc-hoang-dinh","name":"Ngọc Hoàng Đỉnh","cn":"","capDo":"khac","parentId":null,"blurb":"Cự phong tổ chức thịnh hội của các phân tộc Phi Linh.","detail":"Trên đỉnh có quần thể kiến trúc, đại điện màu xanh ẩn trong sương trắng và một cây cầu bảy sắc. Khi khách bước lên, cây cầu phát sáng và dịch chuyển cả đoàn sang đầu bên kia trong chớp mắt; trên không quanh núi còn có hàng trăm cự cầm và phi trùng khổng lồ.","theLucLienQuan":["Phi Linh tộc","Hội liên tịch các trưởng lão"],"nguon":["@c1430"]},{"id":"phia-bac-lanh-dia-phi-linh-toc","name":"Phía bắc lãnh địa Phi Linh tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực phía bắc nơi Quỷ Diện tộc và Độc Cưu tộc đang xử lý việc quan trọng.","detail":"Công việc tại khu vực này khiến Quỷ Diện tộc và Độc Cưu tộc chưa thể đến Ngọc Hoàng Đỉnh trước khi Địa Uyên mở ra.","theLucLienQuan":["Quỷ Diện tộc","Độc Cưu tộc","Phi Linh tộc"],"nguon":["@c1430"]},{"id":"giac-ky-trang","name":"Giác kỹ tràng","cn":"","aliases":["Kỹ tràng","Giác kỹ tràng phía Đông"],"capDo":"khac","parentId":"ngoc-hoang-dinh","blurb":"Khu tỷ thí nằm ở phía Đông Ngọc Hoàng Đỉnh. Đây là nơi duy nhất trong khu vực cho phép các Thánh tử tự do giao đấu.","detail":"Lôi Lan được dẫn tới đây cùng Hồng Sa. Chúc Âm Tử và Xích Thiên lợi dụng việc đó để dụ Hàn Lập xuất hiện, nhằm thăm dò thần thông của hắn trước Uyên thí luyện.","theLucLienQuan":["Xích Dung tộc","Thiên Bằng tộc","Ngũ Quang tộc"],"nguon":["@c1431"]},{"id":"cao-nguyen-hoang-tho","name":"Cao nguyên hoàng thổ","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực rộng lớn mà đoàn thí luyện Phi Linh tộc bay qua trên đường tới địa uyên.","detail":"Đoàn khoảng nghìn cự cầm và phi trùng chở người bay qua cao nguyên hoàng thổ trong hành trình từ Ngọc Hoàng đỉnh tới cửa vào địa uyên.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1434"]},{"id":"cua-vao-dia-uyen","name":"Cửa vào địa uyên","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Điểm đến của đoàn thí luyện Phi Linh tộc trong hành trình rời Ngọc Hoàng đỉnh.","detail":"Khu vực tiếp cận cửa vào địa uyên có một bức tường khổng lồ, những trụ bạch ngọc khắc phù văn và lực lượng Phi Linh tộc do Kim Phong dẫn ra nghênh đón.","theLucLienQuan":["Phi Linh tộc","Hội liên tịch các trưởng lão"],"nguon":["@c1434"]},{"id":"buc-tuong-gan-dia-uyen","name":"Bức tường gần địa uyên","cn":"","capDo":"khac","parentId":"cua-vao-dia-uyen","blurb":"Tuyến phòng vệ khổng lồ nằm gần cửa vào địa uyên.","detail":"Bức tường cao khoảng ba đến bốn trăm trượng và kéo dài tới mức không nhìn thấy điểm cuối. Cứ mỗi trăm trượng lại có một trụ bạch ngọc mang phù văn huyền ảo, còn lực lượng của Kim Phong trấn giữ tại khu vực này.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1434"]},{"id":"lau-cac-hinh-tru","name":"Lầu các hình trụ","cn":"","capDo":"khac","parentId":"buc-tuong-gan-dia-uyen","blurb":"Công trình hình trụ nằm cạnh bức tường phòng vệ gần địa uyên.","detail":"Lầu các cao khoảng ba đến bốn mươi trượng và được ước tính có thể chứa vài nghìn người.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1434"]},{"id":"khu-tru-quan-dia-uyen","name":"Khu trú quân bên ngoài Địa Uyên","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Khu vực tập kết của hàng vạn Uyên thủ vệ mặc sát giáp bên ngoài Địa Uyên.","detail":"Nơi đây có nhiều công trình quy mô lớn và tập trung Uyên thủ vệ với tu vi từ ngoài Kết Đan đến Luyện Hư. Quy mô kiến trúc khiến Hàn Lập cho rằng vẫn còn giáp sĩ đóng tại những nơi chưa lộ diện.","theLucLienQuan":["Uyên thủ vệ"],"nguon":["@c1435"]},{"id":"dai-lau-nghi-truoc-thi-luyen","name":"Đại lâu dành cho đoàn thí luyện","cn":"","capDo":"khac","parentId":"khu-tru-quan-dia-uyen","blurb":"Khu nhà tạm dành cho các đoàn dự thí luyện nghỉ lại trước khi tiến vào Địa Uyên.","detail":"Các đệ tử được phân vào những đại lâu để khôi phục tinh thần và pháp lực trước khi thí luyện bắt đầu vào ngày hôm sau. Đoàn Thiên Bằng tộc ở chung một lầu các, ba thánh tử nghỉ riêng còn Kim Duyệt và Thạch trưởng lão canh tầng một.","theLucLienQuan":["Hội liên tịch các trưởng lão","Thiên Bằng tộc"],"nguon":["@c1435"]},{"id":"phong-ma-mon","name":"Phong Ma môn","cn":"","capDo":"khac","parentId":"thanh-thanh-phi-linh-toc","blurb":"Cánh cửa khổng lồ trên tường thành, được mở để thông ra khu vực dẫn tới Địa Uyên.","detail":"Phong Ma môn cao hơn mười trượng, tỏa khí lạnh và trông như làm từ bạch ngọc. Cánh cửa được pháp trận bạc triệu xuất, sau đó mở lối cho hơn trăm thánh tử rời thành.","theLucLienQuan":["Phi Linh tộc","Hội liên tịch các trưởng lão"],"nguon":["@c1436"]},{"id":"van-dam-suong-mu","name":"Vạn dặm sương mù","cn":"","capDo":"vuc","parentId":"dia-uyen","blurb":"Vùng đất hoang vu nằm sau Phong Ma môn, trên đường tiến vào Địa Uyên.","detail":"Khu vực có mặt đất và đá đen không cây cỏ, phía trên phủ tầng bụi trắng dày đặc. Khoảng trống giữa mặt đất và tầng bụi chỉ cao ba bốn mươi trượng, thường xuyên vang tiếng xé gió; gió bụi âm tà khiến da thịt đau như bị dao cắt.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1436"]},{"id":"dia-uyen-tang-thu-nhat","name":"Địa Uyên tầng thứ nhất","cn":"","capDo":"gioi-nho","parentId":"dia-uyen","blurb":"Tầng đầu tiên của Địa Uyên, có mặt đất đen vàng, cây cối khổng lồ và nhiều loài chim thú bị hắc ám khí tức ảnh hưởng.","detail":"Sau khi hạ xuống nhiều ngàn trượng qua màn sương xám đen, đội Hàn Lập đặt chân tới tầng thứ nhất. Nơi đây có cây cối khổng lồ, quái điểu và nhiều mãnh thú hung bạo, nhưng phần lớn yêu vật chỉ thuộc cấp thấp. Minh Diễm quả gần như không xuất hiện tại tầng này.","theLucLienQuan":["Phi Linh tộc","Thiên Bằng tộc"],"nguon":["@c1437"]},{"id":"cac-cua-vao-tang-thu-hai","name":"Các cửa vào tầng thứ hai","cn":"","capDo":"khac","parentId":"dia-uyen-tang-thu-nhat","blurb":"Những lối từ tầng thứ nhất dẫn xuống tầng thứ hai của Địa Uyên, trong đó chỉ hơn mười cửa được xem là an toàn.","detail":"Theo kinh nghiệm thí luyện của Thiên Bằng tộc, số lối an toàn để xuống tầng hai rất hạn chế. Hàn Lập chọn một cửa vào hẻo lánh nhằm giảm nguy cơ chạm trán những đội thánh tử có ác ý, dù hành trình sẽ mất nhiều thời gian hơn.","theLucLienQuan":["Thiên Bằng tộc","Phi Linh tộc"],"nguon":["@c1437"]},{"id":"cu-tuong-ngoai-dia-uyen","name":"Cự tường ngoài Địa Uyên","cn":"","capDo":"khac","parentId":"cua-vao-dia-uyen","blurb":"Điểm tập kết và xuất phát của hơn trăm thánh tử Phi Linh tộc trước khi tiến vào Địa Uyên.","detail":"Các đội thánh tử tập trung bên ngoài cự tường rồi lần lượt chia đường rời đi. Sau khi mọi người xuất phát, cánh cửa trên tường khép lại, lưu chuyển quang mang ngũ sắc và biến mất.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1437"]},{"id":"khu-bich-dong-cuoi-tang-thu-nhat","name":"Khu bích động cuối tầng thứ nhất","cn":"","capDo":"khac","parentId":"dia-uyen-tang-thu-nhat","blurb":"Khu vực gần cuối tầng thứ nhất của Địa uyên, có thạch bích đen cao như nóc một hang động khổng lồ.","detail":"Thạch bích đen nằm ở độ cao khoảng vạn trượng; cây cối và khoáng chất tại đây phát ra quang mang kỳ dị. Hắc vụ, hàn phong xuất hiện từng đợt và lực áp chế thần niệm rất mạnh, khiến thần niệm của Hàn Lập chỉ có thể vươn ra khoảng mười trượng.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1438"]},{"id":"sa-mac-xam-bac","name":"Sa mạc xám bạc","cn":"","capDo":"khac","parentId":"dia-uyen-tang-thu-nhat","blurb":"Sa mạc hoang vu rộng ít nhất mấy vạn dặm, xuất hiện tại vị trí vốn được pháp bàn đánh dấu là một con sông ngầm lớn.","detail":"Cả ba pháp bàn của Hàn Lập, Bạch Bích và Lôi Lan đều cho thấy khu vực này phải là một con sông dưới mặt đất, nhưng địa hình thực tế đã biến thành sa mạc xám bạc. Nguyên nhân của biến đổi chưa được xác định và cả nhóm quyết định tiếp tục hành trình thay vì dừng lại điều tra.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1438"]},{"id":"oc-dao-trong-sa-mac-xam-bac","name":"Ốc đảo trong sa mạc xám bạc","cn":"","capDo":"khac","parentId":"sa-mac-xam-bac","blurb":"Ốc đảo được phát hiện từ xa trong sa mạc xám bạc, nơi có mùi máu tanh và thiên địa nguyên khí hỗn loạn.","detail":"Hàn Lập dùng linh mục nhìn thấy địa điểm giống một ốc đảo và nhận ra mùi máu tanh. Lôi Lan xác nhận thiên địa nguyên khí tại đó đang hỗn loạn như vừa có người thi triển thần thông, vì vậy đề nghị cả nhóm tới kiểm tra.","theLucLienQuan":[],"nguon":["@c1438"]},{"id":"oc-dao-huyen-hoa","name":"Ốc đảo huyễn hóa","cn":"","capDo":"khac","parentId":"dia-uyen-tang-thu-nhat","blurb":"Ốc đảo đen vàng có huyết đàm và nhiều xác uyên thú, thực chất là hình thái huyễn hóa của một Cự linh hoa.","detail":"Khu vực nằm cách vị trí ban đầu của nhóm Hàn Lập hơn mười dặm, có cây cỏ thấp, huyết đàm và hơn mười thi thể uyên thú. Sau khi bị phát hiện, toàn bộ ốc đảo hiện nguyên hình thành Cự linh hoa khổng lồ.","theLucLienQuan":[],"nguon":["@c1439"]},{"id":"huyet-dam","name":"Huyết đàm","cn":"","capDo":"khac","parentId":"oc-dao-huyen-hoa","blurb":"Thủy đàm rộng hơn mười trượng nằm giữa ốc đảo huyễn hóa, chứa máu chảy ra từ các xác uyên thú.","detail":"Huyết đàm chứa chất lỏng đỏ đậm và tương ứng với tâm hoa đỏ như máu của Cự linh hoa khi yêu vật hiện nguyên hình.","theLucLienQuan":[],"nguon":["@c1439"]},{"id":"tang-ba-dia-uyen","name":"Tầng ba Địa Uyên","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Tầng sâu của Địa Uyên mà nữ tử thần bí tuyên bố sẽ trở về.","detail":"Nữ tử thần bí giao nhiệm vụ cho Oán viên thú rồi dùng cự hoa và pháp trận dịch chuyển để trở về tầng ba.","theLucLienQuan":[],"nguon":["@c1440"]},{"id":"sa-mac-tang-thu-nhat","name":"Sa mạc tầng thứ nhất","cn":"","capDo":"khac","parentId":"dia-uyen-tang-thu-nhat","blurb":"Khu sa mạc nơi nữ tử thần bí rời đi và Oán viên thú lộ nguyên hình.","detail":"Oán viên thú hấp thu hài cốt cự linh hoa tại đây, sau đó dùng hư ảnh cùng lục vụ giết một thánh tử Phi Linh tộc. Đoàn Hàn Lập đã rời khỏi sa mạc trước khi yêu thú bắt đầu truy đuổi.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1440"]},{"id":"hap-coc-gan-duong-vao-tang-thu-nhat","name":"Hạp cốc gần đường vào tầng thứ nhất","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Hạp cốc nằm gần đường vào tầng thứ nhất của Địa Uyên.","detail":"Chúc Âm Tử dẫn bảy tám thánh tử Xích Dung tộc chậm rãi tiến vào khu vực này.","theLucLienQuan":["Xích Dung tộc"],"nguon":["@c1440"]},{"id":"day-nui-den-bi-an","name":"Dãy núi đen bí ẩn","cn":"","aliases":[],"capDo":"khac","parentId":"dia-uyen-tang-thu-nhat","blurb":"Dãy núi đen khổng lồ xuất hiện tại nơi trên bản đồ vốn được đánh dấu là bình nguyên.","detail":"Dấu vết tại mặt đất cho thấy dãy núi mới xuất hiện trong khoảng gần trăm năm và có thể đã bị di chuyển tới bằng đại pháp lực, bảo vật hoặc pháp trận. Khu vực này khiến Minh Hồn Châu nóng lên và làm Đề Hồn Thú liên tục gầm nhẹ, nên Hàn Lập quyết định không đi xuyên qua.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1441"]},{"id":"dia-uyen-tang-thu-hai","name":"Địa Uyên tầng thứ hai","cn":"","aliases":[],"capDo":"vuc","parentId":"dia-uyen","blurb":"Tầng kế tiếp mà các đội Phi Linh tộc đang tìm đường tiến xuống trong cuộc thí luyện.","detail":"Đội Xích Dung tộc phải đi dọc hạp cốc trong khoảng một ngày một đêm để tới tầng này. Một số đội khác đã tìm thấy cửa xuống, còn nhóm Hàn Lập chọn một cửa xa để tránh các nhánh Thiên Hạt Tộc.","theLucLienQuan":["Phi Linh tộc","Xích Dung tộc","Thiên Bằng tộc","Thiên Hạt Tộc"],"nguon":["@c1441"]},{"id":"dia-uyen-tang-thu-bon","name":"Địa Uyên tầng thứ bốn","cn":"","aliases":[],"capDo":"vuc","parentId":"dia-uyen","blurb":"Một tầng sâu của Địa Uyên được Ngao Thanh Chước nhắc tới như nơi có nhiều Minh Diễm Quả.","detail":"Ngao Thanh Chước dự tính xuống tầng thứ bốn tìm kiếm nếu đội của nàng không giành được Minh Diễm Quả tại các tầng phía trên.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1441"]},{"id":"uyen-phong-dai","name":"Uyên Phong Đái","cn":"","aliases":[],"capDo":"vuc","parentId":"dia-uyen-tang-thu-nhat","blurb":"Vùng cấm lạnh giá nằm ở một phía của dãy núi đen bí ẩn.","detail":"Khí lạnh tại Uyên Phong Đái có thể biến người xâm nhập thành băng trụ và giam họ vĩnh viễn tại đó. Mức độ nguy hiểm khiến nhóm Hàn Lập không thể tùy tiện chọn hướng vòng qua khu vực này.","theLucLienQuan":[],"nguon":["@c1441"]},{"id":"sao-huyet-hac-uyen-phi-nghi","name":"Sào huyệt Hắc Uyên Phi Nghĩ","cn":"","aliases":[],"capDo":"khac","parentId":"dia-uyen-tang-thu-nhat","blurb":"Sào huyệt của hơn mười vạn Hắc Uyên Phi Nghĩ, nằm ở phía còn lại của dãy núi đen.","detail":"Số lượng Hắc Uyên Phi Nghĩ tại đây vượt quá mười vạn con. Với tu vi hiện tại, nhóm Hàn Lập đánh giá việc xông qua khu vực gần như cửu tử nhất sinh.","theLucLienQuan":[],"nguon":["@c1441"]},{"id":"hap-coc-dan-xuong-tang-hai","name":"Hạp cốc dẫn xuống tầng hai","cn":"","aliases":[],"capDo":"khac","parentId":"dia-uyen-tang-thu-nhat","blurb":"Tuyến đường tối tăm được đội Xích Dung tộc sử dụng để tiến xuống tầng thứ hai của Địa Uyên.","detail":"Hạp cốc có đàn dơi mắt đỏ cản đường và cần khoảng một ngày một đêm phi hành để đi hết. Chúc Âm Tử tiêu diệt đàn dơi rồi tiếp tục dẫn đội tiến sâu xuống dưới.","theLucLienQuan":["Xích Dung tộc"],"nguon":["@c1441"]},{"id":"son-coc-phu-suong","name":"Sơn cốc phủ sương","cn":"","capDo":"khac","parentId":"dia-uyen-tang-thu-nhat","blurb":"Sơn cốc hẻo lánh phủ sương mù, có khe núi lớn dẫn xuống lòng đất.","detail":"Nhóm Hàn Lập chọn đường qua sơn cốc vì nơi này hẻo lánh và ít có khả năng bị phục kích. Sau khi vượt qua phi xà trong sương mù, họ tiến vào khe núi thông xuống tầng hai.","theLucLienQuan":[],"nguon":["@c1442"]},{"id":"dia-uyen-chi-phong","name":"Địa Uyên Chi Phong","cn":"","capDo":"khac","parentId":"son-coc-phu-suong","blurb":"Thông đạo có hắc sắc kình phong cực lạnh nằm trên đường từ tầng một xuống tầng hai Địa Uyên.","detail":"Luồng kình phong trong thông đạo có thể khiến thạch bích kết thành băng đen. Lôi Lan và Bạch Bích suýt bị nhốt lại, phải nhờ Hàn Lập ra tay mới vượt qua được.","theLucLienQuan":[],"nguon":["@c1442"]},{"id":"tang-sau-dia-uyen","name":"Tầng sáu Địa Uyên","cn":"","capDo":"vuc","parentId":null,"blurb":"Tầng sâu có cung điện phát lục quang và hồ nước được nhiều pháp trận bao quanh.","detail":"Lão phụ nhân tóc trắng chỉ huy hai nữ tử dùng minh hỏa luyện bóng người màu đen trong hồ sâu tại đây.","theLucLienQuan":[],"nguon":["@c1444"]},{"id":"tang-hai-dia-uyen","name":"Tầng hai Địa Uyên","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực Hàn Lập, Lôi Lan và Bạch Bích đang vượt qua trong hành trình thí luyện.","detail":"Nơi đây không còn yêu thú phổ thông nhưng vẫn có yêu vật cấp thấp; Hàn Lập dùng linh mục dò đường và dẫn hai người đồng hành vòng tránh chúng.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c1444"]},{"id":"ba-tang-tren-dia-uyen","name":"Ba tầng trên Địa Uyên","cn":"","capDo":"vuc","parentId":null,"blurb":"Phạm vi các thánh tử Phi Linh Tộc tạm thời được tự do hoạt động.","detail":"Những tồn tại dưới sâu không định can thiệp người thí luyện trong khu vực này nếu họ không cản trở đại sự hoặc vượt xuống dưới tầng bốn.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c1444"]},{"id":"tang-bon-dia-uyen","name":"Tầng bốn Địa Uyên","cn":"","capDo":"vuc","parentId":null,"blurb":"Ranh giới mà các thánh tử Phi Linh Tộc không được tiến xuống nếu muốn tránh bị can thiệp.","detail":"Địa Huyết coi việc đi xuống dưới tầng này là vượt khỏi phạm vi được dung túng trong thời gian đại sự đang ở thời điểm mấu chốt.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c1444"]},{"id":"vung-nui-xanh-biec","name":"Vùng núi xanh biếc","cn":"","capDo":"khac","parentId":"tang-hai-dia-uyen","blurb":"Vùng núi mà đoàn Hàn Lập tiến vào trong ngày thứ hai của hành trình tại tầng hai.","detail":"Khi bay qua phía sau núi, đoàn Hàn Lập gặp bốn đạo thúy mang bất ngờ áp sát từ phía trước và phía sau.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c1444"]},{"id":"nui-non-than-bi","name":"Núi non thần bí","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng núi có tế đàn cao hơn trăm trượng và một nhãn cầu khổng lồ được thờ phụng.","detail":"Nhãn cầu trên tế đàn phun vô số sợi tơ hút hôi khí, còn một người cao lớn khoác áo choàng đen đứng bất động phía dưới.","theLucLienQuan":[],"nguon":["@c1444"]},{"id":"bang-sat-chi-dia","name":"Băng Sát Chi Địa","cn":"","capDo":"vuc","parentId":"tang-hai-dia-uyen","blurb":"Vùng băng tuyết màu đen nổi danh tại tầng hai Địa Uyên.","detail":"Nơi này có gió lạnh dữ dội, tập trung nhiều băng sát yêu vật cấp thấp và lưu truyền tin đồn về băng sát yêu vương. Nhóm Hàn Lập tiến vào trong lúc yêu triều tại Địa Uyên sắp bộc phát.","theLucLienQuan":["Thiên Bằng Tộc","Dạ Lục Tộc"],"nguon":["@c1446"]},{"id":"dong-quat-dan-xuong-tang-ba","name":"Động quật dẫn xuống tầng ba","cn":"","capDo":"khac","parentId":"tang-hai-dia-uyen","blurb":"Động quật tối đen nằm giữa bãi loạn thạch và thông xuống tầng ba Địa Uyên.","detail":"Động quật sâu hơn trăm trượng, được các thánh tử Xích Dung Tộc canh giữ và dùng làm nơi bố trí phục kích nhóm Thiên Bằng Tộc.","theLucLienQuan":["Xích Dung Tộc","Thiên Bằng Tộc"],"nguon":["@c1446"]},{"id":"khu-rung-co-cu-tru-mau-vang","name":"Khu rừng có cự trụ màu vàng","cn":"","capDo":"khac","parentId":"tang-hai-dia-uyen","blurb":"Khu rừng xanh biếc tại tầng hai Địa Uyên có một cự trụ màu vàng khổng lồ.","detail":"Cự trụ có đường kính rất lớn và vùng hơn mười dặm quanh trụ không có cỏ. Một đoàn Phi Linh Tộc bị ngàn vạn phi nga vàng kim vây hãm gần nơi này.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c1446"]},{"id":"dai-dien-go-den","name":"Đại điện gỗ đen","cn":"","capDo":"khac","parentId":"tang-ba-dia-uyen","blurb":"Đại điện dựng từ vô số gỗ đen tại tầng ba Địa Uyên.","detail":"Đây là nơi Mộc Thanh ngồi trên kim sắc đại hoa, triệu kiến Huyết Độc và nghe các thuộc hạ báo cáo tiến độ tìm kiếm huyết thực cho cuộc tế tự.","theLucLienQuan":["Huyết Giao"],"nguon":["@c1452"]},{"id":"tang-hai-bac-uyen","name":"Tầng hai Bắc Uyên","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực nơi bốn thánh tử Phi Linh tộc gặp người trong huyết vụ.","detail":"Bốn thánh tử Phi Linh tộc giao chiến với đàn hắc sắc độc hạt tại đây rồi bị người trong huyết vụ dùng Thiên Cương Huyết Lôi diệt sát.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1453"]},{"id":"hu-diep-lam","name":"Hủ Diệp lâm","cn":"","capDo":"khac","parentId":"tang-hai-dia-uyen","blurb":"Khu rừng thấp mọc hủ diệp thụ, hình thành tại nơi hắc ám uế khí ngưng kết ở tầng hai Địa Uyên.","detail":"Nhóm Hàn Lập dừng lại lục soát khu rừng vì nơi tụ uế khí có khả năng sinh Minh Diễm quả. Lôi Lan sau đó phát hiện một Minh Diễm thụ có sáu quả trong rừng.","theLucLienQuan":[],"nguon":["@c1454"]},{"id":"van-dang-dao","name":"Vạn Đằng đạo","cn":"","capDo":"khac","parentId":"tang-hai-dia-uyen","blurb":"Tuyến đường Hàn Lập dự định hướng tới trong hành trình tại tầng hai Địa Uyên.","detail":"Đoàn người tạm hoãn tiến về Vạn Đằng đạo để dành nửa ngày tìm Minh Diễm quả trong Hủ Diệp lâm.","theLucLienQuan":[],"nguon":["@c1454"]},{"id":"thuy-dam-trong-hu-diep-lam","name":"Thủy đàm trong Hủ Diệp lâm","cn":"","capDo":"khac","parentId":"hu-diep-lam","blurb":"Thủy đàm nằm sâu trong Hủ Diệp lâm, quanh đó có hôi khí phủ trên mặt đất.","detail":"Lôi Lan phát hiện Minh Diễm thụ có sáu quả mọc bên cạnh thủy đàm và dẫn cả nhóm tới kiểm tra.","theLucLienQuan":[],"nguon":["@c1454"]},{"id":"thuy-dam-minh-diem-qua","name":"Thủy đàm Minh Diễm quả","cn":"","capDo":"khac","parentId":"thuy-dam-trong-hu-diep-lam","blurb":"Thủy đàm rộng hơn trăm trượng nằm dưới lớp vụ khí, nơi mọc nhiều cây kết Minh Diễm quả. Một yêu vật giống bạch tuộc màu nâu sống dưới nước và bảo vệ khu vực.","detail":"Những cây hắc lục mọc cách bờ hơn mười trượng, mang các quả đen có hắc khí lưu động. Khi Lôi Lan, Bạch Bích và Tần Hiểu xuống hái quả, yêu vật dưới thủy đàm dùng xúc tu cùng thủy tiễn tập kích và có thể tái sinh xúc tu bằng lam quang.","theLucLienQuan":["Thiên Bằng tộc"],"nguon":["@c1455"]},{"id":"mat-dat-phia-tren-dia-uyen","name":"Mặt đất phía trên Địa Uyên","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Khu vực phía trên Địa Uyên, nơi có các trưởng lão Phi Linh tộc.","detail":"Hàn Lập chọn nơi này làm điểm rút lui vì cho rằng sự hiện diện của các trưởng lão Phi Linh tộc sẽ khiến những đại địch trong Địa Uyên khó bắt được hắn.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c1456"]},{"id":"dai-dien-tang-ba","name":"Đại điện tầng ba","cn":"","capDo":"khac","parentId":"tang-ba-dia-uyen","blurb":"Đại điện tại tầng ba Địa Uyên, nơi Huyết Độc trở về phục mệnh.","detail":"Trong đại điện có kim sắc cự hoa của Mộc Thanh và hai thị nữ áo xanh. Tại đây, Mộc Thanh nghe báo cáo của Huyết Độc, chọn Hàn Lập làm cực phẩm huyết thực rồi quyết định tự mình truy bắt.","theLucLienQuan":[],"nguon":["@c1457"]},{"id":"chieu-trach-tang-hai","name":"Chiểu trạch tầng hai","cn":"","capDo":"khac","parentId":"tang-hai-dia-uyen","blurb":"Khu chiểu trạch thuộc tầng hai Địa Uyên.","detail":"Nhóm Hàn Lập đi qua khu vực này trong hành trình cấp tốc trở lại mặt đất và sau đó trông thấy lối ra khỏi tầng hai.","theLucLienQuan":[],"nguon":["@c1457"]},{"id":"tang-mot-dia-uyen","name":"Tầng một Địa Uyên","cn":"","capDo":"vuc","parentId":"dia-uyen","blurb":"Tầng gần mặt đất, nơi nhóm Hàn Lập chia đường chạy trốn.","detail":"Sau khi trở lại tầng này, Hàn Lập cảnh báo về yêu vương Địa Uyên và yêu cầu ba người đồng hành tách nhau chạy về mặt đất. Hắn một mình tiếp tục phi độn và trở thành mục tiêu chính của cuộc truy đuổi.","theLucLienQuan":[],"nguon":["@c1457"]},{"id":"son-coc-tang-mot","name":"Sơn cốc tầng một","cn":"","capDo":"khac","parentId":"tang-mot-dia-uyen","blurb":"Sơn cốc tại tầng một Địa Uyên, nơi nhóm Hàn Lập dừng lại trong thời gian ngắn.","detail":"Tại đây, Hàn Lập nói rõ nguy cơ từ một yêu vương mà cả nhóm không đủ sức chống lại. Hắn yêu cầu Lôi Lan, Bạch Bích và Tần Hiểu tách nhau chạy trốn trước khi tự mình dẫn đầu rời đi.","theLucLienQuan":[],"nguon":["@c1457"]},{"id":"sao-huyet-cua-moc-thanh-tai-tang-hai-dia-uyen","name":"Sào huyệt của Mộc Thanh tại tầng hai Địa Uyên","cn":"","capDo":"khac","parentId":"tang-hai-dia-uyen","blurb":"Sào huyệt của Mộc Thanh nằm tại tầng hai Địa Uyên và được cấm chế mạnh bảo vệ.","detail":"Khu vực có tế đàn truyền tống, nhiều kiến trúc bằng gỗ và các yêu vật mang hình dạng nửa người nửa yêu. Hôi vân, hắc sắc lôi điện cùng linh áp trên không tạo thành lớp phong tỏa khiến Hàn Lập không thể nhanh chóng đào thoát.","theLucLienQuan":[],"nguon":["@c1458"]},{"id":"dai-dien-cua-moc-thanh","name":"Đại điện của Mộc Thanh","cn":"","capDo":"khac","parentId":"sao-huyet-cua-moc-thanh-tai-tang-hai-dia-uyen","blurb":"Đại điện trong sào huyệt, nơi Mộc Thanh tiếp đãi và thương lượng sơ bộ với Hàn Lập.","detail":"Điện có không gian trống, hai hàng ghế và một đóa kim sắc cự hoa làm chỗ ngồi cho Mộc Thanh. Hàn Lập được mời dùng Âm Sát Trà tại đây trước khi bị giữ lại chờ cuộc thương lượng chính thức.","theLucLienQuan":[],"nguon":["@c1458"]},{"id":"quy-tan-lau","name":"Quý tân lâu","cn":"","capDo":"khac","parentId":"sao-huyet-cua-moc-thanh-tai-tang-hai-dia-uyen","blurb":"Nơi nghỉ dành cho khách trong sào huyệt của Mộc Thanh.","detail":"Mộc Thanh sai Bích Nhi đưa Hàn Lập đến quý tân lâu nghỉ vài ngày và đáp ứng nhu cầu của hắn trong thời gian chờ nàng công bố việc cần thương lượng.","theLucLienQuan":[],"nguon":["@c1458"]},{"id":"minh-ha-chi-dia","name":"Minh Hà Chi Địa","cn":"","aliases":["Minh Hà"],"capDo":"gioi-nho","parentId":null,"blurb":"Mục tiêu của kế hoạch do Mộc Thanh, Lục Túc và các đồng minh chuẩn bị thực hiện.","detail":"Kết giới Minh Hà dùng âm khí làm cấm chế, chứa Minh Ma Chi Khí tinh thuần và có đàn quỷ cản đường. Ích Tà Thần Lôi của Hàn Lập được coi là phương tiện khắc chế ma khí tại đây.","theLucLienQuan":["Mộc Tiên Cốc"],"nguon":["@c1459","@c1482","@c1518"]},{"id":"hac-vu-lam","name":"Hắc Vụ Lâm","cn":"","aliases":[],"capDo":"khac","parentId":"tang-ba-dia-uyen","blurb":"Khu rừng phủ âm vụ tại tầng ba Địa Uyên, đồng thời là địa bàn của Mộc Thanh và Mộc Tiên Cốc.","detail":"Mộc Thanh bố trí cấm chế trong Hắc Vụ Lâm, khiến người ngoài tiến vào khó thoát ra. Hàn Lập đang bị giữ lại tại đây dưới sự giám sát của Huyết Độc.","theLucLienQuan":["Mộc Tiên Cốc"],"nguon":["@c1459"]},{"id":"moc-tien-dien","name":"Mộc Tiên Điện","cn":"","aliases":[],"capDo":"khac","parentId":"hac-vu-lam","blurb":"Nơi Mộc Thanh dự định tổ chức cuộc gặp với Lục Túc, Quỷ Bà và Địa Huyết sau nửa tháng.","detail":"Cuộc gặp tại Mộc Tiên Điện sẽ dùng để thương lượng cách sử dụng Hàn Lập và tiếp tục chuẩn bị cho kế hoạch tiến vào Minh Hà Chi Địa.","theLucLienQuan":["Mộc Tiên Cốc"],"nguon":["@c1459"]},{"id":"am-minh-chi-dia","name":"Âm Minh Chi Địa","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Nơi Hàn Lập từng bị quỷ vụ hút vào khi hỗ trợ Nguyên Dao thi triển hoàn hồn thuật.","detail":"Hàn Lập nhớ lại mình từng bị quỷ vụ cuốn vào Âm Minh Chi Địa trong thời gian hỗ trợ cứu Nghiên Lệ và phải tốn nhiều sức mới thoát ra.","theLucLienQuan":[],"nguon":["@c1460"]},{"id":"moc-tinh-dong","name":"Mộc Tinh Động","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Nơi Mộc Thanh hẹn Hàn Lập tới để bắt đầu học khu lôi chi đạo.","detail":"Mộc Thanh yêu cầu Hàn Lập đến Mộc Tinh Động sau ba ngày. Tại đây, nàng dự định trực tiếp chỉ điểm hắn tu luyện khu lôi chi đạo trong thời hạn hai năm.","theLucLienQuan":["Mộc Thanh"],"nguon":["@c1462"]},{"id":"mat-that-moc-tinh-dong","name":"Mật thất Mộc Tinh Động","cn":"","capDo":"khac","parentId":"moc-tinh-dong","blurb":"Mật thất nơi Hàn Lập trở về sau khi vượt tiểu thiên kiếp.","detail":"Hàn Lập tự bố trí cấm chế trong mật thất rồi dùng thiên kiếp chi lôi thu được để luyện thành hơn ba mươi thanh sắc lôi châu.","theLucLienQuan":[],"nguon":["@c1464"]},{"id":"thinh-duong-moc-tinh-dong","name":"Thính đường Mộc Tinh Động","cn":"","capDo":"khac","parentId":"moc-tinh-dong","blurb":"Thính đường nơi Mộc Thanh tiếp Huyết lão quái và triệu Hàn Lập tới gặp.","detail":"Cuối chương, Hàn Lập theo truyền âm phù tới đây và được Mộc Thanh cho biết Huyết lão quái đã chủ động đến tìm mình.","theLucLienQuan":[],"nguon":["@c1464"]},{"id":"huyet-diem-son","name":"Huyết Diễm Sơn","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Ngọn núi cao khoảng bốn đến năm nghìn trượng, là động phủ của Huyết bào nhân.","detail":"Bên trong núi có cửa đá hình đầu giao, mạng lưới thông đạo như mê cung, số lượng lớn khôi lỗi tuần tra và hồ dung nham bao quanh Huyết Diễm Cung.","theLucLienQuan":["Thuộc hạ Huyết Diễm Cung"],"nguon":["@c1465"]},{"id":"huyet-diem-cung","name":"Huyết Diễm Cung","cn":"","capDo":"khac","parentId":"huyet-diem-son","blurb":"Cung điện tinh xảo nằm giữa hồ dung nham dưới lòng Huyết Diễm Sơn.","detail":"Cung điện tỏa khí tức huyết tinh, được tinh thạch đỏ, cấm chế tơ trong suốt và hồ dung nham bảo vệ. Muốn tiếp cận an toàn phải nhờ Độn Quy Thú đưa qua hồ.","theLucLienQuan":["Thuộc hạ Huyết Diễm Cung"],"nguon":["@c1465"]},{"id":"ho-dung-nham-duoi-huyet-diem-son","name":"Hồ dung nham dưới Huyết Diễm Sơn","cn":"","capDo":"khac","parentId":"huyet-diem-son","blurb":"Hồ nham thạch tự nhiên bao quanh Huyết Diễm Cung.","detail":"Hồ có khí tức cực nóng, là nơi Độn Quy Thú sinh sống và tạo thành một tuyến phòng thủ ngăn người ngoài tiếp cận cung điện.","theLucLienQuan":["Thuộc hạ Huyết Diễm Cung"],"nguon":["@c1465"]},{"id":"me-cung-khoi-loi-huyet-diem-son","name":"Mê cung khôi lỗi Huyết Diễm Sơn","cn":"","capDo":"khac","parentId":"huyet-diem-son","blurb":"Hệ thống thông đạo đan xen rộng lớn trong lòng Huyết Diễm Sơn.","detail":"Mê cung có nhiều lối rẽ và được nhiều loại khôi lỗi bằng kim loại hoặc linh mộc tuần tra. Một số khôi lỗi đặc thù đạt thực lực ước chừng cấp Hóa Thần.","theLucLienQuan":["Thuộc hạ Huyết Diễm Cung"],"nguon":["@c1465"]},{"id":"am-hoa-dien","name":"Âm Hỏa Điện","cn":"","capDo":"khac","parentId":"huyet-diem-cung","blurb":"Điện thất nằm trong Huyết Diễm Cung.","detail":"Huyết bào nhân ra lệnh cho thuộc hạ mở Âm Hỏa Điện để tiếp đãi Hàn Lập. Công dụng cụ thể của điện chưa được tiết lộ.","theLucLienQuan":["Thuộc hạ Huyết Diễm Cung"],"nguon":["@c1465"]},{"id":"huyet-luyen-duong","name":"Huyết Luyện Đường","cn":"","capDo":"khac","parentId":"huyet-diem-cung","blurb":"Công trình bằng một khối thủy tinh lớn nằm giữa dung nham, là nơi đặt Tử Huyết khôi lỗi.","detail":"Huyết Luyện Đường rộng khoảng ba bốn trăm trượng, được xây giữa dung nham nhưng bên trong không nóng. Huyết lão quái đưa Hàn Lập tới đây để chuẩn bị quán chú Ích Tà Thần Lôi vào Minh Ấn Phù Trận trên khôi giáp Tử Huyết khôi lỗi.","theLucLienQuan":["Thuộc hạ Huyết Diễm Cung"],"nguon":["@c1466"]},{"id":"thuy-ngam-vien","name":"Thúy Ngâm Viên","cn":"","capDo":"khac","parentId":"moc-tinh-dong","blurb":"Khu vực bị tầng tầng cấm chế bao phủ bên trong Mộc Tinh Động.","detail":"Thúy Ngâm Viên tỏa ra mộc linh khí tinh thuần, khiến Hàn Lập đoán nơi đây là một dược viên chứa linh dược được Mộc Thanh đặc biệt coi trọng. Hắn không tiến vào vì nhớ lời cảnh cáo của Mộc Thanh và lo ngại có người bí mật giám thị.","theLucLienQuan":[],"nguon":["@c1468"]},{"id":"moc-linh-dien","name":"Mộc Linh Điện","cn":"","capDo":"khac","parentId":"moc-tinh-dong","blurb":"Nơi Mộc Thanh triệu tập các yêu vương để kiểm chứng thành quả tu luyện của Hàn Lập.","detail":"Hàn Lập, Mộc Thanh, Lục Túc, Lam đạo hữu và các huyết bào nhân hội họp tại đây trước khi ra ngoài quan sát Tế Lôi Chi Thuật.","theLucLienQuan":[],"nguon":["@c1468"]},{"id":"khoang-dat-trong-ngoai-moc-linh-dien","name":"Khoảng đất trống ngoài Mộc Linh Điện","cn":"","capDo":"khac","parentId":"moc-linh-dien","blurb":"Địa điểm Hàn Lập biểu diễn Tế Lôi Chi Thuật trước các yêu vương.","detail":"Kim sắc quang trụ do Hàn Lập phóng ra đã phá tan cấm chế cùng tinh cương tại khu đất này và để lại một hố sâu không thấy đáy.","theLucLienQuan":[],"nguon":["@c1468"]},{"id":"am-thuy-quanh-minh-ha-chi-dia","name":"Âm thủy quanh Minh Hà Chi Địa","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Lớp âm thủy thuộc thủy lung tráo bao bọc Minh Hà Chi Địa, dày khoảng vạn trượng. Người bình thường tiến vào sẽ mất ba hồn sáu phách, hóa thành âm thi và vĩnh viễn mắc kẹt trong nước.","detail":"Âm thủy tạo thành lớp ngăn cách quỷ dị bên ngoài Minh Hà Chi Địa. Người không đủ khả năng chống đỡ khi tiến vào sẽ mất hồn phách, thân thể biến thành âm thi và không thể rời khỏi vùng nước này.","theLucLienQuan":[],"nguon":["@c1469"]},{"id":"hoa-vien-cu-hoa","name":"Hoa viên cự hoa","cn":"","capDo":"khac","parentId":"moc-tinh-dong","blurb":"Hoa viên bí mật nằm sau cánh cửa có cấm chế trong Mộc Tinh Động.","detail":"Bên trong hoa viên mọc nhiều đóa hoa khổng lồ tỏa linh khí. Một con đường nhỏ xuyên qua khu vực này dẫn tới bãi cỏ đặt bản thể linh mộc của Mộc Thanh.","theLucLienQuan":["Mộc Tinh Động"],"nguon":["@c1470"]},{"id":"bai-co-cu-moc-den","name":"Bãi cỏ cự mộc đen","cn":"","capDo":"khac","parentId":"hoa-vien-cu-hoa","blurb":"Khu vực trung tâm trong hoa viên bí mật, nơi đặt bản thể linh mộc của Mộc Thanh.","detail":"Trên bãi cỏ có một cự mộc đen cao năm sáu mươi trượng. Một nửa cây vẫn xanh tốt, trong khi nửa còn lại khô héo do tổn thương từ lần Mộc Thanh hy sinh nguyên khí bản thể và tự bạo chống kẻ xâm nhập.","theLucLienQuan":["Mộc Tinh Động"],"nguon":["@c1470"]},{"id":"uyen-canh","name":"Uyên Canh","cn":"","capDo":"vuc","parentId":"dia-uyen","blurb":"Khu vực có nhiều địa điểm bí mật được các yêu vương sử dụng để chuẩn bị cho chuyến đi Minh Hà Chi Địa.","detail":"Trong Uyên Canh có hạp cốc hắc phong nơi Mỹ phụ tóc bạc tập hợp các nhân ảnh mặc quái giáp. Một tầng thần bí khác của khu vực còn có tế đàn đặt hôi bạch nhãn cầu do Lục Túc giám sát.","theLucLienQuan":["Tứ Đại Yêu Vương Địa Uyên"],"nguon":["@c1471"]},{"id":"hap-coc-hac-phong","name":"Hạp cốc hắc phong","cn":"","capDo":"khac","parentId":"uyen-canh","blurb":"Hạp cốc nằm sâu trong Uyên Canh, quanh năm có hắc phong cuồng vũ.","detail":"Bên trong hạp cốc có nhiều nhân ảnh cao lớn mặc hắc sắc quái giáp. Mỹ phụ tóc bạc xuất hiện tại đây để kiểm tra lực lượng bí mật trước chuyến đi Minh Hà Chi Địa.","theLucLienQuan":["Tứ Đại Yêu Vương Địa Uyên"],"nguon":["@c1471"]},{"id":"te-dan-tram-truong","name":"Tế đàn trăm trượng","cn":"","capDo":"khac","parentId":"uyen-canh","blurb":"Tế đàn cao hơn trăm trượng nằm tại một tầng thần bí của Uyên Canh.","detail":"Trên tế đàn đặt hôi bạch nhãn cầu khổng lồ đang phun tơ xám hút âm khí. Lục Túc đứng tại đây giám sát quá trình hoạt động của vật thể.","theLucLienQuan":["Tứ Đại Yêu Vương Địa Uyên"],"nguon":["@c1471"]},{"id":"vung-nui-be-quan-han-lap","name":"Vùng núi bế quan của Hàn Lập","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Vùng núi vắng có linh khí không cao và không tập trung yêu vật cao cấp.","detail":"Hàn Lập chọn khu vực này để dựng động phủ và bế quan hai năm. Tại đây hắn luyện thành biến thân ngũ sắc khổng tước và tiếp tục bồi dưỡng Huyền Thiên Quả Thật.","theLucLienQuan":[],"nguon":["@c1471"]},{"id":"hac-am-khi","name":"Hắc Ám Khí","cn":"","aliases":[],"capDo":"vuc","parentId":"dia-uyen","blurb":"Tầng thứ bảy và nguy hiểm nhất của Địa Uyên, nơi đại quân của tứ đại yêu vương tập kết trước khi tiến vào Minh Hà Chi Địa.","detail":"Hắc Ám Khí có nhiều yêu vật mạnh chưa khai mở linh trí, trong đó tồn tại những sinh vật khiến cả tứ đại yêu vương kiêng kỵ. Một sa mạc hoang vu tại đây được dùng làm nơi tập kết hàng vạn yêu vật, quỷ binh, khôi lỗi và các lực lượng cấp cao.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên"],"nguon":["@c1473"]},{"id":"duyen-tham-thanh","name":"Duyến Thâm Thành","cn":"","aliases":[],"capDo":"thanh","parentId":"dia-uyen","blurb":"Nơi Nghiên Lệ và Nguyên Dao trở về sau khi bàn kế hoạch đào thoát với Hàn Lập.","detail":"Sau khi thống nhất cách lợi dụng mối tình giả để kiềm chế Quỷ Bà, Nghiên Lệ và Nguyên Dao lập tức trở về Duyến Thâm Thành.","theLucLienQuan":[],"nguon":["@c1473"]},{"id":"hac-sac-thong-dao","name":"Hắc sắc thông đạo","cn":"","capDo":"khac","parentId":null,"blurb":"Thông đạo không gian do Kinh Không Ma xé mở, dẫn về phía Minh Hà Chi Địa. Đoạn đã mở dài khoảng trăm trượng và kết thúc trước một vùng ngân hà chắn đường.","detail":"Lục Túc, Mộc Thanh, Hàn Lập và Kim Linh tiến vào hắc động rồi bay khoảng trăm trượng trong tiếng oanh minh và dao động không gian. Khi đến vùng ngân hà phía trước, họ phải dừng lại để tiếp tục đả thông phần không gian nối với Minh Hà Chi Địa.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên"],"nguon":["@c1474"]},{"id":"minh-ha","name":"Minh Hà","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Dòng Minh Thủy trắng sữa chắn đường tiến sâu vào Minh Hà Chi Địa.","detail":"Minh Hà sâu không thấy đáy, mặt nước phẳng lặng như gương dù hàn phong gào thét. Bên dưới có đàn quái ngư phóng ngân mang công kích sinh vật tới gần, còn ma khí trong Minh Thủy phải được thanh trừ trước khi các yêu vương có thể tách dòng nước.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên"],"nguon":["@c1475","@c1506"],"aliases":["Minh Hà chi địa"]},{"id":"thong-dao-khong-gian-toi-minh-ha","name":"Thông đạo không gian tới Minh Hà","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Thông đạo xuất hiện sau khi Mộc Thanh và Lục Túc phá tan ngân hà chắn đường.","detail":"Bên trong thông đạo có bạch quang bất định và luồng hàn phong có thể xuyên qua linh quang hộ thể. Đoàn yêu vương, khôi lỗi, âm giáp quỷ binh cùng Hàn Lập dùng nơi này để tiến vào khu vực Minh Hà.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên"],"nguon":["@c1475"]},{"id":"thong-dao-mau-den-minh-ha","name":"Thông đạo màu đen trong Minh Hà","cn":"","capDo":"khac","parentId":"minh-ha","blurb":"Con đường được tạo giữa hai tường nước Minh Hà nhờ hợp lực công kích và hắc sắc quang ba từ chuông đen.","detail":"Cao hơn mười trượng, rộng vài chục trượng. Được ổn định bởi hắc sắc quang ba của chiếc chuông đen do mỹ phụ đầu bạc thúc động. Chỉ duy trì được vài canh giờ. Bên trong có vô số tơ bạc tập kích có chọn lọc, chỉ nhắm đê giai yêu vật mà bỏ qua khôi lỗi và huyền quỷ.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên"],"nguon":["@c1476"]},{"id":"khong-gian-duoi-minh-ha","name":"Không gian dưới Minh Hà","cn":"","capDo":"gioi-nho","parentId":"minh-ha","blurb":"Không gian rộng lớn nằm bên dưới tầng Minh Hà chi thủy.","detail":"Khu vực có mặt đất phủ cát đen, trong khi tầng Minh Hà chi thủy màu trắng bao trùm phía trên. Đại quân tập kết tại đây sau khi vượt qua thông đạo màu đen.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên","Đội quân tiên phong phá Minh Hà"],"nguon":["@c1477"]},{"id":"binh-nguyen-xuong-trang","name":"Bình nguyên xương trắng","cn":"","capDo":"vuc","parentId":"khong-gian-duoi-minh-ha","blurb":"Bình nguyên vô biên chất đầy xương cốt của nhiều loại sinh linh.","detail":"Xương cốt tại đây mang dấu vết lâu đời và trải rộng đến tận tầm mắt. Xú khí càng trở nên nồng đậm khi đội quân tiến sâu hơn mười dặm vào khu vực.","theLucLienQuan":["Đội quân tiên phong phá Minh Hà"],"nguon":["@c1477"]},{"id":"canh-dong-bach-cot","name":"Cánh đồng bạch cốt","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Cánh đồng phủ đầy xương trắng trong Minh Hà Chi Địa.","detail":"Hôi khí tràn qua khu vực này khiến vô số bộ xương sống dậy thành cốt quái, bao vây đội ngũ Địa Uyên từ mặt đất lẫn không trung.","theLucLienQuan":["Địa Uyên"],"nguon":["@c1478"]},{"id":"ho-den","name":"Hồ đen","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Mặt hồ đen như mực nằm trên hành trình tiến sâu vào Minh Hà Chi Địa.","detail":"Tại đây, cự nhân ba đầu cầm thú cốt giao chiến với tử huyết khôi lỗi, trong khi nhiều quỷ vật ẩn dưới mặt hồ rình rập đội ngũ Địa Uyên.","theLucLienQuan":["Địa Uyên"],"nguon":["@c1478"]},{"id":"chien-truong-quy-vu","name":"Chiến trường quỷ vụ","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Khu vực đội ngũ Địa Uyên bị đại quân quỷ vật phục kích và chia cắt.","detail":"Hơn ba mươi lệ quỷ thống lĩnh có thực lực tương đương tu sĩ Luyện Hư dẫn đại quân xuất hiện tại đây. Quỷ vụ dày đặc che kín chiến trường, khiến các thành viên Địa Uyên mất phương hướng và phải chiến đấu riêng lẻ.","theLucLienQuan":["Địa Uyên","Đại quân quỷ vật Minh Hà"],"nguon":["@c1478"]},{"id":"khu-vuc-suong-mu","name":"Khu vực sương mù","cn":"","capDo":"khac","parentId":"chien-truong-quy-vu","blurb":"Không gian đầy quỷ vật mà đoàn Hàn Lập phải vượt qua bằng bí thuật dẫn đường.","detail":"Khu vực bị sương mù bao phủ và có nhiều quỷ vật cản đường. Càng tiến gần rìa, sương mù càng loãng và số lần đoàn người chạm trán quỷ vật càng giảm.","theLucLienQuan":["Đội quân tiên phong phá Minh Hà"],"nguon":["@c1480"]},{"id":"mep-suong-mu","name":"Mép sương mù","cn":"","capDo":"khac","parentId":"khu-vuc-suong-mu","blurb":"Rìa ngoài của khu vực sương mù, nơi đoàn Hàn Lập bị bạch ảnh chặn lại.","detail":"Khi đoàn người sắp rời khỏi sương mù, tiếng cười quỷ dị bất ngờ khiến Nguyên Dao, Nghiên Lệ và đám huyền quỷ suy kiệt. Hàn Lập sau đó phát hiện bạch ảnh ẩn trong hư không tại đây.","theLucLienQuan":["Đội quân tiên phong phá Minh Hà"],"nguon":["@c1480"]},{"id":"quy-vu","name":"Quỷ vụ","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Vùng sương mù có cấm chế trong Minh Hà Chi Địa, từng vây hãm các nhóm xâm nhập.","detail":"Mộc Thanh và mỹ phụ đầu bạc đã thoát khỏi quỷ vụ, trong khi Lục Túc cùng Địa Huyết được Hàn Lập suy đoán vẫn chưa thể phá giải sương mù để ra ngoài.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên","Phù Du Tộc"],"nguon":["@c1482"]},{"id":"chien-truong-khoi-loi-quy-binh","name":"Chiến trường khôi lỗi–quỷ binh","cn":"","capDo":"khac","parentId":"vu-hai","blurb":"Khu vực giao tranh giữa quân đoàn huyết giáp khôi lỗi và âm giáp quỷ binh.","detail":"Hai đạo quân giao chiến tại đây trong khi các cường giả Hợp Thể kỳ quan sát lẫn nhau. Sau đó phong bạo bao phủ chiến trường, nghiền nát những khôi lỗi và quỷ binh không kịp tháo chạy.","theLucLienQuan":["Âm giáp quỷ binh","Đạo quân huyết giáp"],"nguon":["@c1483"]},{"id":"khu-vuc-cuoi-chan-troi","name":"Khu vực cuối chân trời nơi Lục Túc và Địa Huyết truy đuổi đối phương","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Khu vực ở phương xa nơi Lục Túc và Địa Huyết tiếp tục truy đuổi đối phương.","detail":"Tại đây liên tiếp phát sinh tiếng nổ, tiếng tiêm minh công kích thần thức, cự đại trùng ảnh xích hồng sắc và lưới quang trụ đỏ bao phủ hai vật thể đang né tránh.","theLucLienQuan":[],"nguon":["@c1484"]},{"id":"thanh-dia-phu-du-toc","name":"Thánh địa Phù Du tộc","cn":"","capDo":"gioi-nho","parentId":"minh-ha","blurb":"Thánh địa của Phù Du tộc, được cho là bình thường vài nghìn năm mới mở một lần.","detail":"Ngay cả người Phù Du tộc thông thường cũng không thể tùy tiện tiến vào khu vực này. Kẻ cưỡng ép xâm nhập có thể bị suy giảm mạnh tu vi hoặc chết tại chỗ, trong khi sự xuất hiện sớm của khôi lỗi Phù Du tộc tại đây khiến nhóm Lục Túc nghi ngờ.","theLucLienQuan":["Phù Du tộc"],"nguon":["@c1485","@c1516"]},{"id":"thach-dong-cua-khuong-tien-boi","name":"Thạch động của Khương tiền bối","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Thạch động nằm sâu trong Minh Hà chi địa, nơi Khương tiền bối cư trú và trấn áp nguồn âm khí bất ổn.","detail":"Huyết giáp khôi lỗi được nhiều cao giai quỷ vật dẫn tới đây để cầu viện. Từ sâu trong động, Khương tiền bối nhận Âm Thủy Quỳ Tinh, biểu diễn uy năng rồi đưa Ngũ Long Trát cho sứ giả mượn.","theLucLienQuan":["Phù Du tộc"],"nguon":["@c1486"]},{"id":"hang-dong-cua-lao-gia","name":"Hang động của lão giả","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Nơi lão giả ẩn thân và chuẩn bị lực lượng ngăn chặn đoàn người ngoại lai.","detail":"Tại đây, lão giả truyền pháp quyết điều khiển Ngũ Long Trát bằng thần niệm và giao bình đan dược cho Huyết giáp khôi lỗi trước khi khôi lỗi cùng các quỷ vật lên đường.","theLucLienQuan":["Phù Du tộc"],"nguon":["@c1487"]},{"id":"khu-rung-kho-hoang-vu","name":"Khu rừng khô hoang vu","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Khu rừng chết chóc chứa nhiều hài cốt trùng thú có khả năng tự ghép lại.","detail":"Những bộ xương bị đánh vỡ có thể tự ghép lại khi còn trong rừng. Khi bị đưa ra ngoài, chúng hóa thành bụi vàng hoặc tự quay trở về khu rừng.","theLucLienQuan":["Đội quân tiên phong phá Minh Hà"],"nguon":["@c1487"]},{"id":"son-mach-mau-xam","name":"Sơn mạch màu xám","cn":"","capDo":"vuc","parentId":"minh-ha-chi-dia","blurb":"Sơn mạch nằm sâu trong Minh Hà chi địa và là mục tiêu của hành trình kéo dài một tháng.","detail":"Đoàn Lục Túc nhìn thấy sơn mạch từ khoảng cách chừng trăm dặm. Minh Hà thần nhũ được cho là ẩn giấu tại khu vực chính giữa sơn mạch.","theLucLienQuan":["Phù Du tộc","Đội quân tiên phong phá Minh Hà"],"nguon":["@c1487"]},{"id":"thung-lung-co-quang-mac-den","name":"Thung lũng có quang mạc đen","cn":"","capDo":"khac","parentId":"son-mach-mau-xam","blurb":"Thung lũng rộng hơn mười dặm nằm sau dãy núi xám, bốn phía được đồi núi trùng điệp bao quanh.","detail":"Trung tâm thung lũng bị một tầng quang mạc đen mờ ảo che kín, khiến tình hình bên trong không thể quan sát rõ. Minh Lôi thú trưởng thành ẩn trong khu vực cấm chế tại đây.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên"],"nguon":["@c1488"]},{"id":"thong-thien-tuong","name":"Thông thiên tường","cn":"","capDo":"khac","parentId":"thung-lung-co-quang-mac-den","blurb":"Lớp chướng ngại nằm trước khu vực mục tiêu của nhóm yêu vương.","detail":"Thông thiên tường phải được phá trừ trước khi kế hoạch đoạt bảo tiếp tục. Tử huyết khôi lỗi của phía Địa Huyết được giao làm phương tiện chủ lực để phá lớp chướng ngại này.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên"],"nguon":["@c1488"]},{"id":"ao-dam-cua-minh-loi-thu","name":"Ao đầm của Minh Lôi thú","cn":"","capDo":"khac","parentId":"thung-lung-co-quang-mac-den","blurb":"Khu vực gắn với Minh Lôi thú trưởng thành trong cấm chế.","detail":"Nhóm yêu vương dự định ép Hàn Lập dùng Tích Tà thần lôi dẫn Minh Lôi thú rời thật xa khỏi ao đầm, qua đó giành thời gian an toàn để đoạt thần nhũ.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên"],"nguon":["@c1488"]},{"id":"hac-sac-quang-mac","name":"Hắc sắc quang mạc","cn":"","capDo":"khac","parentId":"ao-dam-cua-minh-loi-thu","blurb":"Lớp quang mạc cấm chế ngăn cách khu vực do Minh Lôi thú canh giữ.","detail":"Nhóm Lục Túc dùng huyết nhận công kích hắc sắc quang mạc để đánh động Minh Lôi thú. Sau khi Hàn Lập dẫn con thú rời đi, các yêu vương cùng khôi lỗi quay lại toàn lực phá mở lớp cấm chế này.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên"],"nguon":["@c1489"]},{"id":"than-tri","name":"Thần trì","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Khu vực nằm phía sau quang mạc đen, nơi nhóm yêu vương tìm cách tiến vào.","detail":"Lục Túc, một thân thể Địa Huyết, Mộc Thanh, mỹ phụ đầu bạc, Nguyên Dao và Nghiên Lệ lần lượt tiến vào thần trì. Việc lực lượng bị chia tách tạo cơ hội cho tồn tại cao giai Phù Du tộc phục kích những người ở lại bên ngoài.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên","Phù Du tộc"],"nguon":["@c1490"]},{"id":"thong-dao-mau-lam","name":"Thông đạo màu lam","cn":"","capDo":"khac","parentId":"than-tri","blurb":"Lối đi tứ phương được Lục Túc cố định trên khe hở của quang mạc đen.","detail":"Thông đạo có bốn vách tinh thạch màu lam, nối khu vực bên ngoài với thần trì. Cuối chương, Địa Huyết hóa thành huyết vân lao về lối này nhưng bị năm cự nhận do Ngũ Long Trát biến thành chặn phía trên.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên","Phù Du tộc"],"nguon":["@c1490"]},{"id":"khu-vuc-dat-dai-tran","name":"Khu vực đặt đại trận","cn":"","capDo":"khac","parentId":"than-tri","blurb":"Vùng phụ cận lối vào được phe quỷ vật chọn để dựng đại trận phong tỏa.","detail":"Đại trận tại đây được bố trí nhằm phong kín toàn bộ khu vực và ngăn những người thoát khỏi cuộc phục kích chạy trốn.","theLucLienQuan":[],"nguon":["@c1491"]},{"id":"hau-cung-dien-trong-than-tri","name":"Hậu cung điện trong thần trì","cn":"","capDo":"khac","parentId":"than-tri","blurb":"Khu vực bên trong thần trì mà đoàn người đi trước được cho là đã tiến vào.","detail":"Gần hậu cung điện có thần nhũ và một Minh Lôi thú khác đang canh giữ, tạo điều kiện để Huyết giáp khôi lỗi thực hiện kế hoạch phục kích.","theLucLienQuan":[],"nguon":["@c1491"]},{"id":"khong-gian-cuu-cung-thien-can-phu","name":"Không gian Cửu Cung Thiên Càn Phù","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian cấm chế do Cửu Cung Thiên Càn Phù tạo ra để vây giữ mục tiêu.","detail":"Bên trong có bạch vụ, ban công, lầu các, điện vũ nối dài và ngân hà cuồn cuộn trên cao. Minh Lôi Thú bị cuốn vào đây, không nhìn thấy lối thoát và phải liên tục công kích cấm chế.","theLucLienQuan":[],"nguon":["@c1493"]},{"id":"quang-sang-mau-den","name":"Quầng sáng màu đen","cn":"","capDo":"khac","parentId":"than-tri","blurb":"Cổng vào khu vực cấm địa quanh Thần Trì.","detail":"Bên ngoài quầng sáng có hơn nghìn thi thể quỷ vật cháy đen và cấm chế đã bị cường lực phá trừ. Một thông đạo lam quang tại đây dẫn vào vùng đất bên trong.","theLucLienQuan":[],"nguon":["@c1494"]},{"id":"vung-dat-ben-trong-quang-sang","name":"Vùng đất bên trong quầng sáng","cn":"","capDo":"khac","parentId":"quang-sang-mau-den","blurb":"Vùng đất tối đen nhưng có linh khí nồng đậm nằm bên trong cấm địa.","detail":"Nơi đây hoang vắng, có nhiều đá vụn và thực vật thấp bé. Hàn Lập bay về phía trung tâm cấm chế vì phán đoán Thần Trì phải nằm tại khu vực đó.","theLucLienQuan":[],"nguon":["@c1494"]},{"id":"cung-dien-da","name":"Cung điện đá","cn":"","capDo":"khac","parentId":"vung-dat-ben-trong-quang-sang","blurb":"Cung điện cao vài chục trượng nằm sâu hơn mười dặm trong cấm địa.","detail":"Cung điện có cửa đá đen mở rộng. Hai luồng âm khí như ẩn như hiện ở hai bên cửa khiến Hàn Lập nghi có hai quỷ vật cấp cao đang mai phục.","theLucLienQuan":[],"nguon":["@c1494"]},{"id":"dien-duong-ngam-duoi-cung-dien","name":"Điện đường ngầm dưới cung điện","cn":"","capDo":"khac","parentId":"cung-dien","blurb":"Điện đường nằm sâu hơn ngàn trượng dưới cung điện phía trên, là nơi các yêu vương giao chiến với Minh Lôi Thú.","detail":"Điện đường ngầm rộng lớn và tinh xảo hơn cung điện phía trên, có tinh thạch phát sáng, linh khí nồng đậm cùng linh hoa linh thảo. Nơi đây chứa chiến trường giữa hai Minh Lôi Thú và phe trong huyết vụ, hai nữ tu bị cấm chế cùng thủy trì nghi chứa Minh Hà thần nhũ.","theLucLienQuan":["Tứ đại yêu vương Địa Uyên"],"nguon":["@c1495"]},{"id":"thuy-tri-xanh-biec","name":"Thủy trì xanh biếc","cn":"","capDo":"khac","parentId":"dien-duong-ngam-duoi-cung-dien","blurb":"Thủy trì phủ sương nằm bên dưới chiến đoàn trong điện đường ngầm, được Hàn Lập nghi là nơi chứa Minh Hà thần nhũ.","detail":"Mặt nước xanh biếc bị sương khói bao phủ, tỏa linh khí dào dạt và thấp thoáng huyết mang. Vị trí của thủy trì nằm ngay dưới khu vực hai Minh Lôi Thú giao chiến với phe yêu vương.","theLucLienQuan":[],"nguon":["@c1495"]},{"id":"luc-tri","name":"Lục trì","cn":"","capDo":"khac","parentId":"dai-dien","blurb":"Thủy trì tỏa ra linh khí tinh thuần và là nơi chứa thần nhũ.","detail":"Sau khi cấm chế được kích hoạt, kim sắc pháp trận bao phủ toàn bộ lục trì, phần đất bên ngoài thủy trì biến mất và con đường lấy thần nhũ tạm thời bị phong tỏa.","theLucLienQuan":[],"nguon":["@c1497"]},{"id":"dai-dien-phia-tren-luc-tri","name":"Đại điện phía trên lục trì","cn":"","capDo":"khac","parentId":"cung-dien-da","blurb":"Đại điện nơi ba cường giả đối đầu với hai Minh Lôi Thú quanh lục trì.","detail":"Đỉnh điện chứa hắc sắc pháp trận đang bành trướng, trong khi kim sắc pháp trận được kích hoạt phía dưới lục trì. Khi cấm chế vận hành, từng mảng trần điện bắt đầu rơi xuống.","theLucLienQuan":[],"nguon":["@c1497"]},{"id":"dai-dien-chua-thuy-tri","name":"Đại điện chứa thủy trì","cn":"","capDo":"khac","parentId":"than-tri","blurb":"Đại điện bao quanh khu vực thủy trì, nơi diễn ra cuộc hỗn chiến giữa các phe.","detail":"Kim giáp khôi lỗi tập kích nhóm ngoại lai tại đây, Mộc Thanh bị giết và Hàn Lập giải cứu Nguyên Dao cùng Nghiên Lệ rồi lao về cửa ra vào.","theLucLienQuan":["Phe kim giáp khôi lỗi","Nhóm Mộc Thanh – mỹ phụ đầu bạc – huyết bào nhân – Lục Túc"],"nguon":["@c1499"]},{"id":"thuy-tri","name":"Thủy trì","cn":"","capDo":"khac","parentId":"dai-dien-chua-thuy-tri","blurb":"Thủy trì nằm trong đại điện và có liên hệ với linh mạch bên dưới.","detail":"Lục Túc ở phía dưới thủy trì và tìm cách chặt đứt liên hệ với linh mạch, buộc kim giáp khôi lỗi phải ra tay sớm.","theLucLienQuan":["Phe kim giáp khôi lỗi"],"nguon":["@c1499"]},{"id":"linh-mach-duoi-thuy-tri","name":"Linh mạch dưới thủy trì","cn":"","capDo":"khac","parentId":"thuy-tri","blurb":"Linh mạch có mối liên hệ trực tiếp với thủy trì.","detail":"Kim giáp khôi lỗi phải bảo vệ mối liên hệ này; nếu Lục Túc chặt đứt được nó, hắn sẽ phải chịu trọng tội khi trở về tộc.","theLucLienQuan":["Phe kim giáp khôi lỗi"],"nguon":["@c1499"]},{"id":"loi-ra-vao-dai-dien","name":"Lối ra vào đại điện","cn":"","capDo":"khac","parentId":"dai-dien","blurb":"Lối thoát mà Hàn Lập tìm cách tiếp cận trong lúc mang theo Nguyên Dao và Nghiên Lệ.","detail":"Hàn Lập nhiều lần bị chặn khi áp sát nơi này. Sau khi hai kim sắc giáp sĩ giữ chân huyết khôi lỗi, hắn xuất hiện tại lối ra vào rồi hóa thành thanh hồng bay đi.","theLucLienQuan":[],"nguon":["@c1500"]},{"id":"lam-sac-thong-dao","name":"Lam sắc thông đạo","cn":"","capDo":"khac","parentId":"dien-duong-ngam-duoi-cung-dien","blurb":"Lối thông hành được huyết khôi lỗi sử dụng khi truy đuổi Hàn Lập.","detail":"Bên ngoài cửa động nối với thông đạo là nơi Hàn Lập bố trí Cửu Cung Thiên Càn Phù, để Đề Hồn Thú giả dạng Minh Lôi Thú và Phệ linh hỏa điểu mai phục huyết khôi lỗi.","theLucLienQuan":[],"nguon":["@c1501"]},{"id":"khu-vuc-cung-dien-ngam","name":"Khu vực cung điện ngầm","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Khu vực cung điện bị kim sắc quang trận phá hủy hoàn toàn trong lúc các bên thoát ra và tiếp tục giao chiến.","detail":"Cung điện ngầm cùng mặt đất trong phạm vi vài dặm sụp đổ thành một hố lớn. Quang trụ còn tạo ra nhiều khe nứt kéo dài hơn mười dặm quanh khu vực.","theLucLienQuan":["Nhóm yêu vương Địa Uyên"],"nguon":["@c1502"]},{"id":"vung-nui-am-khi","name":"Vùng núi âm khí","cn":"","capDo":"vuc","parentId":"minh-ha-chi-dia","blurb":"Một vùng núi cách chiến trường hơn trăm ngàn dặm được Hàn Lập chọn làm nơi ẩn náu và chuẩn bị giải trừ ấn ký.","detail":"Nơi đây có hắc khí bao phủ và cây cối mang màu sắc ảm đạm nhưng vẫn tươi tốt. Âm khí tuy chưa đạt mức lý tưởng nhưng được Nguyên Dao đánh giá đủ mang lại bảy tám thành nắm chắc cho việc giải ấn.","theLucLienQuan":[],"nguon":["@c1502"]},{"id":"thach-dong-trong-hem-da","name":"Thạch động trong hẻm đá","cn":"","capDo":"khac","parentId":"vung-nui-am-khi","blurb":"Nơi ẩn náu tạm thời do Hàn Lập đào trong một hẻm đá không có quỷ vật mạnh.","detail":"Thạch động rộng hơn mười trượng, ăn sâu tới giữa bụng núi và có cửa vào kín đáo. Hàn Lập còn bố trí tiểu kỳ tạo hắc vụ hòa lẫn với âm khí để che giấu động khẩu.","theLucLienQuan":[],"nguon":["@c1502"]},{"id":"go-dat-dat-tran-nhan","name":"Gò đất đặt trận nhãn","cn":"","capDo":"khac","parentId":"vung-nui-am-khi","blurb":"Gò đất có âm khí nồng đậm nhất trong vùng phụ cận, được chọn làm trung tâm của Chuyển Luân Tụ Âm Trận.","detail":"Nghiên Lệ dùng hôi sắc tiểu kỳ dò xét rồi xác định gò đất là nơi thích hợp đặt trận nhãn. Nguyên Dao và Nghiên Lệ lấy địa điểm này làm trung tâm để dựng đại pháp trận.","theLucLienQuan":[],"nguon":["@c1502"]},{"id":"hoang-nguyen-bach-cot","name":"Hoang nguyên bạch cốt","cn":"","capDo":"khac","parentId":null,"blurb":"Một vùng hoang nguyên phủ đầy bạch cốt, nơi nhóm Lục Túc dừng lại sau khi cắt đuôi lực lượng truy đuổi.","detail":"Lục Túc, Địa Huyết, Lam đạo hữu và Tử huyết khôi lỗi dừng tại đây để phân chia chiến lợi phẩm. Cuộc tranh chấp về quyền sở hữu Minh Hà thần nhũ cùng giao ước công kích Thối Tinh Chuyên diễn ra tại khu vực này.","theLucLienQuan":["Phù Du Tộc"],"nguon":["@c1504"]},{"id":"ma-phan","name":"Ma phần","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực nguy hiểm mà Địa Huyết muốn cùng Lục Túc tiến vào để lấy hai bảo vật.","detail":"Ma phần có ma khí và âm khí đặc biệt dày đặc ở sâu bên trong. Ma khí bắt nguồn từ thiên ngoại ma đầu đã chết lâu năm, có thể thông linh hóa hình và được mô tả có uy lực vượt hơn Thông Thiên Linh Bảo; Địa Huyết vì thế muốn dùng Ích Tà Thần Lôi của Hàn Lập mở đường.","theLucLienQuan":[],"nguon":["@c1504","@c1506"]},{"id":"day-bach-sac-son-mach","name":"Dãy bạch sắc sơn mạch","cn":"","capDo":"khac","parentId":"minh-ha","blurb":"Dãy núi trắng nằm sâu trong Minh Hà chi địa, có thạch động nơi Khương tiền bối hiện diện.","detail":"Huyết giáp khôi lỗi trở về khu vực này trong trạng thái cạn kiệt thần thức. Một đạo ngân hồng từ thân khôi lỗi bay vào thạch động để trình báo với Khương tiền bối.","theLucLienQuan":["Phù Du Tộc"],"nguon":["@c1506"]},{"id":"go-dat-bo-tran","name":"Gò đất bố trận","cn":"","capDo":"khac","parentId":"minh-ha","blurb":"Gò đất nơi nhóm Hàn Lập bố trí trận pháp để luyện hóa ấn ký truy tung.","detail":"Nguyên Dao và Nghiên Lệ điều khiển đại trận tại đây để giúp Hàn Lập luyện hóa ấn ký cuối cùng. Sau khi nhóm rời đi, Mộc Thanh tới nơi và nhận ra dấu vết trận pháp, cấm chế cùng âm khí còn sót lại.","theLucLienQuan":[],"nguon":["@c1507"]},{"id":"son-coc-it-am-khi","name":"Sơn cốc ít âm khí","cn":"","capDo":"khac","parentId":"minh-ha","blurb":"Sơn cốc được Mộc Thanh chọn làm nơi dựng một mộc hệ đại trận phòng thủ.","detail":"Mộc Thanh kiểm tra khu vực rồi thúc sinh hàng loạt đại thụ, khiến chúng thay đổi vị trí để tạo thành đại trận bao phủ gần như toàn bộ sơn cốc. Sau khi hoàn thành trận thế, nàng lấy ra một viên châu trắng sữa có hoa văn vàng.","theLucLienQuan":[],"nguon":["@c1507"]},{"id":"vung-cat-vang","name":"Vùng cát vàng","cn":"","capDo":"khac","parentId":"minh-ha","blurb":"Khu vực cát vàng mà nhóm Hàn Lập bay qua khi tìm đường rời Minh Hà chi địa.","detail":"Hàn Lập dẫn Nguyên Dao và Nghiên Lệ vượt qua khu vực này, liên tục đổi hướng để xóa dấu vết và bàn kế hoạch tìm không gian tiết điểm trở về Linh giới.","theLucLienQuan":[],"nguon":["@c1508"]},{"id":"thuy-vuc-hac-vu-tai-minh-ha-chi-dia","name":"Thủy vực hắc vụ tại Minh Hà chi địa","cn":"","capDo":"vuc","parentId":"minh-ha","blurb":"Thủy vực xanh đen rộng gần như đại dương, có vô số đảo và nhiều đám hắc vụ. Một số đám vụ khí tại đây có thể tước đoạt khả năng vận dụng linh lực và giam cầm thần niệm.","detail":"Hàn Lập chọn thủy vực này làm nơi ẩn náu vì dưới đáy có nhiều tồn tại đáng sợ, khiến kẻ truy tìm khó tùy tiện dùng thần niệm tra xét. Khu vực có nhiều đám hắc vụ, nhưng chỉ một số trong đó thôn phệ linh lực; hơn phân nửa là vụ khí bình thường. Hắc vụ đặc biệt cũng giam cầm thần niệm, có thể che giấu nhóm Hàn Lập khỏi các yêu vương nhưng ẩn chứa nguy hiểm chưa rõ.","theLucLienQuan":["Phù Du Tộc"],"nguon":["@c1509"]},{"id":"quan-the-ngoc-thai-trong-long-nui","name":"Quần thể ngọc thai trong lòng núi","cn":"","capDo":"khac","parentId":"minh-ha","blurb":"Quần thể kiến trúc nằm trong lòng núi, bị hắc vụ bao quanh và được nhiều lớp cấm chế bảo vệ.","detail":"Khu vực gồm ngọc thai nơi Hàn Lập và Nghiên Lệ xuất hiện cùng sáu kiến trúc tương tự bố trí thành vòng tròn. Các cột đá khắc phù văn, bạch sắc quang mạc và những lớp cấm chế phân chia quần thể với hắc vụ bên ngoài.","theLucLienQuan":[],"nguon":["@c1511"]},{"id":"binh-thai-mep-da","name":"Bình thai mép đá","cn":"","capDo":"khac","parentId":"quan-the-ngoc-thai-trong-long-nui","blurb":"Khoảng đất đá nhô ra phía trên ngọc thai, nằm sau bức tường cấm chế thanh–vàng.","detail":"Hàn Lập và Nghiên Lệ tiến vào bình thai sau khi vượt qua hắc vụ. Phía đối diện có một thông đạo phát ra nhũ bạch sắc quang mang, còn bức tường cấm chế phía sau nhanh chóng tự khôi phục.","theLucLienQuan":[],"nguon":["@c1511"]},{"id":"phu-cua-lao-gia","name":"Phủ của lão giả","cn":"","capDo":"khac","parentId":"quan-the-ngoc-thai-trong-long-nui","blurb":"Động phủ nằm phía trong thông đạo phát ra nhũ bạch sắc quang mang.","detail":"Chủ nhân phủ có thể nhận biết biến động của Thất Môn Tỏa Âm Trận và dễ dàng bắt hai kim sắc giáp trùng được Hàn Lập phái vào thăm dò. Lão giả chưa lộ diện đã chủ động mời Hàn Lập và Nghiên Lệ tiến vào.","theLucLienQuan":[],"nguon":["@c1511"]},{"id":"dai-sanh-trong-dong-phu","name":"Đại sảnh trong động phủ","cn":"","capDo":"khac","parentId":"phu-cua-lao-gia","blurb":"Đại sảnh cổ kính trong động phủ của lão giả họ Khương, nơi ông gặp Hàn Lập và Nghiên Lệ.","detail":"Không gian rộng hơn trăm trượng, bày biện đơn sơ với vài chiếc bàn và những bồn cây hoa tỏa hơi thở thảo mộc nồng đậm.","theLucLienQuan":[],"nguon":["@c1512","@c1515"]},{"id":"khu-vuc-phe-linh-vu-khi","name":"Khu vực Phệ Linh Vụ Khí","cn":"","capDo":"khac","parentId":"minh-ha","blurb":"Khu vực trong Minh Hà chi địa nơi nhóm Hàn Lập ở gần khi Thất Môn Tỏa Âm Trận được thi triển.","detail":"Hàn Lập, Nghiên Lệ và Nguyên Dao bị trận lực cuốn tới những vị trí khác nhau vì ở gần khu vực Phệ Linh Vụ Khí đúng lúc Khương lão giả thi pháp.","theLucLienQuan":[],"nguon":["@c1513"]},{"id":"noi-sau-nhat-trong-van-truong-ma-khi","name":"Nơi sâu nhất trong vạn trượng ma khí","cn":"","capDo":"khac","parentId":"minh-ha","blurb":"Nơi sâu nhất của vùng ma khí trong Minh Hà chi địa.","detail":"Ma khí đã hóa thành hình người và hoàn thành vô thượng ma thân đang ẩn mình tại đây để chuyên tâm tu luyện.","theLucLienQuan":[],"nguon":["@c1513"]},{"id":"khu-phong-khach-cua-khuong-lao-gia","name":"Khu phòng khách của Khương lão giả","cn":"","capDo":"khac","parentId":"phu-cua-lao-gia","blurb":"Khu nghỉ dành cho khách trong phủ của Khương lão giả, nằm sau nhiều thông đạo và dãy phòng.","detail":"Khu vực gồm một tiểu viện với hơn mười gian nhà đá chỉnh tề. Ảnh nô đưa Hàn Lập, Nguyên Dao và Nghiên Lệ tới đây nghỉ ngơi trong ba ngày cân nhắc quyết định.","theLucLienQuan":[],"nguon":["@c1514"]},{"id":"noi-cat-giu-minh-ha-than-nhu","name":"Nơi cất giữ Minh Hà thần nhũ","cn":"","capDo":"khac","parentId":"thanh-dia-phu-du-toc","blurb":"Khu vực cất giữ Minh Hà thần nhũ, được hai Minh Lôi Thú canh giữ.","detail":"Khương lão giả có thủ đoạn tránh tai mắt của hai linh thú để bí mật lấy từng lượng nhỏ Minh Hà thần nhũ.","theLucLienQuan":["Phù Du Tộc"],"nguon":["@c1516"]},{"id":"khu-vuc-phi-linh-toc","name":"Khu vực Phi Linh Tộc","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Khu vực thuộc phạm vi hoạt động của Phi Linh Tộc tại Linh giới.","detail":"Khương lão giả dự đoán Hàn Lập nhiều khả năng sẽ xuất hiện tại vùng phụ cận khu vực này sau khi được pháp trận truyền tống khỏi Minh Hà chi địa.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c1517"]},{"id":"hoang-nguyen-minh-ha","name":"Hoang nguyên Minh Hà","cn":"","capDo":"khac","parentId":"minh-ha","blurb":"Hoang nguyên nằm cách bạch sắc sơn mạch không biết bao nhiêu vạn dặm.","detail":"Lục Túc, Lam đạo hữu, Huyết bào nhân và Tử huyết khôi lỗi bị trùng hải liên tục bổ sung quân số vây khốn tại đây. Quái trùng mặt người đứng ngoài chiến đoàn quan sát, phía trên có vật thể hình quạt ngân sắc không ngừng phóng thêm quái trùng.","theLucLienQuan":[],"nguon":["@c1517"]},{"id":"hac-minh-vu-hai","name":"Hắc Minh vụ hải","cn":"","capDo":"vuc","parentId":"hac-an-son-mach","blurb":"Vùng hắc vụ nguy hiểm trong Hắc Ẩn sơn mạch, nơi Hàn Lập bị khe hở không gian đưa tới.","detail":"Hắc vụ tại đây hút linh khí của cây cỏ, hạn chế thần niệm và triệt tiêu độn quang, khiến tu sĩ không thể phi hành. Hắc vụ từ Minh Hà chi địa tuôn qua khe hở không gian rồi hòa vào vụ hải, cho thấy hai nơi có liên hệ.","theLucLienQuan":["Phi Linh Tộc","Thiên Bằng Tộc"],"nguon":["@c1518"]},{"id":"hac-an-son-mach","name":"Hắc Ẩn sơn mạch","cn":"","capDo":"vuc","parentId":"cu-dao","blurb":"Sơn mạch trên cự đảo thuộc địa vực Phi Linh Tộc.","detail":"Hắc Ẩn sơn mạch bao chứa Hắc Minh vụ hải, vùng hắc vụ mà Hàn Lập từng tránh tiến vào và nay bị truyền tống tới.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c1518"]},{"id":"mat-that-cua-han-lap","name":"Mật thất của Hàn Lập","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Hàn Lập trọng luyện Nguyên Từ Thần Sơn và nghiên cứu hệ thống kiếm trận mới.","detail":"Nền và vách mật thất đều được cấm chế gia cố. Tại đây, Hàn Lập bắt đầu dung hợp đá xám vào Nguyên Từ Thần Sơn, giao hột Thanh La Quả cho đệ nhị Nguyên Anh và bế quan ba tháng lĩnh ngộ Xuân Lê Kiếm Trận.","theLucLienQuan":[],"nguon":["@c1521"]},{"id":"cu-son","name":"Cự sơn","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Ngọn núi nơi Hàn Lập thu nạp thiên địa nguyên khí và tĩnh tọa phá bình cảnh. Khu vực phụ cận được một cấm chế quy mô lớn bảo vệ.","detail":"Vân hoàn từng bao phủ cự sơn và hội tụ ngũ sắc linh quang trong nhiều ngày. Sau khi thu nạp linh khí, Hàn Lập ngồi trong ngũ sắc quang mạc suốt hai tháng rưỡi tại đây; dã thú tiếp cận ngọn núi bị bạch vụ của cấm chế cuốn mất.","theLucLienQuan":[],"nguon":["@c1523"]},{"id":"hac-minh-vu","name":"Hắc Minh Vụ","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Nơi ở hoặc khu vực có liên hệ trực tiếp với người khống chế tam yêu bằng nô ấn. Người này đã mất liên lạc với chúng hơn một trăm năm.","detail":"Tam yêu không biết người trong Hắc Minh Vụ đã gặp chuyện ngoài ý muốn hay chủ động rời đi. Việc mất liên lạc kéo dài khiến chúng lo nô ấn tiếp tục đe dọa tính mạng và phải tìm người giúp giải trừ.","theLucLienQuan":[],"nguon":["@c1523"]},{"id":"hon-dao-cua-tu-yeu","name":"Hòn đảo của tứ yêu","cn":"","capDo":"khac","parentId":null,"blurb":"Hòn đảo nơi tứ yêu bị nô ngân buộc phải ở lại để cung phụng Thiên Bằng Tộc.","detail":"Tứ yêu sinh sống và tìm linh vật quanh hòn đảo này nhưng không thể tự do rời đi vì nô ngân. Sau lần cống nộp gần nhất, người của Thiên Bằng Tộc dự kiến phải vài trăm năm nữa mới trở lại.","theLucLienQuan":["Thiên Bằng Tộc"],"nguon":["@c1525"]},{"id":"luyen-dan-that-cua-han-lap","name":"Luyện đan thất của Hàn Lập","cn":"","capDo":"khac","parentId":"dong-phu-tren-cu-dao","blurb":"Thạch thất chuyên dùng để luyện đan trong động phủ của Hàn Lập.","detail":"Nơi đây có nhiều lô đỉnh, địa hỏa, huyền băng cùng các bình chứa dược liệu thành phẩm hoặc bán thành phẩm. Hàn Lập dùng căn phòng để chuẩn bị và luyện Đằng Long Đan.","theLucLienQuan":[],"nguon":["@c1526"]},{"id":"dong-phu-tren-cu-dao","name":"Động phủ trên cự đảo","cn":"","capDo":"khac","parentId":"hon-dao-cua-tu-yeu","blurb":"Động phủ nơi Hàn Lập bế quan và luyện đan suốt bốn mươi năm.","detail":"Động phủ được bảo vệ bằng nhiều tầng cấm chế và có các khu vực phục vụ trồng linh dược, luyện đan và dò xét. Thần niệm của hai tồn tại bí ẩn vẫn có thể xuyên qua những tầng phòng hộ này.","theLucLienQuan":[],"nguon":["@c1526"]},{"id":"tieu-son-canh-hac-minh-vu-hai","name":"Tiểu sơn cạnh Hắc Minh vụ hải","cn":"","capDo":"khac","parentId":"hac-minh-vu-hai","blurb":"Ngọn núi nơi Mẫn đạo hữu và Giản huynh đứng trao đổi sau khi vượt biển đến lãnh địa Phi Linh Tộc.","detail":"Hàn Lập đã chôn các viên Vạn Lung Châu quanh khu vực này để bí mật truyền cảnh tượng về mặt kính. Việc theo dõi bị Mẫn đạo hữu phát hiện, sau đó hai dị tộc tìm thấy các viên châu gần ngọn núi.","theLucLienQuan":["Giác Xi Tộc","Hải Vương Tộc"],"nguon":["@c1527"]},{"id":"noi-o-cua-thien-bang-toc","name":"Nơi ở của Thiên Bằng Tộc","cn":"","capDo":"khac","parentId":"khu-vuc-phi-linh-toc","blurb":"Khu vực cư trú của Thiên Bằng Tộc, được Hàn Lập chọn làm hướng chạy ban đầu.","detail":"Hàn Lập trước tiên bay về phía nơi ở của Thiên Bằng Tộc, sau hơn vạn dặm mới chuyển hướng ra biển nhằm đánh lạc hướng những kẻ có thể truy đuổi.","theLucLienQuan":["Thiên Bằng Tộc"],"nguon":["@c1530"]},{"id":"vung-duyen-hai-phia-dong","name":"Vùng duyên hải phía Đông","cn":"","capDo":"vuc","parentId":"khu-vuc-phi-linh-toc","blurb":"Tuyến duyên hải được Hàn Lập lựa chọn để rời khỏi lãnh địa Phi Linh Tộc.","detail":"So với biển sâu, khu vực này ít nguy cơ gặp hải thú mạnh hơn và cũng hiếm có Phi Linh nhân xuất hiện. Hàn Lập men theo tuyến đường này về phía Đông trong hơn nửa năm.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c1530"]},{"id":"khong-gian-huyet-van","name":"Không gian huyết vân","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực quỷ dị có bầu trời đỏ và huyết vân mang tinh khí máu tươi bao phủ trên phạm vi cực rộng.","detail":"Hàn Lập phi độn hàng trăm vạn dặm nhưng vẫn không thể rời khỏi huyết vân. Những biểu hiện trong khu vực cho thấy nơi này liên quan đến một cấm chế huyết tế có khả năng truy bám mục tiêu.","theLucLienQuan":[],"nguon":["@c1531"]},{"id":"khong-gian-ben-trong-huyet-sac-quang-tran","name":"Không gian bên trong huyết sắc quang trận","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian huyết sắc hình thành quanh hắc động trong trận pháp, nơi Hàn Lập cùng Huyền Thiên Quả Thật bị cuốn vào.","detail":"Khu vực có hắc động rộng hơn mười trượng, huyết vân, huyết sắc lôi điện và tiếng quỷ khóc sói tru. Sau khi Hàn Lập bị kéo vào, nơi đây xuất hiện dao động không gian cực mạnh nhưng điểm đến phía sau hắc động chưa được xác định.","theLucLienQuan":[],"nguon":["@c1532"]},{"id":"hac-dong","name":"Hắc động","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian do huyết sắc quang trận tạo ra, có lực hút cực lớn, vô số huyết ảnh và cấm chế vô hình phong kín rìa ngoài.","detail":"Hắc động giam Hàn Lập bằng lực hút, huyết ảnh và huyết ti. Rìa không gian có cấm chế trong suốt đánh bật người định thoát ra, còn phần sâu bên trong có thể phát động một quá trình truyền tống khác thường.","theLucLienQuan":[],"nguon":["@c1533"]},{"id":"huyet-sac-te-dan","name":"Huyết sắc tế đàn","cn":"","capDo":"khac","parentId":null,"blurb":"Tế đàn khổng lồ nằm ở một nơi cách xa không rõ bao nhiêu vạn dặm, có hơn mười bóng người đứng bên trên.","detail":"Trên tế đàn tồn tại một pháp trận giống huyết sắc quang trận đã vây Hàn Lập. Một người tại đây cảm ứng được sự xuất hiện của Huyền Thiên Chi Bảo.","theLucLienQuan":[],"nguon":["@c1533"]},{"id":"ho-mau-duoi-te-dan","name":"Hồ máu dưới tế đàn","cn":"","capDo":"khac","parentId":"huyet-sac-te-dan","blurb":"Hồ máu rộng lớn dường như không có bờ nằm phía dưới huyết sắc tế đàn.","detail":"Bên trong hồ máu nổi vô số hài cốt trắng thuộc nhiều chủng tộc, có hình dạng và kích thước khác nhau.","theLucLienQuan":[],"nguon":["@c1533"]},{"id":"bien-lon","name":"Biển lớn","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng biển Hàn Lập tạm thời đổi hướng bay vào để đánh lạc hướng những người có thể truy đuổi.","detail":"Hàn Lập không tiến quá sâu vào biển vì lo ngại gặp phải hải thú cường đại, sau đó quay lại men theo duyên hải về phía Đông.","theLucLienQuan":[],"nguon":["@c1530"]},{"id":"huyet-ho","name":"Huyết hồ","cn":"","capDo":"khac","parentId":"te-dan","blurb":"Hồ máu bao quanh khu vực tế đàn huyết tế.","detail":"Khi pháp trận được tái khởi, bề mặt huyết hồ sục sôi, hắc khí ngưng tụ và huyết sắc vụ hải quay cuồng.","theLucLienQuan":["Phi Linh Tộc","Giác Đổng Tộc","Hải Vương Tộc"],"nguon":["@c1534"]},{"id":"son-coc-gan-bien","name":"Sơn cốc gần biển","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn cốc nơi Hàn Lập rơi xuống sau khi thoát khỏi truyền tống và hư không vỡ nát.","detail":"Sơn cốc nằm gần biển, có ba mặt là đồi núi và một mặt là lối ra. Giữa cốc có bãi cỏ, phạm vi hơn ngàn dặm và là nơi cự giải thanh sắc phát hiện Hàn Lập.","theLucLienQuan":[],"nguon":["@c1534"]},{"id":"hai-dao-hoa-duong-toc","name":"Hải đảo của phân nhánh Hỏa Dương Tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Hải đảo rộng khoảng vài trăm dặm, là nơi cư trú của một phân nhánh nhỏ thuộc Hỏa Dương Tộc.","detail":"Đảo có cây cỏ xanh tươi và một ngọn núi lớn mang đặc điểm giống núi lửa. Hàn Lập được đội săn xà nhân đưa tới đây sau khi vượt qua vùng biển có thiên tượng biến đổi dữ dội.","theLucLienQuan":["Hỏa Dương Tộc"],"nguon":["@c1536"]},{"id":"ben-tau-hoa-duong-toc","name":"Bến tàu Hỏa Dương Tộc","cn":"","capDo":"khac","parentId":"hai-dao-hoa-duong-toc","blurb":"Bến tàu nhỏ nơi đội săn xà nhân đưa Hàn Lập cập đảo và gặp Viêm Vũ.","detail":"Khu vực bến có nhiều nhà đá cao thấp khác nhau, một bãi đá cao khoảng trăm trượng và nhà gỗ dựng trên bãi đá. Viêm Vũ tiếp nhận báo cáo về Hàn Lập tại đây.","theLucLienQuan":["Hỏa Dương Tộc"],"nguon":["@c1536"]},{"id":"hoa-duong-thanh","name":"Hỏa Dương Thành","cn":"","capDo":"thanh","parentId":"hai-dao-hoa-duong-toc","blurb":"Thành trì nằm về phía trung tâm hải đảo của phân nhánh Hỏa Dương Tộc.","detail":"Viêm Vũ dự định hộ tống Hàn Lập tới Hỏa Dương Thành để gặp đại tế ti và tìm lời giải đáp về hải vực xung quanh.","theLucLienQuan":["Hỏa Dương Tộc"],"nguon":["@c1536"]},{"id":"hoa-ho-quan-dao","name":"Hỏa Hô quần đảo","cn":"","capDo":"vuc","parentId":null,"blurb":"Hỏa Hô quần đảo là hải vực nơi Hàn Lập lưu lạc sau khi được Hỏa Dương Tộc cứu giúp.","detail":"Theo Hỏa Nguyệt, vùng lân cận Hỏa Hô quần đảo không có tu sĩ nào mạnh hơn cấp độ Nguyên Anh của nàng. Một phân nhánh Hỏa Dương Tộc sinh sống trên hải đảo trong khu vực này.","theLucLienQuan":["Hỏa Dương Tộc"],"nguon":["@c1537","@c1582"]},{"id":"tho-thanh-hoa-duong-toc","name":"Thổ thành của Hỏa Dương Tộc","cn":"","capDo":"thanh","parentId":"hoa-ho-quan-dao","blurb":"Thành trì của xà nhân Hỏa Dương Tộc trên một hải đảo thuộc Hỏa Hô quần đảo.","detail":"Thổ thành rộng hơn mười dặm, phần lớn kiến trúc được xây bằng bùn đất nhưng đường phố lát đá trắng. Thành được canh phòng nghiêm ngặt và có nhiều xà nhân mang binh khí.","theLucLienQuan":["Hỏa Dương Tộc"],"nguon":["@c1537"]},{"id":"san-dien-dai-te-ti","name":"Sân điện của đại tế ti","cn":"","capDo":"khac","parentId":"tho-thanh-hoa-duong-toc","blurb":"Khu sân điện trong thổ thành, nơi Hỏa Nguyệt cùng các tế ti Hỏa Dương Tộc xuất hiện.","detail":"Sân có điện phụ làm từ gỗ và đất sét, mặt ngoài khảm vỏ sò ngũ sắc. Tại đây đặt một viên trùy thanh đồng phát bạch quang, được nhiều xà nhân áo trắng vận hành bằng cách đưa những vật nhiều màu xuống đáy.","theLucLienQuan":["Hỏa Dương Tộc"],"nguon":["@c1537"]},{"id":"hoa-van-dao","name":"Hỏa Vân đảo","cn":"","capDo":"khac","parentId":"hoa-ho-quan-dao","blurb":"Hòn đảo rộng mấy trăm dặm và là địa bàn cư trú chính của Hỏa Dương Tộc.","detail":"Đảo có một số linh mạch cấp cao cùng nguồn linh dược và linh thạch. Do các đảo lớn khác đã bị tộc mạnh hoặc nhân vật thượng tộc chiếm giữ, đây gần như là nơi duy nhất Hỏa Dương Tộc có thể bố trí đông đảo tộc nhân.","theLucLienQuan":["Hỏa Dương Tộc"],"nguon":["@c1538"]},{"id":"loi-minh-dai-luc","name":"Lôi Minh đại lục","cn":"","capDo":"khac","parentId":null,"blurb":"Đại lục mà Hàn Lập muốn tới sau khi xem hải đồ Hỏa Hô quần đảo.","detail":"Theo ước tính của Hàn Lập, hắn có thể tới nơi trong khoảng nửa năm. Với tu vi như Đại tế tự Hỏa Dương tộc, hành trình cần ít nhất mười năm và phải vượt qua nhiều hiểm nguy.","theLucLienQuan":[],"nguon":["@c1538","@c1580","@c1582","@c1603","@c1666","@c1741"]},{"id":"nha-go-duoi-chan-nui","name":"Nhà gỗ dưới chân núi","cn":"","capDo":"khac","parentId":"tho-thanh-hoa-duong-toc","blurb":"Nơi Hàn Lập được bố trí tĩnh dưỡng sau khi tới Hỏa Dương Tộc.","detail":"Căn nhà nằm trong một tiểu viện dưới chân núi, có linh khí nồng đậm. Phòng bên trong nhỏ, bài trí đơn giản và phần lớn vật dụng được làm bằng gỗ.","theLucLienQuan":["Hỏa Dương Tộc"],"nguon":["@c1539"]},{"id":"hai-vuc-ngoai-loi-minh-dai-luc","name":"Hải vực ngoài Lôi Minh đại lục","cn":"","capDo":"vuc","parentId":"loi-minh-dai-luc","blurb":"Vùng hải ngoại được đại tế tự nghi là nơi dư nghiệt Ô La Tộc từng chạy trốn và ẩn náu.","detail":"Ba bộ tộc thuộc phía Oa Thị đã đặt chân tại khu vực hiện tại từ mấy ngàn năm trước. Đại tế tự chưa hiểu vì sao Ô La Tộc, nếu đã sống gần đó từ lâu, chỉ mới bắt đầu gây khó dễ vào hiện tại.","theLucLienQuan":["Oa Thị Tộc","Ô La Tộc","Hỏa Dương Tộc"],"nguon":["@c1539"]},{"id":"bon-cua-thanh-oa-thi","name":"Bốn cửa thành Oa Thị","cn":"","capDo":"khac","parentId":null,"blurb":"Bốn cửa thành được bố trí lực lượng đốc chiến khi quân Ô La bắt đầu công thành.","detail":"Đại tế tự Hỏa Dương tộc chia các tế tự thành bốn đội, lần lượt phái đến bốn cửa thành để ngăn tế tự Ô La và xử lý người lùi bước.","theLucLienQuan":["Oa Thị bộ tộc","Ô La Tộc","Hỏa Dương Tộc"],"nguon":["@c1543"]},{"id":"hai-vuc-hoa-ho","name":"Hải vực Hỏa Hô","cn":"","capDo":"vuc","parentId":"hoa-ho-quan-dao","blurb":"Vùng biển quanh Hỏa Hô quần đảo đã bị cô lập sau khi truyền tống trận nối với Lôi Minh đại lục bị phá hủy.","detail":"Trong suốt vạn năm trước khi Hàn Lập xuất hiện, Thanh Tiểu chưa từng biết tu luyện giả nào từ đại lục khác đến vùng biển này. Việc mất truyền tống trận khiến hải vực gần như trở thành tuyệt địa.","theLucLienQuan":["Hỏa Dương Tộc","Ô La Tộc","Oa Thị Tộc"],"nguon":["@c1547"]},{"id":"lam-ho-dao","name":"Lam Hồ đảo","cn":"","capDo":"khac","parentId":"hai-vuc-hoa-ho","blurb":"Băng đảo lớn được chọn làm địa điểm tập hợp cho cuộc săn Hải Thú biến dị.","detail":"Lam Hồ đảo nằm phía sau một vùng biển sương có khí hậu nóng lạnh đối nghịch. Khi Hàn Lập chuẩn bị tiến vào đảo, một tiếng gầm từ sâu bên trong khiến khí huyết hắn cuồng động.","theLucLienQuan":[],"nguon":["@c1548"]},{"id":"vung-bien-suong-quanh-lam-ho-dao","name":"Vùng biển sương quanh Lam Hồ đảo","cn":"","capDo":"khac","parentId":"lam-ho-dao","blurb":"Vùng biển dị thường được bao phủ bởi gió tuyết, khí lạnh và lớp hải vụ trắng dày.","detail":"Không trung phía trên có tuyết lạnh và khí băng hàn, trong khi nước biển phía dưới lại nóng như sôi. Sự tương phản tạo thành lớp sương biển dày che phủ đường tới Lam Hồ đảo.","theLucLienQuan":[],"nguon":["@c1548"]},{"id":"bang-dao","name":"Băng Đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Hòn đảo nơi Hàn Lập truy tìm nguồn tiếng rống và giao chiến với Quái Nga.","detail":"Băng Đảo bị thiên nhiên từ lực bao phủ, áp chế thần niệm và khiến phạm vi dò xét của Hàn Lập chỉ còn hơn mười dặm. Tại đây, Quái Nga truy sát các tu sĩ và giao chiến với Hàn Lập.","theLucLienQuan":[],"nguon":["@c1549"]},{"id":"cung-dien-ngoc-trang-duoi-day-bien-sau","name":"Cung điện ngọc trắng dưới đáy biển sâu","cn":"","capDo":"khac","parentId":null,"blurb":"Cung điện bằng ngọc trắng nằm tại một nơi rất xa dưới vùng biển tối đen.","detail":"Gian phòng sâu nhất của cung điện chứa Biển Sâu Cổ Đăng, Khô lâu khoác áo tơi vàng nhạt và Hắc ấn Chân Long giam giữ quái thú đầu trâu màu xanh.","theLucLienQuan":[],"nguon":["@c1552"]},{"id":"mat-that-hac-am","name":"Mật thất hắc ám","cn":"","capDo":"khac","parentId":"cung-dien-ngoc-trang-duoi-day-bien-sau","blurb":"Gian phòng sâu nhất trong cung điện ngọc trắng dưới đáy biển.","detail":"Đây là nơi Khô lâu theo dõi Biển Sâu Cổ Đăng, phóng thích quái thú đầu trâu, khôi phục đăng diễm và dùng ngân kính tìm thấy hình ảnh Hàn Lập.","theLucLienQuan":[],"nguon":["@c1552"]},{"id":"khu-kien-truc-han-bang","name":"Khu kiến trúc hàn băng","cn":"","capDo":"khac","parentId":"bang-dao","blurb":"Quần thể kiến trúc bằng hàn băng rộng vài dặm nằm sâu trong băng đảo.","detail":"Hơn phân nửa khu vực đã sụp đổ, chỉ còn vết máu và dấu phá hoại. Các dấu vết khiến Hàn Lập nhận định người sống tại đây dường như đã bị Quái nga tàn sát, dù một nhóm người hầu của Ngân Sa cư sĩ vẫn còn ẩn trong lầu các.","theLucLienQuan":[],"nguon":["@c1552"]},{"id":"bang-dien-cua-ngan-sa-cu-si","name":"Băng điện của Ngân Sa cư sĩ","cn":"","capDo":"khac","parentId":"lam-ho-dao","blurb":"Công trình băng lớn từng thuộc về Ngân Sa cư sĩ và là nơi nhóm người hầu Hàn Tinh tộc sinh sống, làm việc.","detail":"Sau khi Ngân Sa cư sĩ chết, nhóm Hàn Tinh tộc thu dọn băng điện để Hàn Lập, Thanh Tiểu và thiếu phụ váy đen vào bàn bạc kế hoạch truy tìm hải thú.","theLucLienQuan":["Hàn Tinh tộc"],"nguon":["@c1553"]},{"id":"hai-vuc-cu-kinh-hai-thu-qua-lai","name":"Hải vực cự kình Hải thú qua lại","cn":"","capDo":"vuc","parentId":"hai-vuc-ngoai-loi-minh-dai-luc","blurb":"Vùng biển mà cự kình Hải thú thường xuyên qua lại trong gần trăm năm.","detail":"Hải vực có nhiều đảo lớn nhỏ và là nơi Hàn Lập lang thang tìm kiếm cự kình suốt mấy năm trước khi phát hiện mục tiêu.","theLucLienQuan":[],"nguon":["@c1554"]},{"id":"cac-dao-nho-trong-hai-vuc","name":"Các đảo nhỏ trong hải vực","cn":"","capDo":"khac","parentId":"hai-vuc-cu-kinh-hai-thu-qua-lai","blurb":"Những đảo nhỏ được Hàn Lập sử dụng làm nơi nghỉ chân trong quá trình tìm kiếm.","detail":"Các đảo có kích thước từ khoảng một dặm đến hơn mười dặm, giúp Hàn Lập đả tọa và khôi phục pháp lực giữa những đợt dò xét trên biển.","theLucLienQuan":[],"nguon":["@c1554"]},{"id":"dong-lon-duoi-day-bien","name":"Động lớn dưới đáy biển","cn":"","capDo":"khac","parentId":"hai-vuc-cu-kinh-hai-thu-qua-lai","blurb":"Một động lớn dưới đáy biển nơi Hàn Lập tìm được da Hải thú quý hiếm.","detail":"Tấm da Hải thú lớn và cứng cỏi tìm thấy tại đây đã được Hàn Lập dùng làm vật liệu luyện Cửu cung thiên kiền phù, Giáp Nguyên phù và Thái nhất hóa thanh phù.","theLucLienQuan":[],"nguon":["@c1554"]},{"id":"dao-nho-noi-nhi-thu-giang-co","name":"Đảo nhỏ nơi nhị thú giằng co","cn":"","capDo":"khac","parentId":"hai-vuc-cu-kinh-hai-thu-qua-lai","blurb":"Hòn đảo nơi cự kình Hải thú và Huyết diễm tôm đối đầu trước khi Hàn Lập xuất hiện.","detail":"Khu vực quanh đảo có nhiều đá ngầm, bầu trời u ám và sóng biển dữ dội do Huyết diễm tôm gọi tới. Hàn Lập phát hiện cự kình mục tiêu tại đây rồi đồng thời tấn công cả hai cự thú.","theLucLienQuan":[],"nguon":["@c1554"]},{"id":"vung-bien-gan-da-ngam","name":"Vùng biển gần đá ngầm","cn":"","capDo":"khac","parentId":"hai-vuc-ngoai-loi-minh-dai-luc","blurb":"Vùng biển nơi Hàn Lập giao chiến với cự tôm và cự kình hải thú.","detail":"Hàn Lập dùng Nguyên Từ Thần Sơn trấn áp cự tôm trên đá ngầm rồi lấy Xuân Lê kiếm trận nhốt cự kình hải thú. Sau cuộc giao chiến, đá ngầm đã bị ép chìm xuống đáy biển và mặt biển không còn dấu vết chiến đấu.","theLucLienQuan":[],"nguon":["@c1555"]},{"id":"truyen-tong-dai-sanh","name":"Truyền tống đại sảnh","cn":"","capDo":"khac","parentId":"loi-minh-dai-luc","blurb":"Đại sảnh đặt đầu bên kia của truyền tống pháp trận mà Hàn Lập sử dụng để tới Lôi Minh đại lục.","detail":"Căn phòng hình tứ giác rộng hơn trăm trượng, bốn vách có cấm chế, các cột đá phát sáng và một truyền tống pháp trận lớn nằm ở giữa. Hàn Lập tỉnh lại tại đây, mở cửa đá rồi nghe tiếng ồn ào từ bên ngoài.","theLucLienQuan":[],"nguon":["@c1555"]},{"id":"luc-quang-thanh","name":"Lục Quang Thành","cn":"","capDo":"thanh","parentId":"linh-gioi","blurb":"Thành nhỏ thuộc khu vực Thiên Vân mười ba tộc, có quảng trường lớn và hệ thống Truyền Tống trận. Thành hiện tập trung hàng vạn người chạy nạn và bị quân tiên phong Giác Xi Tộc áp sát.","detail":"Lục Quang Thành vốn không lớn nhưng có quảng trường rộng vài nghìn trượng cùng các Truyền Tống trận liên lạc với bên ngoài. Khi chiến sự lan tới, phần lớn đường truyền mất hiệu lực, dân chạy nạn tập trung đông đảo và những người trong thành chuẩn bị bỏ đi nhưng bị quân Giác Xi Tộc kiềm chế.","theLucLienQuan":["Thiên Vân mười ba tộc","Giác Xi Tộc"],"nguon":["@c1556","@c1569"]},{"id":"quang-truong-luc-quang-thanh","name":"Quảng trường Lục Quang Thành","cn":"","capDo":"khac","parentId":"luc-quang-thanh","blurb":"Quảng trường lát bạch thạch, rộng vài nghìn trượng và tập trung hàng vạn tu luyện giả thuộc nhiều dị tộc. Nơi đây được bao phủ bởi cấm chế dò xét cùng hạn chế cấm không.","detail":"Phần đông người tụ tập tại quảng trường là dân chạy nạn có tu vi Trúc Cơ hoặc Kim Đan, bên cạnh gần trăm tồn tại Nguyên Anh, Hóa Thần và ba tu sĩ Luyện Hư. Cấm chế tại đây khiến mọi người đứng dưới mặt đất và hỗ trợ phát hiện tu luyện giả cao giai mới xuất hiện.","theLucLienQuan":["Thiên Vân mười ba tộc"],"nguon":["@c1556"]},{"id":"tu-hoa-ho-quan-dao","name":"Tử Hỏa hô quần đảo","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Khu vực hải ngoại có đường Truyền Tống trận nối với Lục Quang Thành. Đường truyền từng hư hỏng hàng nghìn năm trước khi được Hàn Lập sửa chữa.","detail":"Hàn Lập dùng Không Vân Tinh sửa pháp trận tại Tử Hỏa hô quần đảo và truyền tống tới Lục Quang Thành. Sau lần vận hành này, đầu kết nối tại quần đảo đóng lại và chưa thể tái sử dụng ngay.","theLucLienQuan":[],"nguon":["@c1556"]},{"id":"mat-dao-phia-tay-luc-quang-thanh","name":"Mật đạo phía Tây Lục Quang Thành","cn":"","capDo":"khac","parentId":"luc-quang-thanh","blurb":"Lối thoát bí mật dẫn tới một địa điểm cách phía tây Lục Quang Thành hơn mười dặm.","detail":"Nguyên huynh đề nghị sử dụng mật đạo này khi đại chiến thuyền Giác Xi Tộc tập kích và đại trận phòng hộ thành bị ép tới cực hạn.","theLucLienQuan":["Thiên Vân mười ba tộc"],"nguon":["@c1557"]},{"id":"lau-cac-tai-tram-canh-gac","name":"Lầu các tại trạm canh gác","cn":"","capDo":"khac","parentId":"luc-quang-thanh","blurb":"Một lầu các đóng kín tại trạm canh gác trong Lục Quang Thành.","detail":"Bên trong công trình có khôi lỗi thần tượng bốn mắt bốn tay, dùng khoang bụng để che giấu một Truyền Tống pháp trận loại nhỏ.","theLucLienQuan":["Thiên Vân mười ba tộc"],"nguon":["@c1557"]},{"id":"bang-hoa-hac-nguc","name":"Băng hỏa hắc ngục","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi thuộc quyền kiểm soát của Giác Xi Tộc, được dùng để giam giữ và bắt tù binh làm nô lệ.","detail":"Nguyên huynh cảnh báo rằng người bị Giác Xi Tộc bắt có thể bị đưa tới Băng hỏa hắc ngục làm nô lệ.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1557"]},{"id":"ngan-dao","name":"Ngân đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Căn cứ trên không của lực lượng Giác Xi Tộc tại khu vực Lục Quang Thành.","detail":"Từ Ngân đảo, Giác Xi Tộc lần lượt tung hơn nghìn song đầu ưng, hơn trăm độc mộc màu đen chở giáp sĩ và bảy tám giao long hai cánh để truy sát người đào thoát.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1558"]},{"id":"dong-quat-cuoi-truyen-tong-tran","name":"Động quật cuối Truyền Tống Trận","cn":"","capDo":"khac","parentId":"mat-dao-phia-tay-luc-quang-thanh","blurb":"Động quật nhỏ ở đầu bên kia của Truyền Tống Trận giấu trong thần tượng khôi lỗi.","detail":"Không gian rộng hơn mười trượng, có tinh thạch chiếu sáng trên đỉnh và một thông đạo cao khoảng một trượng nối vào mật đạo rời Lục Quang Thành.","theLucLienQuan":[],"nguon":["@c1558"]},{"id":"son-coc-tai-ngon-nui-nho-vo-danh","name":"Sơn cốc tại ngọn núi nhỏ vô danh","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn cốc cách Lục Quang Thành hơn mười dặm, nằm lệch khỏi hướng bốn cửa thành.","detail":"Nhóm Hàn Lập phá vách đá ở cuối mật đạo để xuất hiện tại đây. Do vị trí không trùng với những hướng tháo chạy chính, cả nhóm tạm thời chưa gặp truy binh Giác Xi Tộc.","theLucLienQuan":[],"nguon":["@c1558"]},{"id":"van-thanh","name":"Vân thành","cn":"","capDo":"thanh","parentId":null,"blurb":"Điểm tập trung dự kiến của các trưởng lão Thiên Vân mười ba tộc trong cuộc đối đầu với Giác Xi Tộc.","detail":"Gã đầu to đề nghị những người mang hộp ngọc tới Vân thành. Các trưởng lão Thiên Vân mười ba tộc cùng nhiều đại trưởng lão Vạn Cổ Tộc dự kiến tập trung và tọa trấn tại đây để ứng phó Giác Xi Tộc.","theLucLienQuan":["Thiên Vân mười ba tộc","Vạn Cổ Tộc","Giác Xi Tộc"],"nguon":["@c1559","@c1577","@c1652","@c1664","@c1741"],"aliases":["Thiên Vân thành","Vân thành"]},{"id":"tieu-coc","name":"Tiểu cốc","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn cốc nhỏ nơi Hàn Lập giao chiến và tiêu diệt Hỏa Nguyệt.","detail":"Hàn Lập bố trí Xuân Lê Kiếm Trận tại đây, dùng các tầng huyễn cảnh che giấu Nguyên Từ Thần Sơn để nghiền nát thân thể Hỏa Nguyệt. Sau khi thẩm vấn nguyên thần thất bại, hắn phá viên châu và không để nguyên thần đối phương sống sót rời khỏi tiểu cốc.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1561"]},{"id":"ngan-sac-dai-dien-tren-luc-quang-thanh","name":"Ngân sắc đại điện trên Lục Quang Thành","cn":"","capDo":"khac","parentId":"luc-quang-thanh","blurb":"Tòa đại điện màu bạc trôi nổi phía trên Lục Quang Thành.","detail":"Đây là nơi Đồ huynh và trung niên nhân ngân bào phát hiện cấm chế trong thần niệm Hoằng Ngân đã biến mất. Sau khi kiểm tra mộc bài sinh mệnh và suy đoán nguyên nhân cái chết, hai người quyết định đích thân đi điều tra.","theLucLienQuan":[],"nguon":["@c1561"]},{"id":"khu-vuc-phu-can-luc-quang-thanh","name":"Khu vực phụ cận Lục Quang Thành","cn":"","capDo":"vuc","parentId":"luc-quang-thanh","blurb":"Vùng truy quét rộng lớn bao quanh Lục Quang Thành.","detail":"Song đầu ưng, ngân sắc giáp sĩ và kim sắc Vũ Giao lùng bắt những tu luyện giả đang ẩn nấp hoặc đào thoát tại đây. Khoảng mười tám người đã bị giết hoặc bắt làm tù binh.","theLucLienQuan":["Giác Xi Tộc","Thiên Vân chư tộc"],"nguon":["@c1562"]},{"id":"ngoai-luc-quang-thanh-bay-tam-chuc-dam","name":"Ngoài Lục Quang Thành bảy tám chục dặm","cn":"","capDo":"khac","parentId":"khu-vuc-phu-can-luc-quang-thanh","blurb":"Vị trí Hàn Lập tiến tới sau khi rời nơi giao chiến với Hoằng Diệt.","detail":"Hàn Lập dùng Hóa Thanh Phù ẩn giấu thân hình, vượt qua quân truy kích và đi tới khu vực cách Lục Quang Thành bảy tám chục dặm.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1562"]},{"id":"ngoai-luc-quang-thanh-may-tram-dam","name":"Ngoài Lục Quang Thành mấy trăm dặm","cn":"","capDo":"khac","parentId":"khu-vuc-phu-can-luc-quang-thanh","blurb":"Khu vực Hàn Lập đã chạy tới trước khi bị Thiên Huyền La Bàn khóa hướng.","detail":"Sau khi bí mật vượt vòng vây, Hàn Lập tiến ra ngoài Lục Quang Thành mấy trăm dặm. Thiên Huyền La Bàn sau đó chỉ đúng phương hướng hắn đang đào thoát.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1562"]},{"id":"khoang-khong-tren-ngan-sac-cu-dao","name":"Khoảng không trên ngân sắc cự đảo","cn":"","capDo":"khac","parentId":"khu-vuc-phu-can-luc-quang-thanh","blurb":"Nơi sáu người Giác Xi Tộc tập trung vận hành Thiên Huyền La Bàn.","detail":"Hai chỉ huy cùng bốn thuộc hạ dùng la bàn xác định bốn tồn tại cường đại tại đây. Sau đó bốn thuộc hạ chia thành hai nhóm, mang theo tám Vũ Giao để truy tìm mục tiêu.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1562"]},{"id":"rung-ram-gan-luc-quang-thanh","name":"Rừng rậm gần Lục Quang Thành","cn":"","capDo":"vuc","parentId":"luc-quang-thanh","blurb":"Khu rừng gần Lục Quang Thành nơi Đại Đầu Nhân ẩn mình.","detail":"Đại Đầu Nhân khoác áo choàng màu xám và che giấu khí tức trong rừng, khiến hai tu sĩ Giác Xi tộc cùng bốn vũ giao không thể tìm thấy.","theLucLienQuan":["Giác Xi tộc"],"nguon":["@c1564"]},{"id":"vung-nui-ngoai-luc-quang-thanh","name":"Vùng núi ngoài Lục Quang Thành","cn":"","capDo":"vuc","parentId":"luc-quang-thanh","blurb":"Vùng núi nơi dị tộc nhân đầu cá sấu đang phi độn.","detail":"Dị tộc nhân đầu cá sấu toàn lực phi hành qua vùng núi trong khi bị hai tu sĩ Luyện Hư Giác Xi tộc cưỡi phi xa bí mật bám theo.","theLucLienQuan":["Giác Xi tộc"],"nguon":["@c1564"]},{"id":"khu-rung-giua-hai-ngon-nui","name":"Khu rừng giữa hai ngọn núi","cn":"","capDo":"khac","parentId":null,"blurb":"Khu rừng giữa hai ngọn núi là nơi Hàn Lập chọn để dừng chạy và nghênh chiến lão giả họ Đồ.","detail":"Hàn Lập lao vào khu rừng giữa hai ngọn núi, dùng kiếm quang dọn sạch cây cối và bố trí chiến trường trước khi đối đầu với lão giả họ Đồ.","theLucLienQuan":[],"nguon":["@c1565"]},{"id":"khoang-dat-trong-trong-rung","name":"Khoảng đất trống trong rừng","cn":"","capDo":"khac","parentId":"khu-rung-giua-hai-ngon-nui","blurb":"Khoảng đất trống rộng vài trăm trượng được tạo ra giữa khu rừng để làm nơi giao chiến.","detail":"Hơn mười thanh tiểu kiếm của Hàn Lập cắt đổ toàn bộ đại thụ, tạo thành khoảng đất trống rồi ẩn vào hư không xung quanh.","theLucLienQuan":[],"nguon":["@c1565"]},{"id":"chien-truong-quanh-hac-son","name":"Chiến trường quanh hắc sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Đây là khu vực diễn ra trận chiến giữa Hàn Lập và lão giả họ Đồ. Địa hình bị biến đổi từ mặt đất đóng băng thành hồ dung nham rồi dần hiện lại cảnh sắc ban đầu.","detail":"Mặt đất quanh nơi giao chiến bị hàn băng bao phủ sau khi Hàn Lập phóng ngũ sắc quang diễm. Hỏa công của lão giả họ Đồ nung chảy khu vực thành hồ dung nham, trong khi thiên địa nguyên khí trong phạm vi mười dặm bị kéo về phía Xuân Lê kiếm trận.","theLucLienQuan":["Giác Xi tộc"],"nguon":["@c1566"]},{"id":"ngon-nui-hoang","name":"Ngọn núi hoang","cn":"","capDo":"khac","parentId":"loi-minh-dai-luc","blurb":"Nơi Hàn Lập tạm ẩn náu và hồi phục pháp lực sau khi rời chiến trường.","detail":"Hàn Lập ẩn dưới một tàng cây kín đáo trên ngọn núi hoang, hấp thu linh lực từ linh thạch đỉnh giai mộc thuộc tính rồi tĩnh tọa nửa ngày. Khi rời nơi này, pháp lực của hắn đã khôi phục được bảy tám phần.","theLucLienQuan":[],"nguon":["@c1569"]},{"id":"kim-giap-thanh","name":"Kim Giáp thành","cn":"","capDo":"thanh","parentId":"loi-minh-dai-luc","blurb":"Thành thị lớn nhất và có vị trí quan trọng, tập trung quân đội tinh nhuệ cùng nhiều tồn tại cấp cao của Thiên Vân mười ba tộc.","detail":"Hàn Lập chọn Kim Giáp thành làm đích đến sau khi xem hải vực đồ và tránh các thành thị lân cận đang có nguy cơ bị Giác Xi tộc kiểm soát. Lực lượng tập trung tại đây khiến thành trì trở thành nơi thích hợp để hắn tìm kiếm sự bảo hộ.","theLucLienQuan":["Thiên Vân mười ba tộc"],"nguon":["@c1569"]},{"id":"khu-vuc-bi-giac-xi-toc-phong-toa","name":"Khu vực bị Giác Xi tộc phong tỏa","cn":"","capDo":"vuc","parentId":null,"blurb":"Một khu vực rộng lớn đã bị Giác Xi tộc chiếm phần lớn và bố trí lực lượng tuần tra dày đặc.","detail":"Các tuyến đường hẻo lánh trong khu vực cũng thường xuyên xuất hiện đội giáp sĩ Giác Xi tộc. Chỉ còn hai thành thị đang bị bao vây nhưng chưa thất thủ.","theLucLienQuan":["Giác Xi tộc"],"nguon":["@c1570"]},{"id":"thanh-thi-vua-bi-giac-xi-toc-cong-chiem","name":"Thành thị vừa bị Giác Xi tộc công chiếm","cn":"","capDo":"thanh","parentId":"khu-vuc-bi-giac-xi-toc-phong-toa","blurb":"Thành thị mới rơi vào tay Giác Xi tộc và được dùng làm nơi bàn bạc việc truy bắt cùng kế hoạch mở rộng chiến sự.","detail":"Trong đại điện của thành thị, Ân Tôn giả triệu tập lão giả khô gầy và phụ nhân tóc hồng để nghe báo cáo về việc phong tỏa, truy tìm mục tiêu và công chiếm hai thành thị cuối cùng.","theLucLienQuan":["Giác Xi tộc"],"nguon":["@c1570"]},{"id":"tieu-son-vo-danh","name":"Tiểu sơn vô danh","cn":"","capDo":"khac","parentId":null,"blurb":"Tiểu sơn nơi Hàn Lập ẩn dưới tàng cây để quan sát cuộc vây bắt.","detail":"Hàn Lập ẩn thân tại tiểu sơn vô danh trước khi Giáp Thiên Mộc công khai làm lộ vị trí của hắn.","theLucLienQuan":["Giác Xi tộc"],"nguon":["@c1571"]},{"id":"khong-vuc-quanh-tieu-son","name":"Không vực quanh tiểu sơn","cn":"","capDo":"khac","parentId":"tieu-son-vo-danh","blurb":"Không vực quanh tiểu sơn là chiến trường của cuộc vây bắt và phản kích.","detail":"Giác Xi tộc vây bắt Giáp Thiên Mộc tại đây, hai chiến thuyền tiến hành oanh kích, rồi Hàn Lập dùng Kiếm Ti Nhâm hà quét sạch quân địch trong phạm vi trăm trượng.","theLucLienQuan":["Giác Xi tộc","Vạn Cổ tộc"],"nguon":["@c1571"]},{"id":"chien-thuyen-truyen-tong","name":"Chiến thuyền truyền tống","cn":"","aliases":[],"capDo":"khac","parentId":null,"blurb":"Chiến thuyền có bố trí truyền tống pháp trận và trực tiếp hỗ trợ nhóm tu sĩ Luyện Hư trên chiến trường.","detail":"Từ chiến thuyền, bốn tu sĩ Luyện Hư được truyền tống tới chiến trường. Chiến thuyền còn nguyên vẹn sau đó bắn hàng trăm cột sáng trắng xuống Hàn Lập để cứu viện.","theLucLienQuan":["Đội Luyện Hư kỳ trên chiến thuyền"],"nguon":["@c1573"]},{"id":"truyen-tong-tran-bi-mat-cua-thien-van-muoi-ba-toc","name":"Truyền tống trận bí mật của Thiên Vân mười ba tộc","cn":"","capDo":"khac","parentId":"khu-vuc-bi-giac-xi-toc-phong-toa","blurb":"Điểm truyền tống bí mật do một nhân viên đặc thù của Thiên Vân mười ba tộc thiết lập. Giáp Thiên Mộc chọn nơi này làm lối thoát khỏi vòng phong tỏa.","detail":"Truyền tống trận nằm trong khu vực do Giác Xi tộc kiểm soát và có thể đưa người ra ngoài. Hàn Lập đồng ý hộ tống Giáp Thiên Mộc tới đây để tránh các đội tuần tra và tìm đường rời chiến trường.","theLucLienQuan":["Thiên Vân mười ba tộc","Giác Xi tộc"],"nguon":["@c1574"]},{"id":"hoang-thuy-thanh","name":"Hoàng Thủy Thành","cn":"","capDo":"thanh","parentId":null,"blurb":"Hoàng Thủy Thành là thành thị lớn được hoàng sắc quang tráo bảo vệ và đang bị đại quân Giác Xi tộc bao vây.","detail":"Hơn trăm chiến thuyền cùng nhiều loại khôi lỗi của Giác Xi tộc phát động công kích quy mô lớn vào quang tráo phòng hộ của Hoàng Thủy Thành. Nếu thành thất thủ, Kim Giáp thành sẽ bị cô lập.","theLucLienQuan":["Giác Xi tộc"],"nguon":["@c1575"]},{"id":"cu-diem-bi-mat-cua-van-co-toc","name":"Cứ điểm bí mật của Vạn Cổ tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Cứ điểm bí mật của Vạn Cổ tộc nằm trong một điện phủ bằng đá ở núi cao và có truyền tống trận khẩn cấp.","detail":"Cứ điểm cách xa khu vực Giác Xi tộc chiếm giữ và không cách Vân Thành quá nửa ngày. Hàn Lập cùng Giáp Thiên Mộc đến đây sau khi sử dụng truyền tống trận.","theLucLienQuan":["Vạn Cổ tộc"],"nguon":["@c1575"]},{"id":"thien-van","name":"Thiên Vân","cn":"","capDo":"vuc","parentId":null,"blurb":"Thiên Vân là khu vực rộng lớn nơi Thiên Vân mười ba tộc hoạt động và Vân Thành tọa lạc.","detail":"Hàn Lập đang cân nhắc thời gian lưu lại Thiên Vân trong lúc Giác Xi tộc mở rộng chiến sự.","theLucLienQuan":["Thiên Vân mười ba tộc"],"nguon":["@c1575"]},{"id":"thien-huc-cac","name":"Thiên Húc các","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Một địa điểm nằm trong Vân Thành, nơi các trưởng lão Vạn Cổ tộc chờ Giáp Thiên Mộc.","detail":"Thủ vệ cửa thành chuyển lời rằng các trưởng lão Vạn Cổ tộc đã căn dặn Giáp Thiên Mộc phải tới Thiên Húc các ngay sau khi trở về.","theLucLienQuan":["Vạn Cổ tộc"],"nguon":["@c1576"]},{"id":"khu-vuc-nhan-toc","name":"Khu vực nhân tộc","cn":"","capDo":"vuc","parentId":"phong-nguyen-dai-luc","blurb":"Khu vực quê cũ của Hướng Chi Lễ và nơi Hàn Lập từng phi thăng tới linh giới.","detail":"Hướng Chi Lễ không còn hy vọng trở về khu vực nhân tộc do chi phí truyền tống, tu vi suy yếu và sự nguy hiểm của Man hoang thế giới.","theLucLienQuan":[],"nguon":["@c1578"]},{"id":"man-hoang-the-gioi","name":"Man hoang thế giới","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực nguy hiểm nằm trên đường trở về khu vực nhân tộc.","detail":"Hướng Chi Lễ cho rằng với tu vi hiện tại, ông không đủ khả năng vượt qua Man hoang thế giới để trở về khu vực nhân tộc.","theLucLienQuan":[],"nguon":["@c1578"]},{"id":"khong-gian-tiet-diem","name":"Không gian tiết điểm","cn":"","capDo":"khac","parentId":null,"blurb":"Lối đi không gian nơi Hàn Lập và những người đồng hành từng vượt qua.","detail":"Hàn Lập, Hướng Chi Lễ, Hô lão ma và Phong lão quái từng sử dụng không gian tiết điểm. Các đợt không gian gió lốc tại đây khiến Hô lão ma và Phong lão quái tử nạn, còn Hướng Chi Lễ trọng thương và mất gần hết tu vi.","theLucLienQuan":[],"nguon":["@c1578"]},{"id":"khach-san-cua-di-toc","name":"Khách sạn của dị tộc","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Địa điểm Hàn Lập dự định đến sau khi rời nơi ở.","detail":"Hàn Lập đi thú xa về phía khách sạn của dị tộc, nhưng sau đó chuyển tới khu vực có nhiều cửa hàng.","theLucLienQuan":[],"nguon":["@c1579"]},{"id":"cua-hang-dien-tich","name":"Cửa hàng điển tịch","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Cửa hàng tại Vân Thành do nữ tử Tinh tộc làm chủ.","detail":"Cửa hàng bày bán thạch phiến, ngọc điệp, ngân bài và nhiều loại sách được che bởi quang mạc. Hàn Lập chọn hơn hai mươi quyển điển tịch tại đây.","theLucLienQuan":["Tinh tộc"],"nguon":["@c1579"]},{"id":"tuong-thanh-van-thanh","name":"Tường thành Vân Thành","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Tường thành nơi đặt quả cầu khổng lồ được xác định là chiến tranh khôi lỗi.","detail":"Hàn Lập quan sát quả cầu khổng lồ trên tường thành và biết đó là một trong mười ba chiến tranh khôi lỗi lớn của Thiên Vân mười ba tộc.","theLucLienQuan":["Thiên Vân mười ba tộc"],"nguon":["@c1579"]},{"id":"tieu-khong-gian","name":"Tiểu không gian","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian bí mật được mở để Hàn Lập và nữ tử Tinh tộc trao đổi mà không bị phát hiện.","detail":"Tiểu không gian rộng hơn bốn mươi trượng, bên trong chỉ có một bàn và hai ghế.","theLucLienQuan":["Tinh tộc"],"nguon":["@c1580"]},{"id":"co-ma-gioi","name":"Cổ ma giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Nơi được Hàn Lập đối chiếu khi xem xét nguồn gốc ma công và ma khí.","detail":"Cổ ma giới được nhắc tới trong quá trình Hàn Lập liên hệ ma khí với nguồn gốc ma công của mình.","theLucLienQuan":[],"nguon":["@c1580"]},{"id":"ma-kim-son-mach","name":"Ma Kim Sơn Mạch","cn":"魔金山脈","capDo":"vuc","parentId":null,"blurb":"Ma Kim Sơn Mạch là dãy núi đen xuất hiện sau một vùng không gian gió lốc, cách Vân Thành khoảng một tháng đường.","detail":"Sơn mạch bị ma khí nồng đậm bao phủ, bên trong có nhiều khe không gian tuôn ra ma khí và ma thú cấp cao. Các thánh tộc từng tiến vào trung tâm rồi phong tỏa khu vực, chỉ để lại một lối vào và giới hạn thời gian tiến nhập hằng năm. Nơi đây có tài liệu quý hiếm nhưng tỷ lệ người sống sót trở ra chưa tới một phần mười.","theLucLienQuan":["Thiên Vân Tộc","Thánh tộc"],"nguon":["@c1581","@c1582","@c1605","@c1651","@c1661"]},{"id":"ma-vuc-quanh-ma-kim-son-mach","name":"Ma vực quanh Ma Kim Sơn Mạch","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Ma vực bao quanh Ma Kim Sơn Mạch bị ma khí bao phủ và lan rộng.","detail":"Khu vực rộng khoảng trăm dặm quanh sơn mạch chịu ảnh hưởng của ma khí. Tu sĩ ở lại quá lâu có nguy cơ bị ma khí đồng hóa thành ma vật.","theLucLienQuan":[],"nguon":["@c1581"]},{"id":"bat-van-xuyen-son","name":"Bát Vân Xuyên Sơn","cn":"","capDo":"vuc","parentId":"van-thanh","blurb":"Bát Vân Xuyên Sơn là quần thể tám ngọn linh sơn trong Vân Thành.","detail":"Khu vực này có tám cực phẩm linh mạch, các động phủ cho thuê với giá cao và là nơi duy nhất trong Vân Thành cho phép phi độn.","theLucLienQuan":[],"nguon":["@c1582"]},{"id":"van-ha-son","name":"Vân Hà Sơn","cn":"","capDo":"vuc","parentId":"bat-van-xuyen-son","blurb":"Vân Hà Sơn là một trong tám linh sơn thuộc Bát Vân Xuyên Sơn.","detail":"Động phủ của Giáp Thiên Mộc nằm tại Vân Hà Sơn, nơi Hàn Lập đến nhận thông linh khôi lỗi.","theLucLienQuan":[],"nguon":["@c1582","@c1584"]},{"id":"dong-phu-cua-giap-thien-moc","name":"Động phủ của Giáp Thiên Mộc","cn":"","capDo":"tieu-khong-gian","parentId":null,"blurb":"Động phủ nơi Hàn Lập và Giáp Thiên Mộc trao đổi về các khôi lỗi.","detail":"Tại đây Giáp Thiên Mộc trình diễn khôi lỗi bạch xà, còn Hàn Lập cho xem nhóm linh thị.","theLucLienQuan":["Vạn Cổ Tộc"],"nguon":["@c1583"]},{"id":"dai-luc","name":"Đại lục","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Đại lục là điểm đến của truyền tống trận được nhắc đến trong chương.","detail":"Hàn Lập dò hỏi truyền tống trận từ Thiên Vân đến đại lục và được xác nhận rằng trận pháp này tồn tại.","theLucLienQuan":[],"nguon":["@c1583"]},{"id":"dai-luc-khac","name":"Đại lục khác","cn":"","capDo":"chau","parentId":null,"blurb":"Đại lục khác là đích đến Hàn Lập muốn tới bằng truyền tống trận.","detail":"Khả năng đến đại lục khác còn phụ thuộc vào thân phận và công trạng của Hàn Lập.","theLucLienQuan":[],"nguon":["@c1584"]},{"id":"noi-o-cua-han-lap","name":"Nơi ở của Hàn Lập","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Hàn Lập kiểm tra khôi lỗi và chuẩn bị nghiên cứu ngọc hạp.","detail":"Hàn Lập phong tỏa nơi ở bằng cấm chế, trận kỳ, nhiều tầng quang mạc và hắc sắc tiểu sơn trước khi phá giải cấm chế trên ngọc hạp.","theLucLienQuan":[],"nguon":["@c1584"]},{"id":"tay-thanh","name":"Tây thành","cn":"","capDo":"thanh","parentId":"van-thanh","blurb":"Tây thành là khu vực thuộc Vân thành, nơi chấp pháp vệ đội Tây thành hoạt động.","detail":"Chấp pháp vệ đội Tây thành xuất hiện tại phòng Hàn Lập để điều tra cột sáng do Nghiễm Hàn Lệnh phát ra.","theLucLienQuan":["Chấp pháp vệ đội Tây thành Vân thành"],"nguon":["@c1585"]},{"id":"phong-cua-han-lap","name":"Phòng của Hàn Lập","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Phòng của Hàn Lập là nơi ngọc hạp được mở và Nghiễm Hàn Lệnh được kích hoạt.","detail":"Hàn Lập tháo phong ấn ngọc hạp trong phòng. Cấm chế phát nổ, Nghiễm Hàn Lệnh phóng cột sáng xuyên nóc nhà, rồi chấp pháp vệ đội và Bạch trưởng lão xuất hiện.","theLucLienQuan":["Chấp pháp vệ đội Tây thành Vân thành"],"nguon":["@c1585"]},{"id":"nghiem-han-gioi","name":"Nghiễm Hàn Giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Nghiễm Hàn Giới là nơi các thế lực muốn đưa người trong tộc tiến vào thông qua Nghiễm Hàn Lệnh.","detail":"Việc tiến vào Nghiễm Hàn Giới liên quan đến Nghiễm Hàn Lệnh và pháp trận khởi động do Vạn Cổ Tộc chuẩn bị.","theLucLienQuan":["Vạn Cổ Tộc","Thủy Mị Tộc","Âm Yêu Tộc"],"nguon":["@c1586","@c1588"]},{"id":"khu-vuc-bien-canh-giac-xi-toc","name":"Khu vực biên cảnh Giáp Xi Tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực biên cảnh Giáp Xi Tộc từng là nơi Giáp đại sư gặp nguy hiểm.","detail":"Giáp đại sư suýt thất thủ tại khu vực do Giáp Xi Tộc chiếm lĩnh, các hộ vệ đi cùng ông bỏ mạng và ông được Hàn Lập ra tay giúp đỡ.","theLucLienQuan":["Giáp Xi Tộc","Vạn Cổ Tộc"],"nguon":["@c1586"]},{"id":"thong-linh-dien","name":"Thông Linh Điện","cn":"","aliases":[],"capDo":"khac","parentId":"thanh-tri-nhieu-lop-phia-sau-bat-van-son","blurb":"Đại điện màu bích lục ở trung tâm thành trì bí mật phía sau Bát Vân Sơn, là trọng địa của Vạn Cổ Tộc.","detail":"Thông Linh Điện là nơi Thiên Cơ Tử đưa Hàn Lập đến để bàn chuyện Nghiễm Hàn Lệnh. Cửa điện có hai thông linh khôi lỗi cấp thượng tộc cửu giai bảo vệ và sẽ công kích người không được phép tiếp cận.","theLucLienQuan":["Vạn Cổ Tộc"],"nguon":["@c1587","@c1740"]},{"id":"thanh-tri-nhieu-lop-phia-sau-bat-van-son","name":"Thành trì nhiều lớp phía sau Bát Vân Sơn","cn":"","aliases":[],"capDo":"thanh","parentId":"bat-van-xuyen-son","blurb":"Một thành nhỏ bí mật của Vạn Cổ Tộc nằm phía sau Bát Vân Sơn, có nhiều lớp tường thành xếp cao dần vào trung tâm.","detail":"Thành trì có bảy tám lớp tường xếp như kim tự tháp. Hệ thống phòng thủ gồm điêu tượng ngân sắc, giáp sĩ khôi lỗi, bốn cột lớn nhiều màu và phù văn, còn Thông Linh Điện nằm tại khu vực trung tâm.","theLucLienQuan":["Vạn Cổ Tộc"],"nguon":["@c1587"]},{"id":"bat-van-son","name":"Bát Vân Sơn","cn":"","capDo":"vuc","parentId":null,"blurb":"Bát Vân Sơn là nơi Vạn Cổ Tộc dự định sắp xếp động phủ miễn phí cho Hàn Lập.","detail":"Hàn Lập được đề nghị đến Bát Vân Sơn để tu luyện và chờ thời điểm Nghiễm Hàn Giới mở ra.","theLucLienQuan":["Vạn Cổ Tộc"],"nguon":["@c1589","@c1740"]},{"id":"khach-san-moi-gan-bat-van-son","name":"Khách sạn mới gần Bát Vân Sơn","cn":"","capDo":"khac","parentId":"bat-van-son","blurb":"Đây là nơi Hàn Lập tạm trú sau khi rời thành.","detail":"Khách sạn có kiến trúc giống Nhân tộc và được Hàn Lập bố trí pháp khí phòng hộ.","theLucLienQuan":[],"nguon":["@c1589"]},{"id":"dong-phu-bat-van-son","name":"Động phủ Bát Vân Sơn","cn":"","capDo":"khac","parentId":"bat-van-son","blurb":"Động phủ mới do Thiên Cơ Tử sắp xếp cho Hàn Lập tại Bát Vân Sơn.","detail":"Nơi này có linh khí không kém Vân Hà Sơn, được trang bị đan phòng, luyện khí thất và dược viên. Hàn Lập bố trí nhiều lớp cấm chế rồi luyện đan và tu luyện tại đây trong một năm.","theLucLienQuan":[],"nguon":["@c1590"]},{"id":"luc-canh-thanh","name":"Lục Cảnh thành","cn":"","capDo":"thanh","parentId":null,"blurb":"Thành trì nơi Hàn Lập từng nghe các dị tộc nhân nhắc đến Vạn Diệu Đan.","detail":"Địa danh được nhắc lại khi Hàn Lập nhớ tới thông tin trước đây về giá trị của Vạn Diệu Đan.","theLucLienQuan":[],"nguon":["@c1590"]},{"id":"thien-dien-dau-gia","name":"Thiên điện","cn":"","capDo":"khac","parentId":"dai-dien-dau-gia","blurb":"Khu vực phụ thuộc đại điện đấu giá tại Vân thành.","detail":"Thiết Kiến dự định đến đây bán một số vật phẩm lấy linh thạch và mời Hàn Lập cùng đi.","theLucLienQuan":["Thạch Kiến Tộc"],"nguon":["@c1590"]},{"id":"khu-giao-dich-tu-do","name":"Khu giao dịch tự do","cn":"","capDo":"khac","parentId":"thien-dien-dau-gia","blurb":"Một sân giao dịch rộng trong thiên điện, nơi tu sĩ tự do mua bán và trao đổi vật phẩm.","detail":"Khu vực có nhiều quang mạc hình bán cầu do tiểu phiên dựng nên. Những quang mạc này che kín người giao dịch và ngăn thần niệm bên ngoài dò xét.","theLucLienQuan":["Tứ Tộc Đấu Giá Hội"],"nguon":["@c1591"]},{"id":"khu-thach-bich-va-ngoc-oc","name":"Khu thạch bích và ngọc ốc","cn":"","capDo":"khac","parentId":"thien-dien-dau-gia","blurb":"Một khu vực trong thiên điện có thạch bích ghi ngân sắc văn tự và nhiều ngọc ốc được quang hà bao phủ.","detail":"Thạch bích cao hơn mười trượng thu hút nhiều tu sĩ theo dõi. Xung quanh có các ngọc ốc trắng sáng cùng một lầu các trung tâm phủ khói xanh; chức năng cụ thể của khu vực chưa được giải thích.","theLucLienQuan":["Tứ Tộc Đấu Giá Hội"],"nguon":["@c1591"]},{"id":"khu-san-rong-truoc-lau-cac-do","name":"Khu sân rộng trước lầu các đỏ","cn":"","capDo":"khac","parentId":"khu-giao-dich-tu-do","blurb":"Khoảng sân nơi Hàn Lập xem các thạch bích và chạm mặt nữ tử áo lam.","detail":"Khu sân rộng tập trung các thạch bích ghi danh mục thiên tài địa bảo. Tại đây Hàn Lập chứng kiến Đoạn Thiên Nhận xuất hiện và bị ông lưu ấn ký theo dõi.","theLucLienQuan":["Tứ Tộc Đấu Giá Hội","Thạch Kiến Tộc"],"nguon":["@c1592"]},{"id":"lau-cac-do","name":"Lầu các đỏ","cn":"","capDo":"khac","parentId":"khu-giao-dich-tu-do","blurb":"Nơi Khâu đạo hữu tranh cãi với người bán về một vật phẩm bị nhận định là giả.","detail":"Tiếng tranh chấp giữa Khâu đạo hữu và người bán vang ra từ lầu các đỏ. Đoạn Thiên Nhận bước ra khỏi nơi này sau khi rời khu giao dịch bên trong.","theLucLienQuan":["Tứ Tộc Đấu Giá Hội"],"nguon":["@c1592"]},{"id":"muoi-ba-ngoc-oc","name":"Mười ba ngọc ốc","cn":"","capDo":"khac","parentId":"khu-giao-dich-tu-do","blurb":"Mười ba gian phòng nằm cách khu thạch bích một khoảng, mỗi gian mang một con số vàng lơ lửng.","detail":"Hàn Lập đối chiếu số trên các ngọc ốc với ngân sắc văn tự trên thạch bích và suy ra đây là những nơi chứa tài liệu tương ứng.","theLucLienQuan":["Tứ Tộc Đấu Giá Hội"],"nguon":["@c1592"]},{"id":"thuan-huong-cac","name":"Thuần Hương Các","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Địa điểm Đoạn Thiên Nhận chọn để chờ Hàn Lập sau cuộc gặp tại khu giao dịch.","detail":"Đoạn Thiên Nhận yêu cầu Hàn Lập đến Thuần Hương Các để trao đổi tâm đắc Luyện Thể Thuật, đồng thời cảnh cáo hắn không được tìm cách rời đi.","theLucLienQuan":["Thạch Kiến Tộc"],"nguon":["@c1592"]},{"id":"van-chau","name":"Vân Châu","cn":"","capDo":"chau","parentId":"loi-minh-dai-luc","blurb":"Khu vực nơi Cửu Hương Linh Tửu được một số tu sĩ ca tụng là loại linh tửu đứng đầu.","detail":"Danh tiếng của Cửu Hương Linh Tửu do Thái tiên tử luyện chế được biết đến trong phạm vi Vân Châu.","theLucLienQuan":["Tinh Tộc"],"nguon":["@c1593"]},{"id":"khu-giam-dinh-dau-gia-hoi","name":"Khu giám định đấu giá hội","cn":"","capDo":"khac","parentId":"dai-dien-dau-gia","blurb":"Khu vực thẩm định bảo vật trước khi đưa vào đấu giá.","detail":"Khu giám định gồm hành lang có biển Giám định và một phòng đá trắng rộng hơn ba mươi trượng. Phòng có thanh sắc quang mạc, bàn ghế và một truyền tống trận đơn giản.","theLucLienQuan":["Đấu giá hội Vân thành"],"nguon":["@c1596"]},{"id":"dai-dien-dau-gia-van-thanh","name":"Đại điện đấu giá Vân thành","cn":"","capDo":"thanh","parentId":"van-thanh","blurb":"Đại điện tổ chức cuộc đấu giá tại Vân thành.","detail":"Đại điện có đông người tham dự và nhiều thị vệ, đồng thời nối với khu giám định cùng thính đường ba tầng.","theLucLienQuan":["Đấu giá hội Vân thành"],"nguon":["@c1596"]},{"id":"thing-duong-dau-gia-ba-tang","name":"Thính đường đấu giá ba tầng","cn":"","capDo":"khac","parentId":"dai-dien-dau-gia-van-thanh","blurb":"Thính đường ba tầng dành cho người tham dự cuộc đấu giá.","detail":"Tầng giữa và tầng dưới có bàn ghế trắng huyền phù cho người tham dự thông thường. Tầng trên được cấm chế gia cố và dành cho người có thân phận, địa vị tại Vân thành.","theLucLienQuan":["Đấu giá hội Vân thành"],"nguon":["@c1596"]},{"id":"tang-ba-dai-dien-dau-gia","name":"Tầng ba đại điện đấu giá","cn":"","capDo":"khac","parentId":"dai-dien-dau-gia","blurb":"Khu vực dành cho những nhân vật có địa vị và tu vi cao trong đại điện đấu giá.","detail":"Lão giả họ Lục ở tầng ba trả giá thắng tử hồ rồi bay xuống nhận linh thú.","theLucLienQuan":["Bốn tộc tổ chức đấu giá hội"],"nguon":["@c1600"]},{"id":"phien-hai-vuc-gan-dong-phu-nhan-dien-giao","name":"Phiến hải vực gần động phủ Nhân Diện Giao","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biển gần động phủ Nhân Diện Giao, nơi nhóm lão Ông săn bắt linh thú.","detail":"Nhóm khách khanh đã săn bắt linh thú tại vùng biển này mà không biết đó là khu vực gần động phủ của Nhân Diện Giao.","theLucLienQuan":["Nhân Diện Giao"],"nguon":["@c1601"]},{"id":"dong-phu-nhan-dien-giao","name":"Động phủ Nhân Diện Giao","cn":"","capDo":"khac","parentId":"phien-hai-vuc-gan-dong-phu-nhan-dien-giao","blurb":"Động phủ của Nhân Diện Giao, nơi tử sắc ấu thú vốn phải ở lại.","detail":"Tử sắc ấu thú tự ý rời động phủ rồi bị nhóm lão Ông bắt giữ ở vùng biển gần đó.","theLucLienQuan":["Nhân Diện Giao"],"nguon":["@c1601"]},{"id":"tu-vi-hai","name":"Tử Vi hải","cn":"","capDo":"vuc","parentId":null,"blurb":"Tử Vi hải là địa bàn của Nhân Diện Giao.","detail":"Nhóm lão Ông bị Nhân Diện Giao cấm đặt chân vào Tử Vi hải; nếu vi phạm sẽ bị xử trí.","theLucLienQuan":[],"nguon":["@c1602"]},{"id":"dien-trong-van-thanh","name":"Điện trong Vân thành","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Điện trong Vân thành là nơi diễn ra việc xử phạt và hòa giải.","detail":"Nhân Diện Giao xử phạt nhóm lão Ông, nữ đồng tử sắc phát hiện khí tức của Hàn Lập, và Hàn Lập bị tiếp cận tại nơi này.","theLucLienQuan":[],"nguon":["@c1602"]},{"id":"dong-phu-lao-gia-ho-luc","name":"Động phủ của lão giả họ Lục","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi lão giả họ Lục được khuyên trở về dưỡng thương.","detail":"Tiêu Bố Y khuyên lão giả họ Lục trở về động phủ dưỡng thương sau khi bị chém mất một cánh tay.","theLucLienQuan":[],"nguon":["@c1603"]},{"id":"khe-khong-gian-rieng-cua-tiem-tiem","name":"Khe không gian riêng của Tiêm Tiêm","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian bí mật nơi Tiêm Tiêm đưa Hàn Lập đến gặp Việt Tông.","detail":"Tiêm Tiêm dùng pháp bàn và ngũ sắc quang hà để đưa Hàn Lập vào khe không gian riêng, nơi Việt Tông đang chờ sẵn.","theLucLienQuan":["Tinh tộc"],"nguon":["@c1605"]},{"id":"cua-hang-bi-mat","name":"Cửa hàng bí mật","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Tiêm Tiêm chờ Hàn Lập sau khi Nghiễm Hàn Giới mở ra.","detail":"Cửa hàng đóng kín và được che giấu với khách bên ngoài; Hàn Lập dùng pháp quyết mở cửa để gặp Tiêm Tiêm.","theLucLienQuan":[],"nguon":["@c1605"]},{"id":"chan-linh-chi-huyet","name":"Chân linh chi huyệt","cn":"","capDo":"khac","parentId":null,"blurb":"Một địa điểm bí mật chứa tin tức và cơ duyên liên quan đến Chân linh Kỳ lân.","detail":"Tiêm Tiêm và Kỳ Ảnh dự định tiến vào Chân linh chi huyệt để tìm cơ duyên. Họ lo ngại nơi này có thể đã bị thánh giai ma thú hoặc phân thần Kỳ lân khác chiếm trước.","theLucLienQuan":[],"nguon":["@c1607","@c1621"]},{"id":"thanh-linh-van-hai","name":"Thanh linh vân hải","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Biển mây xanh do cấm chế hình thành tại Ma Kim Sơn Mạch.","detail":"Việt Tông cho biết Thanh linh vân hải là lối đi duy nhất để tiến vào Ma Kim Sơn Mạch; xông vào từ nơi khác sẽ nguy hiểm đến tính mạng.","theLucLienQuan":[],"nguon":["@c1607"]},{"id":"loi-van-cac","name":"Lôi Vân Các","cn":"","capDo":"khac","parentId":"vu-hai","blurb":"Lầu các năm tầng nằm giữa khu nhà đá trong vụ hải.","detail":"Lôi Vân Các là nơi cấp lệnh bài và vật phẩm cần thiết để tiến vào Ma Kim Sơn Mạch.","theLucLienQuan":["Lôi Vân Các"],"nguon":["@c1608"]},{"id":"tran-ben-ngoai-ma-kim-son-mach","name":"Trấn bên ngoài Ma Kim Sơn Mạch","cn":"","capDo":"khac","parentId":"ma-kim-son-mach","blurb":"Trấn bên ngoài Ma Kim Sơn Mạch là nơi nhiều tu luyện giả tụ tập trước khi tiến vào sơn mạch.","detail":"Nơi đây cũng là địa điểm Cốc tiền bối lưu lại và treo thưởng Chi tiên.","theLucLienQuan":[],"nguon":["@c1609"]},{"id":"loi-van-tran","name":"Lôi Vân Trấn","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực có quy củ nghiêm ngặt về việc giải quyết tranh chấp và tiến vào Ma Kim Sơn Mạch.","detail":"Tranh chấp tại Lôi Vân Trấn phải được giải quyết bằng đấu pháp giữa những người có tu vi tương đương tại nơi chuyên dụng. Người gây rối có thể bị trưởng lão hội hủy tư cách tiến vào Ma Kim Sơn Mạch và trục xuất khỏi trấn.","theLucLienQuan":["Trưởng lão hội Lôi Vân Trấn"],"nguon":["@c1610"]},{"id":"lau-cac-kiem-tra-tu-cach","name":"Lầu các kiểm tra tư cách","cn":"","capDo":"khac","parentId":"thi-tran-ngoai-ma-kim-son-mach","blurb":"Công trình năm tầng trong thị trấn, nơi kiểm tra người muốn tiến vào Ma Kim Sơn Mạch.","detail":"Mẫn chấp sự trấn giữ lầu các này, kiểm tra tư cách và phát Ích Lôi Tán cho người đạt yêu cầu.","theLucLienQuan":[],"nguon":["@c1611"]},{"id":"tang-bon-lau-cac-kiem-tra","name":"Tầng bốn lầu các","cn":"","capDo":"khac","parentId":"lau-cac-kiem-tra-tu-cach","blurb":"Tầng bốn là nơi Mẫn chấp sự điều khiển pháp trận kiểm tra.","detail":"Không gian có vách và trần trong suốt phát ánh sáng xanh, đặt một pháp trận trắng rộng hơn hai mươi trượng.","theLucLienQuan":[],"nguon":["@c1611"]},{"id":"thi-tran-ngoai-ma-kim-son-mach","name":"Thị trấn ngoài Ma Kim Sơn Mạch","cn":"","capDo":"khac","parentId":"ma-kim-son-mach","blurb":"Thị trấn nhỏ nơi nhóm Hàn Lập hoàn tất thủ tục trước khi tiến vào sơn mạch.","detail":"Thị trấn có ít cửa hàng, phần lớn buôn bán tài liệu ma thú. Đây là nơi Hàn Lập, Tiêm Tiêm và Việt Tông nhận tư cách cùng Ích Lôi Tán.","theLucLienQuan":[],"nguon":["@c1611"]},{"id":"dai-trach-vien-cua-vi-thanh-toc","name":"Đại trạch viện của vị Thánh tộc","cn":"","capDo":"khac","parentId":"thi-tran-ngoai-ma-kim-son-mach","blurb":"Đại trạch viện đóng kín được bảo vệ bằng cấm chế cao minh.","detail":"Thần niệm của Hàn Lập bị cấm chế ngăn lại. Hắn suy đoán đây có thể là nơi ở của vị Thánh tộc treo thưởng Chi tiên nhưng không cưỡng ép xâm nhập.","theLucLienQuan":["Thánh tộc"],"nguon":["@c1611"]},{"id":"khu-vuc-loi-dien-ngoai-ma-kim-son-mach","name":"Khu vực lôi điện ngoài Ma Kim Sơn Mạch","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Vùng không trung đầy điện quang bao phủ bên ngoài Ma Kim Sơn Mạch.","detail":"Khu vực có vô số thanh sắc điện quang và tiếng sấm liên tục, tạo thành lớp ngăn cách mà người tiến vào phải dùng Ích Lôi Tán để vượt qua.","theLucLienQuan":[],"nguon":["@c1611"]},{"id":"khu-vuc-ngoai-vi-ma-kim-son-mach","name":"Khu vực ngoại vi Ma Kim Sơn Mạch","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Khu vực ngoại vi nằm ở phần sâu của tuyến ngoài Ma Kim Sơn Mạch.","detail":"Đàn ma nha vốn sống sâu trong sơn mạch lại xuất hiện tại khu vực này, tạo dấu hiệu bất thường.","theLucLienQuan":[],"nguon":["@c1612"]},{"id":"loi-dien-the-gioi","name":"Lôi điện thế giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Khu vực mà toán bốn người do đại hán mặt đen dẫn đầu vượt qua trước khi vào Ma Kim Sơn Mạch.","detail":"Đại hán mặt đen cùng ba người đồng hành chạy ra khỏi khu vực lôi điện rồi dùng pháp bàn xác định phương hướng.","theLucLienQuan":[],"nguon":["@c1612"]},{"id":"vu-hai-hac-sac","name":"Vụ hải hắc sắc","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Vùng sương ma khí đen dày đặc bao phủ phần lớn núi non.","detail":"Vụ hải che khuất cảnh vật, hạn chế thần niệm và khiến ma vật nhiều mắt có thể ẩn náu ở cuối chương.","theLucLienQuan":[],"nguon":["@c1612"]},{"id":"tieu-son-cach-nhom-han-lap-muoi-dam","name":"Tiểu sơn cách nhóm Hàn Lập khoảng mười dặm","cn":"","capDo":"khac","parentId":"vu-hai-hac-sac","blurb":"Một ngọn núi nhỏ trong vụ hải, cách nhóm Hàn Lập khoảng mười dặm.","detail":"Đây là nơi ma vật bí ẩn để lộ huyết quang cùng hơn mười con mắt đỏ trong phần sâu của vụ hải.","theLucLienQuan":[],"nguon":["@c1612"]},{"id":"vu-hai-trong-ma-kim-son-mach","name":"Vụ hải trong Ma Kim Sơn Mạch","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Khu vực vụ hải nằm dưới đường bay trong Ma Kim Sơn Mạch, nơi quang nhận màu đen tạo thành một khe sâu.","detail":"Vụ hải nằm trong Ma Kim Sơn Mạch, bên dưới đường bay của các tu sĩ. Quang nhận màu đen của Thiết Ma bổ xuống nơi này, tạo thành một khe rộng hơn mười trượng, tối đen và không nhìn thấy đáy.","theLucLienQuan":[],"nguon":["@c1614"]},{"id":"dai-suong-trang-chan-ngang-son-mach","name":"Dải sương trắng chắn ngang sơn mạch","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Dải sương trắng mới xuất hiện chắn ngang Ma Kim Sơn mạch và chứa sát khí nguy hiểm.","detail":"Dải sương trải dài như thác nước vô tận. Hàn Lập và Việt Tông nghi bên trong có ma thú cực mạnh hoặc cả đàn ma thú cao giai, nên đoàn phải chuẩn bị thủ đoạn hộ thân trước khi tiến vào.","theLucLienQuan":["Người Linh giới"],"nguon":["@c1615"]},{"id":"khu-rung-dai-thu-ky-quai","name":"Khu rừng đại thụ kỳ quái","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Khu rừng có những cây đại thụ cao hơn mười trượng, nơi Khuê Hoán truy đuổi linh chu.","detail":"Ba lam bào nhân chạy qua khu rừng bằng linh chu màu vàng nhạt trong khi Khuê Hoán truy sát phía sau.","theLucLienQuan":["Người Linh giới"],"nguon":["@c1615"]},{"id":"khong-gian-trong-xuan-le-kiem-tran","name":"Không gian trong Xuân Lệ kiếm trận","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian trong Xuân Lệ kiếm trận được huyễn hóa thành rừng cự mộc màu xanh không thấy điểm cuối. Cảnh vật trong khu vực này đan xen hư thực.","detail":"Khu vực có tán cây che kín bầu trời và rừng cự mộc trải rộng. Cảnh vật vừa có tính huyễn hóa vừa có lực phản chấn thực chất, khiến ma thú phi hành bị hạn chế.","theLucLienQuan":[],"nguon":["@c1617"]},{"id":"khe-ho-hu-khong-canh-phe-linh-hoa-dieu","name":"Khe hở hư không cạnh Phệ Linh hỏa điểu","cn":"","capDo":"khac","parentId":null,"blurb":"Khe hở hư không được Hàn Lập mở ra trong hình thái Thải phượng để tiếp cận cuộc giao chiến của hai loại linh hỏa.","detail":"Khe hở nối vị trí ban đầu của Hàn Lập với khu vực Phệ Linh hỏa điểu đang giao chiến cùng Kim Ô Chân Hỏa. Hàn Lập xuyên qua khe hở và xuất hiện cạnh chiến trường.","theLucLienQuan":[],"nguon":["@c1617"]},{"id":"son-coc-bi-an","name":"Sơn cốc bí ẩn","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Sơn cốc sâu trong Ma Kim Sơn Mạch, nơi Cự Thử tập hợp đại quân ma thú.","detail":"Cự Thử tập hợp hơn một ngàn ma thú đã khai mở linh trí tại sơn cốc này để phát động cuộc săn người ngoại lai và tìm Chi tiên.","theLucLienQuan":["Đại quân ma thú dưới quyền Cự Thử"],"nguon":["@c1619"]},{"id":"dia-cung","name":"Địa cung","cn":"","capDo":"khac","parentId":"ma-kim-son-mach","blurb":"Địa cung là nơi Thiết Sí và Đa Nhãn được chờ đợi nhưng chưa xuất hiện.","detail":"Sự vắng mặt của Thiết Sí và Đa Nhãn tại địa cung khiến đại hán sắc mặt tái nhợt nghi ngờ tình hình có biến.","theLucLienQuan":[],"nguon":["@c1619"]},{"id":"thach-phong-co-cam-che","name":"Thạch phòng có cấm chế","cn":"","capDo":"khac","parentId":"ma-kim-son-mach","blurb":"Thạch phòng nơi đại hán sắc mặt tái nhợt nhận tin từ vẹt huyết sắc.","detail":"Đại hán nhận tin về cuộc tập hợp ma thú trong thạch phòng rồi giao Huyết Anh điều tra chuyện Chi tiên.","theLucLienQuan":[],"nguon":["@c1619"]},{"id":"day-nui-an-giau-cua-dong","name":"Dãy núi ẩn giấu cửa động","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Dãy núi liên miên có bề ngoài bình thường, nơi Tiêm Tiêm dẫn Hàn Lập đến tìm lối vào khu vực bí mật.","detail":"Cửa vào động phủ được che giấu trên một vách đá trong dãy núi. Việt Tông ở lại gần khu vực này trong khi Hàn Lập và Tiêm Tiêm đi theo Ma Yên Điểu.","theLucLienQuan":[],"nguon":["@c1620"]},{"id":"dong-phu-trong-vach-da","name":"Động phủ trong vách đá","cn":"","capDo":"khac","parentId":"day-nui-an-giau-cua-dong","blurb":"Động phủ có cửa vào bị vách đá và khói đen ngụy trang.","detail":"Bên trong động phủ tràn ngập ma khí hung mãnh và có một thánh giai ma thú đang ngủ. Hàn Lập dùng kim quang hộ thể một mình tiến vào để đánh phủ đầu.","theLucLienQuan":[],"nguon":["@c1620"]},{"id":"thong-dao-duoi-long-nui","name":"Thông đạo dưới lòng núi","cn":"","capDo":"khac","parentId":null,"blurb":"Hệ thống đường hầm rộng lớn dưới lòng núi, có vách đá đen liên tục phóng thích ma khí.","detail":"Các lối đi chằng chịt như mê cung và càng lúc càng dẫn sâu xuống lòng đất.","theLucLienQuan":[],"nguon":["@c1621"]},{"id":"loi-ra-bach-quang","name":"Lối ra bạch quang","cn":"","capDo":"khac","parentId":"thong-dao-duoi-long-nui","blurb":"Lối ra ở cuối đoạn thông đạo, nơi ma khí giảm mạnh và xuất hiện ánh sáng trắng.","detail":"Ma Yên Điểu dẫn Hàn Lập tới gần khu vực này trước khi bị chế trụ.","theLucLienQuan":[],"nguon":["@c1621"]},{"id":"ben-ngoai-son-mach","name":"Bên ngoài sơn mạch","cn":"","capDo":"khac","parentId":null,"blurb":"Vị trí nơi Tiêm Tiêm và hư ảnh Kỳ lân trao đổi sau khi Ma Yên Điểu bị chế trụ.","detail":"Từ khu vực này, họ thay đổi kế hoạch và chuẩn bị mở Chân linh chi huyệt.","theLucLienQuan":["Tinh Tộc"],"nguon":["@c1621"]},{"id":"dai-sanh-hinh-tron","name":"Đại sảnh hình tròn","cn":"","capDo":"khac","parentId":"ma-kim-son-mach","blurb":"Đại sảnh rộng hơn năm trượng nằm trong động phủ tại Ma Kim Sơn Mạch.","detail":"Giữa đại sảnh là pháp trận kim sắc, mười hai cột đá đen phun ma khí và một huyết sắc đại sàng nơi Cự viên màu đen nằm dưỡng thương. Hàn Lập thăm dò nơi này rồi phát động cuộc tập kích.","theLucLienQuan":[],"nguon":["@c1622"]},{"id":"dai-sanh-trong-phap-tran-tu-sac","name":"Đại sảnh trong pháp trận tử sắc","cn":"","capDo":"khac","parentId":"dai-sanh-hinh-tron","blurb":"Chiến trường nơi Hàn Lập giao chiến với Ma viên mặc tử sắc chiến giáp.","detail":"Các đợt công kích liên tiếp gây ra vụ nổ lớn, phá hủy phần lớn pháp trận và tạo một khe đen rộng hơn một trượng chia cắt đại sảnh. Chiếc giường màu máu nằm trên đường khe nứt nhưng vẫn nguyên vẹn.","theLucLienQuan":[],"nguon":["@c1623"]},{"id":"phap-tran-tu-sac","name":"Pháp trận tử sắc","cn":"","capDo":"khac","parentId":"dai-sanh-trong-phap-tran-tu-sac","blurb":"Pháp trận bao quanh chiếc giường màu máu và Ma viên trong đại sảnh.","detail":"Pháp trận bị Tam Nguyên Trảm cùng điện hồ, Phệ Kim Trùng, Phệ Linh hỏa và kim sắc cự phong đánh trúng. Sau vụ nổ, phần lớn kết cấu của trận vực đã bị phá hủy nghiêm trọng.","theLucLienQuan":[],"nguon":["@c1623"]},{"id":"chien-truong-giua-phe-linh-hoa-dieu-va-ma-cam","name":"Chiến trường giữa Phệ Linh hỏa điểu và ma cầm","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực trên không trung nơi Hàn Lập xuất hiện để hỗ trợ Phệ Linh hỏa điểu giao chiến với ma cầm.","detail":"Hàn Lập dùng không gian thần thông Thiên Phượng vượt qua khoảng cách hơn mười trượng, xuất hiện giữa Phệ Linh hỏa điểu và ma cầm Kim Ô biến dị tại khu vực chiến đấu trên không trung.","theLucLienQuan":[],"nguon":["@c1618"]},{"id":"thach-bich-den-cuoi-thong-dao","name":"Thạch bích đen cuối thông đạo","cn":"","capDo":"khac","parentId":null,"blurb":"Thạch bích nằm ở cuối thông đạo và không để lộ lối đi ở bề mặt. Bên trong nó ẩn giấu Huyệt linh cùng cửa vào Chân linh chi huyệt.","detail":"Kỳ lân dùng viên châu màu xanh thăm dò thạch bích để xác nhận vị trí Linh huyệt. Khi pháp trận được vận hành bằng Chân linh huyết, thạch bích nứt ra và để lộ khuôn mặt của Huyệt linh.","theLucLienQuan":[],"nguon":["@c1624"]},{"id":"thong-dao-ma-khi","name":"Thông đạo ma khí","cn":"","capDo":"khac","parentId":null,"blurb":"Lối đi phủ đầy ma khí mà Khuê Hoán và Cửu Dạ lần lượt xâm nhập. Ma khí dày đặc đến mức Cửu Dạ liên tưởng nơi này với động phủ bí mật của Thiết ma hoặc Huyết thủ.","detail":"Khuê Hoán dùng huyết độn đi qua thông đạo và khiến ma khí tự động tránh sang hai bên. Cửu Dạ theo sau, nhận thấy mức độ ma khí bất thường nhưng vẫn tiếp tục tiến vào.","theLucLienQuan":[],"nguon":["@c1624"]},{"id":"dai-sanh-noi-ma-vien-ngu-say","name":"Đại sảnh nơi Ma viên ngủ say","cn":"","capDo":"khac","parentId":null,"blurb":"Đại sảnh là chiến trường giữa Hàn Lập và Ma viên.","detail":"Chiếc giường màu máu và huyết ảnh mai phục tại khu vực cửa ra vào đại sảnh, nơi Hàn Lập giao chiến với Ma viên.","theLucLienQuan":["Ma giới"],"nguon":["@c1625"]},{"id":"thong-dao-dat-xuan-le-kiem-tran","name":"Thông đạo đặt Xuân Lệ kiếm trận","cn":"","capDo":"khac","parentId":null,"blurb":"Thông đạo có Xuân Lệ kiếm trận, nơi Hàn Lập định dẫn Ma viên tới.","detail":"Hàn Lập thi triển lôi độn để kéo Ma viên về phía thông đạo, dự định dùng Xuân Lệ kiếm trận vây khốn và đánh chết đối phương.","theLucLienQuan":[],"nguon":["@c1625"]},{"id":"ngon-nui-ma-khi","name":"Ngọn núi ma khí","cn":"","capDo":"khac","parentId":null,"blurb":"Ngọn núi chứa thông đạo ma khí và quái vật hắc quang khổng lồ.","detail":"Dị biến khiến cả ngọn núi đổ sập với tốc độ kinh người, chôn Hàn Lập dưới vô số cự thạch. Sau đó núi gần như bị san bằng khi Huyệt linh hiện ra.","theLucLienQuan":[],"nguon":["@c1632"]},{"id":"khong-gian-chua-chan-lan-ban-nguyen","name":"Không gian chứa Chân lân bản nguyên","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Khu vực có ma khí tinh thuần do Huyệt linh tạo ra để dụ Ma viên đến dưỡng thương.","detail":"Đây cũng là nơi Tiêm Tiêm và Khuê Hoán tìm cách lấy Chân lân bản nguyên, đồng thời diễn ra cuộc đối đầu giữa Hàn Lập và Huyệt linh.","theLucLienQuan":[],"nguon":["@c1634"]},{"id":"co-the-huyet-linh","name":"Cơ thể Huyệt linh","cn":"","capDo":"khac","parentId":"khong-gian-chua-chan-lan-ban-nguyen","blurb":"Nơi Tiêm Tiêm và Khuê Hoán từng tiến vào và bị gieo linh chủng.","detail":"Việc tiến vào cơ thể Huyệt linh tạo điều kiện để nó bí mật đặt linh chủng vào cơ thể hai người.","theLucLienQuan":[],"nguon":["@c1634"]},{"id":"khong-gian-toi-trong-than-the-mac-ky-lan","name":"Không gian tối trong thân thể Mặc kỳ lân","cn":"","capDo":"gioi-nho","parentId":"co-the-huyet-linh","blurb":"Không gian tối do Đại thôn diệt thuật đưa mục tiêu vào bên trong cơ thể Mặc kỳ lân.","detail":"Khu vực tối đen cả trên lẫn dưới, ngăn thần niệm ly thể và khiến Linh mục thần thông chỉ có thể quan sát mơ hồ trong phạm vi trăm trượng. Nguyên thần của Mặc kỳ lân có thể phân hóa thành nhiều hóa thân và liên tục tái sinh tại đây.","theLucLienQuan":[],"nguon":["@c1635"]},{"id":"quai-dien-da-trang","name":"Quái điện đá trắng","cn":"","capDo":"khac","parentId":null,"blurb":"Tòa quái điện sứt mẻ nơi Tiêm Tiêm và nam tử họ Khuê giằng co sau trận chiến với Huyệt linh.","detail":"Hàn Lập trở lại quái điện đá trắng khi kiến trúc đang nhanh chóng sụp xuống. Tiêm Tiêm dùng phi đao trắng hộ thân, còn nam tử họ Khuê có hư ảnh Ngân sắc giao long trên đầu và hai người đang đề phòng lẫn nhau.","theLucLienQuan":["Tinh Tộc"],"nguon":["@c1636"]},{"id":"chien-truong-quanh-hai-cot-quai-vat","name":"Chiến trường quanh hài cốt quái vật","cn":"","capDo":"khac","parentId":"chan-linh-chi-huyet","blurb":"Khu vực quanh nơi quái vật bị tiêu diệt trong Chân linh chi huyệt.","detail":"Hàn Lập dùng linh mục, thần niệm và độn quang rà soát kỹ phạm vi vài dặm tại đây nhưng không tìm thấy dấu vết Chân lân bản nguyên.","theLucLienQuan":[],"nguon":["@c1637"]},{"id":"ngoai-vi-ma-kim-son-mach","name":"Ngoại vi Ma Kim Sơn Mạch","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Khu vực nơi Tiêm Tiêm kiểm tra dấu vết của Việt Tông.","detail":"Tại nơi từng chia tay Việt Tông, Tiêm Tiêm phát hiện ông có lẽ đã ngã xuống trước khi nàng và Hàn Lập quay về theo đường cũ.","theLucLienQuan":[],"nguon":["@c1638","@c1651"]},{"id":"son-coc-kha-nghi-trong-ma-kim-son-mach","name":"Sơn cốc khả nghi trong Ma Kim Sơn Mạch","cn":"","capDo":"vuc","parentId":"ma-kim-son-mach","blurb":"Sơn cốc khiến pháp bàn phát ra phản ứng.","detail":"Sơn cốc có bề ngoài bình thường nhưng trở thành nơi tranh chấp giữa nhóm lão giả họ Ngạn và nhóm dị tộc nhân tóc xanh.","theLucLienQuan":[],"nguon":["@c1638"]},{"id":"son-coc-ma-ngac","name":"Sơn cốc Ma ngạc","cn":"","capDo":"khac","parentId":"ma-kim-son-mach","blurb":"Sơn cốc phủ hắc sắc ma khí, phía dưới sâu như một vực dài không thấy đáy. Nơi đây có dòng sông và là hang ổ của Hắc Uyên ngạc gần đạt thánh giai.","detail":"Bề ngoài sơn cốc không biểu hiện hết chiều sâu thực tế. Pháp bảo thăm dò xuống hơn nghìn trượng vẫn chưa nhìn thấy đáy; ma khí bao phủ phía trên và một dòng sông nằm sâu bên trong, nơi Hắc Uyên ngạc ẩn dưới lớp bùn đáy sông. Phản ứng của pháp bàn khiến nhiều nhóm nghi Chi tiên đang ẩn tại khu vực này.","theLucLienQuan":["Ma thú"],"nguon":["@c1639"]},{"id":"vung-suong-mu-nhan-dien-thuu","name":"Vùng sương mù Nhân diện thứu","cn":"","capDo":"khac","parentId":"ma-kim-son-mach","blurb":"Vùng sương mù từng do đám Nhân diện thứu cao giai chiếm giữ. Sau khi chúng bị tiêu diệt, chưa có ma thú cao giai khác chuyển đến tiếp quản khu vực.","detail":"Hàn Lập và Tiêm Tiêm phải giảm tốc độ, duy trì cảnh giác khi xuyên qua vùng sương trên đường trở về. Họ đi qua thuận lợi nhưng ngay tại rìa ngoài lại gặp hàng trăm ma thú đang chặn đường.","theLucLienQuan":["Ma thú"],"nguon":["@c1639"]},{"id":"khu-vuc-ngoai-vi-son-mach","name":"Khu vực ngoại vi sơn mạch","cn":"","capDo":"vuc","parentId":"son-mach","blurb":"Vùng ngoại vi nằm gần lối vào sơn mạch và tiếp giáp khu vực của ngoại tộc.","detail":"Ngũ Khấp từng cân nhắc rút về đây, gọi thêm viện binh rồi bố trí mai phục Hàn Lập tại vùng giáp ranh với ngoại tộc.","theLucLienQuan":["Ma thú"],"nguon":["@c1643"]},{"id":"khu-vuc-giao-chien-giua-hac-thuy-va-hoa-van","name":"Khu vực giao chiến giữa hắc thủy và hỏa vân","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực nơi hắc thủy và hỏa vân vốn va chạm dữ dội trước khi đồng thời chuyển hướng về chiến trường của Hàn Lập.","detail":"Hắc thủy và hỏa vân đang va chạm ở xa thì tách thành hai nửa, sau đó cuồn cuộn kéo về phía Hàn Lập, lão giả họ Ngạn và nữ tử cung trang.","theLucLienQuan":[],"nguon":["@c1646"]},{"id":"ngon-nui-cao","name":"Ngọn núi cao","cn":"","capDo":"khac","parentId":null,"blurb":"Hàn Lập dẫn truy binh đến ngọn núi cao cách chiến trường hơn mười ngàn dặm.","detail":"Tại đây Hàn Lập dừng độn quang và bố trí Xuân Lệ kiếm trận để chuẩn bị phản kích.","theLucLienQuan":[],"nguon":["@c1647"]},{"id":"chien-truong-ban-dau","name":"Chiến trường ban đầu","cn":"","capDo":"khac","parentId":null,"blurb":"Đây là nơi Hàn Lập đánh chết dị tộc nhân tóc xanh và thu hồi chiến lợi phẩm.","detail":"Sau khi thu hồi các bảo vật, Hàn Lập rời khỏi chiến trường, còn lão giả họ Ngạn và cung trang nữ tử không dám tiếp tục truy đuổi trực tiếp.","theLucLienQuan":[],"nguon":["@c1647"]},{"id":"hu-khong","name":"Hư không","cn":"","capDo":"khac","parentId":null,"blurb":"Hư không là nơi các phi kiếm quay về cơ thể Hàn Lập và thanh quang của Xuân Lệ kiếm trận được ẩn giấu.","detail":"Hàn Lập bố trí vô số thanh quang trong hư không để chuẩn bị đối phó Cự thử.","theLucLienQuan":[],"nguon":["@c1647"]},{"id":"chien-truong-tren-khong-trung","name":"Chiến trường trên không trung","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực giao chiến giữa Hàn Lập và cự thú hỏa thuộc tính trên không trung.","detail":"Cự thú hỏa thuộc tính hóa thành mặt trời đỏ giữa không trung, còn Xuân Lê kiếm trận bao phủ vùng chiến đấu rộng hơn trăm trượng. Thiên địa nguyên khí trong khu vực bị Hàn Lập triệu tập để ngưng kết Nguyên khí chi kiếm.","theLucLienQuan":[],"nguon":["@c1648"]},{"id":"cung-dien-sau-trong-ma-kim-son-mach","name":"Cung điện sâu trong Ma Kim Sơn Mạch","cn":"","capDo":"khac","parentId":"ma-kim-son-mach","blurb":"Cung điện hùng vĩ nằm sâu trong Ma Kim Sơn Mạch.","detail":"Nơi đây có hắc ô đại môn và là địa điểm Thiết huynh, Huyết Tí cùng Đa Nhãn tập trung chờ Thánh tổ thức tỉnh.","theLucLienQuan":["Nhóm ba ma đầu trấn giữ Ma Kim Sơn Mạch"],"nguon":["@c1649"]},{"id":"thong-dao-gioi-dien","name":"Thông đạo giới diện","cn":"","capDo":"khac","parentId":null,"blurb":"Thông đạo nối giữa các giới diện, từng bị lực lượng tại Ma Kim Sơn Mạch ngăn chặn.","detail":"Thông đạo xuất hiện dị biến nhẹ sau thời gian bị phong tỏa. Tam ma cho rằng phía Thánh giới có thể mất nhiều năm và phải dùng lực lượng của Thánh tổ cùng Huyền Thiên chi bảo để đả thông nó.","theLucLienQuan":["Thánh giới","Nhóm ba ma đầu trấn giữ Ma Kim Sơn Mạch"],"nguon":["@c1650"]},{"id":"khong-gian-phan-hong-sau-cua-da","name":"Không gian phấn hồng sau cửa đá","cn":"","capDo":"gioi-nho","parentId":"ma-kim-son-mach","blurb":"Thiên địa riêng nằm sau cánh cửa đá phủ kinh văn màu phấn hồng.","detail":"Không gian có trời xanh, đồng cỏ kéo dài và một cây hoa thụ cao hơn trăm trượng. Đây là nơi nữ Thánh tổ ngủ say, tĩnh tu và tiếp kiến ba ma thú thánh giai.","theLucLienQuan":["Thánh giới","Nhóm ba ma đầu trấn giữ Ma Kim Sơn Mạch"],"nguon":["@c1650"]},{"id":"hoa-thu","name":"Hoa thụ","cn":"","capDo":"khac","parentId":"khong-gian-phan-hong-sau-cua-da","blurb":"Cây hoa khổng lồ cao hơn trăm trượng trong không gian sau cửa đá.","detail":"Hoa thụ nở những đóa hoa màu hồng nhạt giống hoa sen. Nữ Thánh tổ đứng dưới tàng cây và hái một đóa hoa để đưa Đa Nhãn ma, Thiết Sí ma cùng Huyết Tí tới gần.","theLucLienQuan":["Thánh giới"],"nguon":["@c1650"]},{"id":"thong-dao-thanh-gioi","name":"Thông đạo đi Thánh giới","cn":"","capDo":"gioi-dien","parentId":"thanh-gioi","blurb":"Thông đạo nối Ma Kim Sơn Mạch với Thánh giới đang xuất hiện dao động.","detail":"Bạch y nữ tử giao tam ma bố trí đại trận để gia cố thông đạo, khiến việc phá mở từ Thánh giới trở nên khó khăn hơn.","theLucLienQuan":["Thánh giới"],"nguon":["@c1651"]},{"id":"loi-ra-ma-kim-son-mach","name":"Lối ra Ma Kim Sơn Mạch","cn":"","capDo":"khac","parentId":"ma-kim-son-mach","blurb":"Lối ra là vùng hư không phải đi qua để được trận pháp bên ngoài tiếp dẫn.","detail":"Khu vực này dài vài dặm và có hàng trăm ma thú mai phục ở hai bên. Hàn Lập dùng Minh Thanh Linh Mục phát hiện vòng phục kích tại đây.","theLucLienQuan":[],"nguon":["@c1651"]},{"id":"dai-dien-cua-thanh-to","name":"Đại điện của Thánh tổ","cn":"","capDo":"khac","parentId":"ma-kim-son-mach","blurb":"Đại điện nơi bạch y nữ tử triệu kiến tam ma.","detail":"Bạch y nữ tử truyền nhiệm vụ cho tam ma tại đây rồi dùng Di Tinh Hoán Nguyệt đưa cả ba ra ngoài.","theLucLienQuan":[],"nguon":["@c1651"]},{"id":"tieu-van-tran","name":"Tiêu Vân trấn","cn":"","capDo":"thanh","parentId":null,"blurb":"Địa điểm Hàn Lập và Tiêm Tiêm quyết định không quay lại sau khi rời Ma Kim Sơn Mạch.","detail":"Sau khi thoát khỏi khu vực nguy hiểm, Hàn Lập và Tiêm Tiêm bỏ ý định quay lại Tiêu Vân trấn, lựa chọn bay thẳng ra ngoài để tránh trì hoãn và truy binh.","theLucLienQuan":[],"nguon":["@c1652"]},{"id":"thuong-co-di-tich-cua-luyen-dan-tong-su","name":"Thượng cổ di tích của luyện đan tông sư","cn":"","capDo":"khac","parentId":null,"blurb":"Di tích chưa rõ vị trí, từng là nơi ở của một luyện đan tông sư nổi danh thời viễn cổ.","detail":"Kỳ ảnh biết một thượng cổ di tích có khả năng cải thiện thể chất Tinh Tộc của Tiêm Tiêm và hỗ trợ nàng tiến vào Thánh tộc. Nơi này được hé lộ như phương án thay thế sau khi chuyến tìm Chân lân bổn nguyên thất bại.","theLucLienQuan":["Tinh Tộc","Thánh tộc"],"nguon":["@c1652"]},{"id":"dam-lay-trong-ma-kim-son-mach","name":"Đầm lầy trong Ma Kim Sơn Mạch","cn":"","capDo":"khac","parentId":"ma-kim-son-mach","blurb":"Một đầm lầy trong Ma Kim Sơn Mạch, nơi Hắc Uyên ngạc củng cố cảnh giới sau khi tiến giai.","detail":"Hoa đại nhân xuất hiện tại đây, đánh giá Tà Long chân huyết của Hắc Uyên ngạc rồi dùng thần thông đưa cả hai rời đi.","theLucLienQuan":[],"nguon":["@c1653"]},{"id":"van-mong-son","name":"Vân Mộng sơn","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Khu vực thuộc Vân thành, nơi đặt động phủ của Hàn Lập.","detail":"Sau khi rời Ma Kim Sơn Mạch, Hàn Lập trở về động phủ tại Vân Mộng sơn, nghỉ ngơi rồi vào mật thất xử lý chiến lợi phẩm.","theLucLienQuan":[],"nguon":["@c1653"]},{"id":"vuon-thuoc-dong-phu-han-lap","name":"Vườn thuốc trong động phủ Hàn Lập","cn":"","capDo":"khac","parentId":null,"blurb":"Vườn thuốc bên trong động phủ của Hàn Lập, nơi Chi tiên cắm rễ và thỏ trắng tự do hoạt động.","detail":"Nơi Chi tiên biến về dạng cây cắm rễ vào đất, thỏ trắng sinh sống. Hàn Lập bàn chuyện mở linh trí cho thỏ trắng tại đây trước khi rời động phủ.","theLucLienQuan":[],"nguon":["@c1660"]},{"id":"cua-hang-tiem-tiem","name":"Cửa hàng của Tiêm Tiêm","cn":"","capDo":"khac","parentId":null,"blurb":"Cửa hàng của cô gái Tinh tộc Tiêm Tiêm, bên trong có truyền tống trận dẫn vào khe không gian riêng.","detail":"Cửa hàng thường đóng chặt không tiếp khách, Hàn Lập dùng tín hiệu lửa để báo đến. Bên trong có truyền tống trận dẫn vào khe không gian riêng nơi Tiêm Tiêm bố trí pháp trận tu bổ ma giáp.","theLucLienQuan":["Tinh tộc"],"nguon":["@c1660"]},{"id":"khe-khong-gian-tiem-tiem","name":"Khe không gian của Tiêm Tiêm","cn":"","capDo":"khac","parentId":"cua-hang-tiem-tiem","blurb":"Không gian riêng của Tiêm Tiêm, nơi bố trí pháp trận tu bổ Thiên ngoại ma giáp.","detail":"Không gian riêng được truy cập qua truyền tống trận trong cửa hàng. Sau khi kích hoạt cấm chế, mây đen kéo xuống, bốn vách hạ, tối đen như Trụy Ma cốc. Bên trong bố trí pháp trận lớn hơn mười trượng với mười khỏa tinh thạch đen và đỉnh đồng xanh chứa ma hạch.","theLucLienQuan":["Tinh tộc"],"nguon":["@c1660"]},{"id":"thuong-co-di-chi","name":"Thượng cổ di chỉ","cn":"上古遺址","capDo":"khac","parentId":null,"blurb":"Di chỉ thượng cổ mà Kỳ Lân muốn đưa Tiêm Tiêm vào, cần một vật đặc biệt chỉ vài lão quái Thánh giai biết rõ.","detail":"Kỳ Lân hư ảnh nhắc đến thượng cổ di chỉ và hỏi Tiêm Tiêm đã tìm được vật cần thiết để vào chưa. Tiêm Tiêm nói chưa tìm được, vật đó chỉ vài lão quái Thánh giai mới biết rõ, dự định tìm mua hoặc mượn từ con cháu các lão quái. Kỳ Lân nhấn mạnh không có vật đó thì căn bản không vào được.","theLucLienQuan":[],"nguon":["@c1661"]},{"id":"linh-son","name":"Linh sơn","cn":"灵山","capDo":"khac","parentId":"thien-van","blurb":"Ngọn núi trong Vân Thành nơi Hàn Lập có động phủ, cũng có nhiều ngoại tộc tu luyện giả khác cư ngụ.","detail":"Linh sơn nằm trong Vân Thành, sườn núi có nhiều động phủ của ngoại tộc tu luyện giả, bình thường hiếm thấy bóng người. Hứa lão quái cũng ở trên núi này. Động phủ Hàn Lập được Thiên Cơ Tử trưởng lão Vạn Cổ Tộc an bài tại đây.","theLucLienQuan":["Vạn Cổ Tộc"],"nguon":["@c1662"]},{"id":"cung-phung-duong","name":"Cung phụng đường","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Nơi bị kẻ Giác Xi tộc xông vào, là nguyên nhân Vân Thành siết chặt an ninh.","detail":"Kẻ Giác Xi tộc xâm nhập cung phụng đường, khiến liên minh thánh tộc phải tổ chức cuộc họp truy tìm quy mô lớn.","theLucLienQuan":["Giác Xi tộc"],"nguon":["@c1664"]},{"id":"thong-linh-dai-dien","name":"Thông Linh đại điện","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Đại điện trong Vân thành, nơi Vạn Cổ Tộc bố trí Nghiễm Hàn nghi để cảm ứng Nghiễm Hàn Giới.","detail":"Thông Linh đại điện nằm trong Vân thành, là nơi Vạn Cổ Tộc bố trí Nghiễm Hàn nghi — bảo vật dùng cảm ứng khi Nghiễm Hàn Giới sắp mở. Nghiễm Hàn nghi trong điện đã có phản ứng hai ngày trước cuộc họp.","theLucLienQuan":["Vạn Cổ Tộc"],"nguon":["@c1665"]},{"id":"khu-vuc-phap-tran-nghiem-han-gioi","name":"Khu vực pháp trận Nghiễm Hàn Giới","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Khu vực phương viên mười dặm gần khách sạn nơi Hàn Lập từng kích phát Nghiễm Hàn Lệnh, bị ngũ sắc quang mạc bao phủ, chứa hai pháp trận truyền tống và một điện phủ trung tâm.","detail":"Nằm gần khách sạn nơi Hàn Lập từng kích phát Nghiễm Hàn Lệnh trong Vân thành. Phương viên mười dặm bị ngũ sắc quang mạc bao phủ do hơn mười cây cột cao trăm trượng tạo ra. Canh giữ bởi hơn tám trăm khôi lỗi thân cao bảy tám trượng đeo xích đỏ cùng hàng ngàn giáp sĩ (tối thiểu Kết Đan Kỳ, đa số Nguyên Anh Kỳ, vài Luyện Hư Kỳ). Bên trong có hai pháp trận hình tròn khảm tinh thạch dùng truyền tống vào Nghiễm Hàn Giới và một điện phủ làm trung tâm chỉ huy nơi các Hợp Thể Kỳ hội họp.","theLucLienQuan":["Vân tộc"],"nguon":["@c1669"]},{"id":"tieu-dao-hai-thu","name":"Tiểu đảo hải thú","capDo":"khac","parentId":"nghiem-han-gioi","blurb":"Hòn đảo nhỏ duy nhất ba người tìm thấy sau một đêm phi hành trăm vạn dặm trong Nghiễm Hàn Giới, bị hải thú xúc tu khổng lồ chiếm cứ.","detail":"Tiểu đảo nằm giữa hải vực mênh mông của Nghiễm Hàn Giới. Ba người Hàn Lập, Thạch Côn, Liễu Thuý Nhi phi hành cả đêm với sáu bảy thành tốc độ, vượt hơn trăm vạn dặm mới gặp hòn đảo duy nhất này. Bầu trời mây hồng lúc bình minh, ngoài khơi có yêu khí và thứ gì đó khắc chế thần niệm. Bị Thạch Côn san bằng toàn bộ núi đá cây cối chỉ với một quyền, sau đó hải thú xúc tu khổng lồ màu đen từ dưới nước lộ diện.","theLucLienQuan":[],"nguon":["@c1672"]},{"id":"vung-bien-nghiem-han-gioi","name":"Vùng biển Nghiễm Hàn Giới","cn":"","capDo":"vuc","parentId":"nghiem-han-gioi","blurb":"Vùng biển rộng lớn thuộc Nghiễm Hàn Giới, phi hành mất năm ngày mới tới bờ lục địa. Dọc đường có nhiều tiểu đảo bị hải thú cường đại chiếm cứ, vùng gần bờ là lãnh địa của Trấn Hải Viên và tử sắc đại điểu — thượng cổ mãnh thú cực kỳ hung mãnh.","detail":"Ba người Hàn Lập phi hành suốt năm ngày trên biển này. Dọc đường gặp ba bốn tiểu đảo đều bị hải thú cường đại (mạnh hơn bạch tuộc khổng lồ trước đó) chiếm cứ. Vùng biển gần bờ lục địa có Trấn Hải Viên — thượng cổ mãnh thú sở hữu Thiên Hống thần thông, và tử sắc đại điểu ngang sức đối đầu. Liễu Thuý Nhi nhận xét nguy hiểm trên đất liền còn ghê gớm hơn trên biển.","theLucLienQuan":[],"nguon":["@c1675"]},{"id":"van-cam-linh","name":"Vạn Cầm Lĩnh","cn":"","capDo":"vuc","parentId":"nghiem-han-gioi","blurb":"Vạn Cầm Lĩnh là hung địa nổi danh trong Nghiễm Hàn Giới. Nhóm Hàn Lập được xác định đang ở rìa khu vực này.","detail":"Vạn Cầm Lĩnh có mấy vạn linh cầm và ba thượng cổ mãnh thú trú ngụ, uy danh không kém Trấn Hải Viên. Vì quá nguy hiểm, nhóm Hàn Lập không chọn trực tiếp băng qua khu vực này.","theLucLienQuan":[],"nguon":["@c1676"]},{"id":"bat-hung-hai","name":"Bát Hung Hải","cn":"","capDo":"vuc","parentId":"nghiem-han-gioi","blurb":"Bát Hung Hải là hải vực hung địa nổi danh trong Nghiễm Hàn Giới. Nhóm Hàn Lập vừa đi qua khu vực này trước khi lên đại lục.","detail":"Bát Hung Hải có tám thượng cổ mãnh thú, là nơi Trấn Hải Viên và cự điểu giao chiến dữ dội. Sau khi dùng Nghiễm Hàn Đồ, Liễu Thuý Nhi xác định hải vực vừa vượt qua chính là Bát Hung Hải.","theLucLienQuan":[],"nguon":["@c1676"]},{"id":"am-thu-sam-lam","name":"Ám Thú sâm lâm","cn":"","capDo":"vuc","parentId":"nghiem-han-gioi","blurb":"Ám Thú sâm lâm là rừng rậm nằm cạnh Vạn Cầm Lĩnh trong Nghiễm Hàn Giới. Nhóm Hàn Lập quyết định xuyên qua nơi này để tiết kiệm thời gian.","detail":"Ám Thú sâm lâm có bộ tộc Ám Thú, loài dị thú đã tuyệt diệt tại Linh giới nhưng còn tồn tại trong Nghiễm Hàn Giới. Ám Thú ban đêm thực lực bạo tăng mấy lần; dù vậy, Liễu Thuý Nhi cho rằng tuyến này vẫn khả thi hơn vòng qua Vạn Cầm Lĩnh hoặc đi Lam Dương sa mạc.","theLucLienQuan":["Ám Thú"],"nguon":["@c1676","@c1686"]},{"id":"lam-duong-sa-mac","name":"Lam Dương sa mạc","cn":"","capDo":"vuc","parentId":"nghiem-han-gioi","blurb":"Lam Dương sa mạc là khu vực nằm bên cạnh Vạn Cầm Lĩnh. Nơi này bị xem là còn hung hiểm hơn Vạn Cầm Lĩnh vì ánh nắng quỷ dị.","detail":"Lam Dương sa mạc có ánh nắng đặc biệt nguy hiểm; người chưa tiến giai thánh tộc nếu phơi nắng nửa ngày sẽ hóa thành tro bụi. Vì mức độ hung hiểm này, nhóm Hàn Lập loại bỏ tuyến đường qua sa mạc.","theLucLienQuan":[],"nguon":["@c1676"]},{"id":"cam-che-chi-dia","name":"Cấm chế chi địa","cn":"","capDo":"khac","parentId":null,"blurb":"Mục tiêu tiếp theo trong hành trình của Hàn Lập, Liễu Thuý Nhi và Thạch Côn.","detail":"Thạch Côn đề nghị cả nhóm sớm tìm đến cấm chế chi địa để có thể nghỉ ngơi, nhưng vị trí và bản chất cụ thể của nơi này chưa được hé lộ.","theLucLienQuan":[],"nguon":["@c1689"]},{"id":"cam-che-chia-dia","name":"Cấm chế chia địa","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm được Hàn Lập, Liễu Thuý Nhi và Thạch Côn chọn làm nơi hội hợp sau khi chia hướng thoát thân.","detail":"Cấm chế chia địa nằm cách vị trí ba người phân tán khoảng một nửa lộ trình còn lại. Cả ba đều biết đường đến đây và thống nhất sẽ gặp lại sau hai tháng.","theLucLienQuan":[],"nguon":["@c1690"]},{"id":"sa-mac-bao-cat-vang","name":"Sa mạc bão cát vàng","cn":"","capDo":"khac","parentId":"nghiem-han-gioi","blurb":"Sa mạc mênh mông trong Nghiễm Hàn Giới, thường xuyên bị bão cát vàng bao phủ. Một phế tích đền đài cực lớn bị che giấu bên trong khu vực này.","detail":"Hai tháng sau khi rời chiến trường ngân trùng, hành trình chuyển tới vùng sa mạc đầy bão cát của Nghiễm Hàn Giới. Đoàn dị tộc dùng Thanh đồng cổ kính phá mở bão cát và phát hiện phế tích nằm bên trong.","theLucLienQuan":["Dị tộc thấp bé"],"nguon":["@c1691"]},{"id":"phe-tich-den-dai","name":"Phế tích đền đài","cn":"","capDo":"khac","parentId":"sa-mac-bao-cat-vang","blurb":"Phế tích đền đài quy mô cực lớn bị bão cát che giấu giữa sa mạc Nghiễm Hàn Giới. Phạm vi của nó rộng đến mức không thể nhìn thấy điểm cuối.","detail":"Đoàn dị tộc phát hiện địa điểm này bằng Thanh đồng cổ kính. Khi họ chuẩn bị hạ xuống, Lôi bằng khôi lỗi bất ngờ xuất hiện và giao chiến với cả đoàn.","theLucLienQuan":["Dị tộc thấp bé"],"nguon":["@c1691"]},{"id":"di-chi-thuong-co-trong-bao-cat","name":"Di chỉ thượng cổ trong bão cát","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Một vùng phế tích thượng cổ rộng khoảng hai ba trăm vạn dặm, thường xuyên bị bão cát bao phủ.","detail":"Trong di chỉ còn nhiều cấm chế và cơ quan thượng cổ nguy hiểm. Hàn Lập cùng Liễu Thuý Nhi phải bay vòng tránh các khu vực có nguy cơ, trong đó có nơi từng xuất hiện cơ quan mang hình thái giống Lôi bằng.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1693"]},{"id":"khu-vuc-cam-che-nhieu-tang","name":"Khu vực cấm chế nhiều tầng","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực phía dưới nhóm Hàn Lập có ít nhất mười tầng cấm chế khác nhau.","detail":"Chín tầng đầu gồm nhiều loại quang hà, quầng sáng và mạng tinh ti đã bị phù văn Nguyên từ phá tan. Tầng thứ mười là màn cát vàng sẫm có Thái Ất thanh quang bảo vệ.","theLucLienQuan":[],"nguon":["@c1695"]},{"id":"cua-vao-sau-trong-cam-che-thu-muoi-mot","name":"Cửa vào sau trọng cấm chế thứ mười một","cn":"","capDo":"khac","parentId":"khu-vuc-cam-che-nhieu-tang","blurb":"Lối vào khu vực phía trong xuất hiện sau khi trọng cấm chế cuối bị phá.","detail":"Cửa vào là một lỗ thủng đường kính hơn mười trượng, huyền phù giữa không trung và có hai mép tỏa hào quang trắng ngà. Phía sau được cho là khu vực còn chứa nhiều trọng bảo.","theLucLienQuan":[],"nguon":["@c1696"]},{"id":"khong-gian-cam-che-bien-cat-vang","name":"Không gian cấm chế biển cát vàng","cn":"","capDo":"khac","parentId":"khu-vuc-cam-che-nhieu-tang","blurb":"Không gian chứa hàng trăm vạn hạt cát cấu thành đệ thập trọng cấm chế.","detail":"Phần lớn biển cát bị Nguyên Từ Cực Sơn hút vào, số cát còn lại bị kiếm quang màu xám chấn vỡ, khiến đệ thập trọng cấm chế bị cưỡng ép phá bỏ.","theLucLienQuan":[],"nguon":["@c1696"]},{"id":"khong-gian-sau-ngu-sac-quang-tran","name":"Không gian sau ngũ sắc quang trận","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian riêng được nối với lỗ thủng cấm chế bằng ngũ sắc quang trận, bên trong có đài đá, kỳ hoa dị thảo, ngọn núi và cung điện.","detail":"Nơi này có mặt trời, bầu trời xanh không mây và cảnh vật khác biệt với khu vực bên ngoài. Nhiều cấm chế hạn chế phi hành, pháp khí và việc tiến lên ngọn núi bảo vệ mục tiêu nằm sâu bên trong.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1697"]},{"id":"dai-da-truyen-tong","name":"Đài đá truyền tống","cn":"","capDo":"khac","parentId":"khong-gian-sau-ngu-sac-quang-tran","blurb":"Đài cao bằng đá tảng lớn là điểm đến của ngũ sắc quang trận trong không gian động phủ.","detail":"Đài đá mang hoa văn thô sơ nguyên thủy, trên mặt có truyền tống trận đường kính khoảng hai trượng. Một cầu thang nối đài với bãi đá phía dưới.","theLucLienQuan":[],"nguon":["@c1697"]},{"id":"ngon-nui-cung-dien","name":"Ngọn núi cung điện","cn":"","capDo":"khac","parentId":"khong-gian-sau-ngu-sac-quang-tran","blurb":"Tiểu sơn cao vài trăm trượng và rộng hơn mười dặm, có đỉnh bằng phẳng cùng quần thể cung điện màu tím.","detail":"Đỉnh núi phẳng như bị cắt và gần như bị cung điện chiếm trọn. Cấm chế cấm không bao phủ khu vực, còn con đường lên đỉnh gồm hàng vạn bậc đá chịu hấp lực tăng dần.","theLucLienQuan":[],"nguon":["@c1697"]},{"id":"son-dao-thach-giai-trang","name":"Sơn đạo thạch giai trắng","cn":"","capDo":"khac","parentId":"ngon-nui-cung-dien","blurb":"Con đường gồm hàng vạn bậc đá trắng chạy thẳng từ chân núi lên cung điện trên đỉnh.","detail":"Nhìn từ xa, sơn đạo giống một con mãng xà trắng bám trên núi. Mỗi bậc tiếp theo tạo hấp lực mạnh hơn bậc trước, khiến người đi phải dựa nhiều vào sức mạnh thân thể.","theLucLienQuan":[],"nguon":["@c1697"]},{"id":"cung-dien-mau-tim","name":"Cung điện màu tím","cn":"","capDo":"khac","parentId":"ngon-nui-cung-dien","blurb":"Quần thể kiến trúc màu tím phát ngân quang trên đỉnh núi, được nhóm Hàn Lập xem là mục tiêu có khả năng cất giấu bảo vật.","detail":"Cung điện có quy mô mênh mông và chiếm gần trọn phần đỉnh bằng phẳng của ngọn núi. Nội tình cùng những nguy hiểm bên trong chưa được xác định khi ba người bắt đầu vượt thạch giai.","theLucLienQuan":[],"nguon":["@c1697"]},{"id":"quang-truong-xanh-trong-tu-dien","name":"Quảng trường xanh trong tử điện","cn":"","capDo":"khac","parentId":"cung-dien-mau-tim","blurb":"Quảng trường rộng khoảng năm sáu trăm trượng nằm sau cửa tử điện.","detail":"Bốn phía quảng trường có lan can bạch ngọc và phía trước dẫn về chủ điện màu tím. Toàn bộ khu vực bị một ảo trận bao phủ, khiến người tiến vào quanh quẩn gần góc quảng trường và không nhận ra quang môn ẩn ở trung tâm.","theLucLienQuan":[],"nguon":["@c1699"]},{"id":"chu-dien-mau-tim","name":"Chủ điện màu tím","cn":"","capDo":"khac","parentId":"cung-dien-mau-tim","blurb":"Đại điện chính nằm ở cuối quảng trường xanh trong tử điện.","detail":"Ba điện nhỏ, mỗi điện có diện tích khoảng một phần ba chủ điện, vây quanh công trình theo hình chữ “phẩm”. Phía sau chủ điện còn thấp thoáng nhiều ban công và lầu các.","theLucLienQuan":[],"nguon":["@c1699"]},{"id":"quang-mon-giua-quang-truong","name":"Quang môn giữa quảng trường","cn":"","capDo":"khac","parentId":"quang-truong-xanh-trong-tu-dien","blurb":"Cửa sáng lớn bị ảo trận che giấu tại trung tâm quảng trường trong tử điện.","detail":"Quang môn chỉ hiện ra sau khi ti võng đen xanh từ thần thông dung hợp linh mục làm các luồng hào quang nổ tung và khiến hư không bên dưới vặn vẹo.","theLucLienQuan":[],"nguon":["@c1699"]},{"id":"tu-kim-dai-dien","name":"Tử kim đại điện","cn":"","capDo":"khac","parentId":"ngon-nui-cung-dien","blurb":"Quần thể cung điện Hàn Lập tiến vào sau khi vượt qua quang môn.","detail":"Khu kiến trúc gồm chủ điện và các thiên điện. Bảng hiệu trên cửa mang loại cổ văn mà Hàn Lập nhận định có khả năng là Kim Triện Văn, nhưng hắn không thể đọc nội dung.","theLucLienQuan":[],"nguon":["@c1700"]},{"id":"thien-dien-tu-kim-dai-dien","name":"Thiên điện Tử kim đại điện","cn":"","capDo":"khac","parentId":"tu-kim-dai-dien","blurb":"Tòa thiên điện không có cấm chế trên cửa, được Hàn Lập chọn thăm dò sau khi từ bỏ chủ điện.","detail":"Tòa điện rộng khoảng một phần ba chủ điện. Bên trong được bố trí như nơi thờ phụng, có bàn thờ bạch ngọc, thần tượng màu tím, hàng trăm bồ đoàn vàng, bốn lư hương xanh và hương đàn lan tỏa.","theLucLienQuan":[],"nguon":["@c1700"]},{"id":"dai-sanh-chua-mieu","name":"Đại sảnh chùa miếu","cn":"","capDo":"khac","parentId":"tu-kim-dai-dien","blurb":"Một đại sảnh có bố trí giống chùa miếu hơn điện phủ, chứa nhiều vật phẩm quý hiếm và một thần tượng lục ngọc.","detail":"Trong đại sảnh có hai giá Tuyết mộc đặt hơn mười bảo vật bán thành phẩm, hơn trăm bồ đoàn Giáp Y thảo, các lư hương chứa Hắc u băng hương và một thần tượng mặc đạo bào xanh. Hai cửa nhỏ từ đây dẫn sang khu vực khác.","theLucLienQuan":[],"nguon":["@c1701"]},{"id":"day-suong-phong","name":"Dãy sương phòng","cn":"","capDo":"khac","parentId":"tu-kim-dai-dien","blurb":"Khu vực phía sau thiên môn, gồm hơn mười căn phòng nhỏ có hình thức giống nhau.","detail":"Hàn Lập sai cự viên khôi lỗi mở toàn bộ cửa phòng để kiểm tra. Sau khi không phát hiện dị thường bên ngoài, hắn bước vào một căn phòng để tiếp tục khám xét.","theLucLienQuan":[],"nguon":["@c1701"]},{"id":"khu-phong-o-trong-thien-dien","name":"Khu phòng ở trong thiên điện","cn":"","capDo":"khac","parentId":"thien-dien-tu-kim-dai-dien","blurb":"Khu phòng khách và phòng ngủ dành cho môn nhân đệ tử trong thiên điện.","detail":"Hàn Lập tìm kiếm tại đây nhưng không phát hiện bảo vật đáng giá, chỉ thu được một số ngọc giản ghi bằng loại cổ văn chưa biết.","theLucLienQuan":[],"nguon":["@c1702"]},{"id":"day-mat-that-tu-luyen","name":"Dãy mật thất tu luyện","cn":"","capDo":"khac","parentId":"thien-dien-tu-kim-dai-dien","blurb":"Dãy phòng vuông độc lập được bảo vệ bằng cấm chế mang Ngân Khoa văn.","detail":"Các mật thất cách nhau hơn mười trượng. Sáu phòng đầu trống rỗng hoặc chỉ có bồ đoàn Giáp Y thảo, còn mật thất thứ bảy lưu giữ Kim Kiếm Đồ, ba hộp ngọc và hai bình nhỏ.","theLucLienQuan":[],"nguon":["@c1702"]},{"id":"quang-truong-ao-tran","name":"Quảng trường ảo trận","cn":"","capDo":"khac","parentId":"tu-kim-dai-dien","blurb":"Khu quảng trường được bao phủ bởi một ảo trận khó vượt qua trong thời gian ngắn.","detail":"Hàn Lập nhận định hai người còn ở ngoài quảng trường khó nhanh chóng xuyên qua ảo trận nếu không có thủ đoạn đặc thù.","theLucLienQuan":[],"nguon":["@c1703"]},{"id":"khu-lau-cac-dinh-thai-phia-sau-chu-dien","name":"Khu lầu các đỉnh thai phía sau chủ điện","cn":"","capDo":"khac","parentId":"chu-dien-mau-tim","blurb":"Khu lầu các có cây xanh, mộc linh khí nồng đậm và dược hương lan tỏa.","detail":"Dấu hiệu mộc linh khí cùng dược hương tại đây giúp Hàn Lập xác định vị trí dược viên tiên nhân.","theLucLienQuan":[],"nguon":["@c1703"]},{"id":"duoc-vien","name":"Dược viên","cn":"","aliases":["Dược viên tiên nhân","Dược viên trong di tích"],"capDo":"khac","parentId":"khu-lau-cac-dinh-thai-phia-sau-chu-dien","blurb":"Dược viên rộng khoảng một mẫu nằm trước một tòa lầu các ba tầng phía sau chủ điện.","detail":"Khu vườn phát ra dược hương và được ngũ sắc quang tráo cùng các tử kim quang trụ bảo vệ. Hàn Lập đã tìm tới nhưng chưa tiến hẳn vào dược viên trong chương này.","theLucLienQuan":[],"nguon":["@c1703","@c1706"]},{"id":"dai-linh-tuyen","name":"Đại linh tuyền","cn":"","capDo":"khac","parentId":"duoc-vien","blurb":"Linh tuyền rộng khoảng bảy tám trượng nằm trong dược viên.","detail":"Bên trong đại linh tuyền có một đài sen bạc óng ánh lơ lửng, nhưng Hàn Lập chưa nhận ra giống linh dược này.","theLucLienQuan":[],"nguon":["@c1706"]},{"id":"linh-tuyen-duoi-ngan-sac-dai-sen","name":"Linh tuyền dưới ngân sắc đài sen","cn":"","capDo":"khac","parentId":"duoc-vien","blurb":"Dòng linh tuyền trong suốt nuôi dưỡng ngân sắc đài sen ở trung tâm dược viên.","detail":"Nước suối trong đến mức nhìn thấy đáy và có những sợi bạch sắc linh khí thoát ra. Hàn Lập dùng pháp trận hút toàn bộ nước suối vào bình ngọc cùng ngân sắc đài sen và bộ rễ.","theLucLienQuan":[],"nguon":["@c1707"]},{"id":"khu-vuc-mo-hu-thien-dinh","name":"Khu vực mở Hư Thiên Đỉnh","cn":"","capDo":"khac","parentId":null,"blurb":"Khoảng hư không được dùng làm nơi mở đỉnh, giám định và phân chia bảo vật.","detail":"Hàn Lập bố trí bạch sắc quang mạc bao phủ phạm vi hơn mười trượng quanh khu vực để đề phòng sự cố trong quá trình kiểm tra bảo vật.","theLucLienQuan":[],"nguon":["@c1711"]},{"id":"binh-trung-dong-thien","name":"Bình trung động thiên","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Tên một không gian chưa rõ được bốn cổ văn phía sau tấm bình phong biểu thị sau khi Hàn Lập biến mất.","detail":"Hàn Lập bị thất sắc quang hà từ bình phong cuốn đi, sau đó mặt sau bình phong hiện bốn cổ văn mang nghĩa Bình trung động thiên. Phạm vi, cấu tạo và tình trạng của Hàn Lập bên trong chưa được làm rõ.","theLucLienQuan":[],"nguon":["@c1712"]},{"id":"khong-gian-trong-binh-phong","name":"Không gian trong bình phong","cn":"","capDo":"gioi-nho","parentId":"chu-dien-mau-tim","blurb":"Không gian xám xịt nằm sau cấm chế của tấm bình phong trong tử sắc chủ điện.","detail":"Khu vực này tương tự Tu Di động thiên và có một cánh cửa khổng lồ màu xám đen phủ vô số phù văn kim ngân. Hàn Lập tiến vào đây sau khi xé mở cấm chế không gian, rồi dùng sương mù che khuất bản thân cùng cánh cửa.","theLucLienQuan":[],"nguon":["@c1713"]},{"id":"chu-dien-ngoai-binh-phong","name":"Chủ điện ngoài bình phong","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Gian điện nơi Liễu Thuý Nhi và Thạch Côn thu lấy các binh khí cùng khôi giáp còn lại.","detail":"Sau khi đồ vật trong điện bị thu sạch, Liễu Thuý Nhi và Thạch Côn rời sang thiên điện khác. Tấm bình phong tại đây che giấu lối vào Tu di động thiên.","theLucLienQuan":[],"nguon":["@c1714"]},{"id":"tu-di-dong-thien-sau-binh-phong","name":"Tu di động thiên sau bình phong","cn":"","capDo":"gioi-nho","parentId":"chu-dien-ngoai-binh-phong","blurb":"Không gian ẩn nằm sau tấm bình phong trong chủ điện.","detail":"Bên trong có đại môn được bảo vệ bởi quang hà và phù văn kim ngân. Hàn Lập phải dùng Huyền Thiên tàn nhận mới chém mở được cánh cửa.","theLucLienQuan":[],"nguon":["@c1714"]},{"id":"san-rong-sau-dai-mon","name":"Sân rộng sau đại môn","cn":"","capDo":"khac","parentId":"tu-di-dong-thien-sau-binh-phong","blurb":"Sân rộng khép kín nằm phía sau đại môn trong Tu di động thiên.","detail":"Không gian tràn ngập thanh quang, bốn phía là vách xám và không có lối ra nào khác ngoài đại môn. Trung tâm sân có một đài cao đặc biệt.","theLucLienQuan":[],"nguon":["@c1714"]},{"id":"dai-cao-nhat-nguyet-tinh-khong","name":"Đài cao nhật nguyệt tinh không","cn":"","capDo":"khac","parentId":"san-rong-sau-dai-mon","blurb":"Đài tròn lớn nằm giữa sân rộng, mang đồ án nhật nguyệt và vô số tinh tú.","detail":"Chính giữa đài đặt một ghế bành xanh biếc. Chín khôi lỗi giáp bạc cầm ngân thương đứng trên đài trong tư thế bấm quyết và hướng mũi thương lên cao.","theLucLienQuan":[],"nguon":["@c1714"]},{"id":"quang-doan-mau-vang-ong","name":"Quang đoàn màu vàng óng","cn":"","capDo":"khac","parentId":"tu-di-dong-thien-sau-binh-phong","blurb":"Dị tượng nằm rất cao trên bầu trời Tu di động thiên và được chín ngân thương đồng loạt chỉ tới.","detail":"Bên trong quang đoàn có quang hà chuyển động, khiến Hàn Lập liên tưởng tới không gian tiết điểm. Hắn xác định nó không giống không gian liệt phùng nhưng chưa biết quang đoàn có thông tới một địa phương thần bí khác hay không.","theLucLienQuan":[],"nguon":["@c1715"]},{"id":"tinh-khong-ky-di","name":"Tinh không kỳ dị","cn":"","capDo":"gioi-nho","parentId":"dai-cao-nhat-nguyet-tinh-khong","blurb":"Không gian tinh tú xuất hiện quanh Hàn Lập và đài cao khi cơ chế Tinh Không Đồ vận chuyển.","detail":"Không gian chứa vô số tinh tú trắng và cho phép Hàn Lập quan sát đài cao từ một góc nhìn kỳ dị. Những tinh tú bị phi kiếm chém vỡ có thể nhanh chóng phục hồi, khiến nơi này không hoàn toàn giống một ảo cảnh thông thường.","theLucLienQuan":[],"nguon":["@c1716"]},{"id":"mat-that-duoi-day-bien-sau","name":"Mật thất dưới đáy biển sâu","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Căn phòng ngầm bằng đá nằm dưới đáy biển sâu ở Linh giới, nơi một bộ xương khô tĩnh tọa giữa bảy mươi hai Thanh đồng đăng.","detail":"Mật thất là nơi bộ xương khô cảm ứng biến cố của kim sắc viên bàn và kiểm tra ngân sắc viên bàn. Sau khi viên bàn nứt vỡ, nó tung cự trảo phá nát một vách đá của căn phòng rồi quay lại tĩnh tọa.","theLucLienQuan":[],"nguon":["@c1719"]},{"id":"khong-gian-cung-dien","name":"Không gian cung điện","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian rộng lớn chứa chủ điện, lầu các, sơn đạo và truyền tống trận.","detail":"Khu vực bắt đầu rung chuyển dữ dội, thiên địa nguyên khí trở nên hỗn loạn, mây đen cùng lốc xoáy xuất hiện và hàng loạt cấm chế mất kiểm soát. Sau khi Hàn Lập, Liễu Thuý Nhi và Thạch Côn rời xa, một tiếng nổ kinh thiên động địa truyền đến từ phía sau.","theLucLienQuan":[],"nguon":["@c1720"]},{"id":"son-dao-khong-gian-cung-dien","name":"Sơn đạo","cn":"","capDo":"khac","parentId":"khong-gian-cung-dien","blurb":"Tuyến đường từ khu cung điện trên núi dẫn xuống chân núi.","detail":"Sơn đạo vốn có hấp lực gây trở ngại cho người đi lên. Khi cấm chế suy yếu, Hàn Lập cùng hai người đồng hành có thể phi độn nhanh chóng xuống chân núi.","theLucLienQuan":[],"nguon":["@c1720"]},{"id":"truyen-tong-tran-khong-gian-cung-dien","name":"Truyền tống trận","cn":"","capDo":"khac","parentId":"khong-gian-cung-dien","blurb":"Pháp trận dùng làm lối thoát khỏi không gian cung điện.","detail":"Hàn Lập kích hoạt pháp trận, để bạch quang bao phủ cả ba người và truyền tống họ ra ngoài ngay trước khi khu vực phía sau sụp đổ.","theLucLienQuan":[],"nguon":["@c1720"]},{"id":"khu-vuc-loi-vao-khong-gian-bi-mat","name":"Khu vực lối vào không gian bí mật","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực chịu ảnh hưởng trực tiếp từ vụ nổ trong không gian bí mật.","detail":"Phong trụ và linh áp dữ dội phá hủy nhiều tầng cấm chế tại lối vào, đồng thời cuốn mọi vật trong phạm vi vài dặm vào cơn lốc. Hàn Lập, Liễu Thuý Nhi và Thạch Côn rời khỏi nơi này theo ba hướng khi phát hiện truy binh Giác Xi Tộc áp sát.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1721"]},{"id":"khong-trung-cach-hien-truong-hon-muoi-van-dam","name":"Không trung cách hiện trường hơn mười vạn dặm","cn":"","capDo":"khac","parentId":null,"blurb":"Tuyến đường Hàn Lập phi độn với tốc độ cực cao trong lúc bị Thục Thử truy tung.","detail":"Dù đã chạy xa hơn mười vạn dặm và đẩy độn tốc tới cực hạn, Hàn Lập vẫn cảm thấy bản thân bị khóa chặt. Hắn dùng bí pháp dò xét, xác định chỉ có một truy binh phía sau rồi bắt đầu lựa chọn nơi giao chiến.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1721"]},{"id":"chien-truong-han-lap-chon-chan-truy-binh","name":"Chiến trường Hàn Lập chọn chặn truy binh","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực Hàn Lập chủ động dừng lại để chờ Thục Thử đuổi tới.","detail":"Nơi này đã cách xa lực lượng tiếp viện Giác Xi Tộc. Hàn Lập bí mật bố trí vài chục phi kiếm màu xanh quanh chiến trường trước khi giao đấu với Thục Thử và quái thú sáu chân bốn cánh.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1721"]},{"id":"lau-cac-bi-mat-cua-giac-xi-toc","name":"Lầu các bí mật của Giác Xi Tộc","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Một lầu các bí mật của Giác Xi Tộc tại Linh giới, được nhiều tầng cấm chế bảo vệ.","detail":"Lối vào lầu các có các kim giác giáp sĩ canh giữ. Bên trong đặt cự chung và năm pháp trận liên hoàn dùng để nhận biết, hô ứng và thu hồi lực lượng từ các Huyền Thiên thánh khí.","theLucLienQuan":["Giác Xi Tộc"],"nguon":["@c1725"]},{"id":"ho-nuoc-vo-danh","name":"Hồ nước vô danh","cn":"","capDo":"khac","parentId":"nghiem-han-gioi","blurb":"Hồ nước cực lớn có mặt nước xanh biếc như đại dương, Hàn Lập phải bay nhiều canh giờ vẫn chưa vượt qua.","detail":"Khu vực hầu như không có linh thú hay cao giai ma thú, còn những hải yêu thú cấp thấp hiếm hoi đều ẩn dưới đáy. Đàn Phi Hồng Ngư đông đảo sinh sống quanh hải đảo giữa hồ.","theLucLienQuan":[],"nguon":["@c1726"]},{"id":"hai-dao-chua-khoang-thach","name":"Hải đảo chứa khoáng thạch","cn":"","capDo":"khac","parentId":"ho-nuoc-vo-danh","blurb":"Hải đảo rộng khoảng ngàn dặm giữa hồ nước vô danh, có hai ngọn núi nối liền nhau.","detail":"Ngọn núi cao hơn vạn trượng phủ bụi gai ở phần dưới nhưng trơ trụi ở phần trên và chứa khoáng thạch Thạch Kiến Tộc cần. Ngọn núi thấp khoảng ba đến bốn nghìn trượng, xanh biếc và có cây cối rậm rạp.","theLucLienQuan":["Thạch Kiến Tộc"],"nguon":["@c1726"]},{"id":"ho-phi-hong-ngu","name":"Hồ Phi hồng ngư","cn":"","capDo":"khac","parentId":null,"blurb":"Thủy vực sinh sống của đàn Phi hồng ngư đông tới khoảng bốn đến năm vạn con.","detail":"Hàn Lập giao chiến với đàn Phi hồng ngư tại đây. Độc dịch rơi xuống nước đã giết nhiều loài cá khác, khiến xác cá phủ trên mặt hồ.","theLucLienQuan":[],"nguon":["@c1727"]},{"id":"hon-dao-phia-truoc","name":"Hòn đảo phía trước","cn":"","capDo":"khac","parentId":null,"blurb":"Hòn đảo Hàn Lập bay tới sau khi tiêu diệt đàn Phi hồng ngư.","detail":"Hàn Lập dặn Khúc nhi đến hòn đảo này hội hợp sau khi thu xong nội đan quái ngư. Trên đảo có một ngọn núi xám được hắn dùng kim bàn khảo sát.","theLucLienQuan":["Thạch Kiến Tộc"],"nguon":["@c1727"]},{"id":"son-phong-xam-xit","name":"Sơn phong xám xịt","cn":"","capDo":"khac","parentId":"hon-dao-phia-truoc","blurb":"Ngọn núi xám trên đảo, nơi Hàn Lập kích hoạt kim bàn của Thạch Kiến Tộc.","detail":"Sau khi nhận thanh khí và pháp quyết, kim bàn tự thoát khỏi tay Hàn Lập rồi bay nhanh về phía ngọn núi này.","theLucLienQuan":["Thạch Kiến Tộc"],"nguon":["@c1727"]},{"id":"hon-dao-giua-ho","name":"Hòn đảo giữa hồ","cn":"","capDo":"khac","parentId":"ho-nuoc-vo-danh","blurb":"Hòn đảo nơi Hàn Lập dừng chân, phát hiện khoáng mạch và luyện hóa Hỗn Nguyên Xích.","detail":"Trên đảo có sơn phong chứa khoáng mạch đáng kể. Hàn Lập bố trí cấm chế che giấu ngọn núi, giao khôi lỗi khai thác khoáng thạch và tham ngộ Thông bảo quyết của Hỗn Nguyên Xích. Cuối chương, Khúc nhi cùng Nguyệt tiên tử và Tư lão chạy về đây trong khi bị chiến xa truy sát.","theLucLienQuan":[],"nguon":["@c1728"]},{"id":"dong-ngam-trong-long-nui","name":"Động ngầm trong lòng núi","cn":"","capDo":"khac","parentId":"hon-dao-giua-ho","blurb":"Động ngầm nằm sâu dưới sơn phong trên đảo.","detail":"Hàn Lập dùng Thổ độn thuật tiến vào động ngầm, nơi nối với nhiều thông đạo uốn lượn. Thạch bích tại đây chứa khoáng thạch tím đen với số lượng đáng kể.","theLucLienQuan":[],"nguon":["@c1728"]},{"id":"day-ho-quanh-dao","name":"Đáy hồ quanh đảo","cn":"","capDo":"khac","parentId":"ho-nuoc-vo-danh","blurb":"Khu vực quanh đảo có nhiều linh dược sinh trưởng tại các vị trí kín đáo.","detail":"Khúc nhi dựa vào khả năng cảm ứng của thiên địa linh vật để tìm kiếm linh dược tại khu vực đáy hồ. Trong quá trình tiếp tục thăm dò, cô bé bị cuốn vào cuộc truy sát liên quan đến Cửu diễm thảo.","theLucLienQuan":[],"nguon":["@c1728"]},{"id":"dia-phuong-cat-cong-phap-kim-trien-van","name":"Địa phương cất công pháp Kim triện văn","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm chưa rõ tên đang bị Nhung Tộc chiếm giữ, bên trong có một bản công pháp viết bằng Kim triện văn.","detail":"Nguyệt tiên tử đề nghị Hàn Lập trợ giúp đoạt lại nơi này. Mục tiêu của nàng và Tư lão là phục chế một bản công pháp Kim triện văn được cất bên trong.","theLucLienQuan":["Nhung Tộc"],"nguon":["@c1731"]},{"id":"mat-dong-chua-luyen-than-thuat","name":"Mật động chứa Luyện thần thuật","cn":"","capDo":"khac","parentId":"nghiem-han-gioi","blurb":"Mật động bí ẩn tại Nghiễm Hàn Giới, nơi cất giữ công pháp Kim triện văn mang tên Luyện thần thuật.","detail":"Mật động có hệ thống cấm chế mạnh và các phần công pháp được đặt rải rác tại nhiều vị trí. Nhóm Tư lão từng bị Nhung Tộc ám toán tại đây; hiện hơn mười tu sĩ Nhung Tộc đang chiếm giữ và phá giải cấm chế.","theLucLienQuan":["Nhung Tộc"],"nguon":["@c1732"]},{"id":"mat-dong-nhung-toc","name":"Mật động Nhung Tộc","cn":"","capDo":"khac","parentId":"nghiem-han-gioi","blurb":"Mật động bí mật do Nhung Tộc chiếm giữ trong Nghiễm Hàn Giới, chứa công pháp viết bằng Kim triện văn.","detail":"Lối vào mật động được ngụy trang sau vách đá có các thạch văn hợp thành Bắc đẩu tinh đồ. Bên trong có nhiều tầng cấm chế cần Nghiễm Hàn Lệnh hóa giải, khiến Nhung Tộc chưa thể lấy được phần cuối trọng yếu của công pháp.","theLucLienQuan":["Nhung Tộc","Thiên Vân Tộc"],"nguon":["@c1733"]},{"id":"thong-dao-tinh-thach","name":"Thông đạo tinh thạch","cn":"","capDo":"khac","parentId":"mat-dong-nhung-toc","blurb":"Thông đạo nằm sau vách đá ngụy trang, dẫn đến đại môn được hai người Nhung Tộc trấn giữ.","detail":"Bốn phía thông đạo khảm vô số tinh thạch cỡ nắm tay tỏa bạch quang. Hàn Lập tiến qua nơi này trong trạng thái hư hóa và bị hắc mao Nhung Tộc dùng ngân ti thăm dò.","theLucLienQuan":["Nhung Tộc"],"nguon":["@c1733"]},{"id":"dai-mon-mau-xanh","name":"Đại môn màu xanh","cn":"","capDo":"khac","parentId":"thong-dao-tinh-thach","blurb":"Cánh cửa cao hơn mười trượng nằm sâu trong thông đạo tinh thạch của mật động Nhung Tộc.","detail":"Đại môn đã bị phá khuyết một góc và còn lưu lại các phù văn Kim triện văn không hoàn chỉnh. Hắc mao Nhung Tộc cùng bạch mao Nhung Tộc trấn thủ ngay trước cửa.","theLucLienQuan":["Nhung Tộc"],"nguon":["@c1733"]},{"id":"dong-quat-thach-nhu-thu-nhat","name":"Động quật thạch nhũ thứ nhất","cn":"","capDo":"khac","parentId":"mat-dong-nhung-toc","blurb":"Động quật đầu tiên có thạch bích linh văn được Hàn Lập tìm thấy trong mật động Nhung Tộc.","detail":"Động quật rộng hơn ba mươi trượng, có một thạch bích màu nhũ bạch hiện kim sắc phù văn và một người Nhung Tộc đội nón rộng vành đang nghiên cứu tại đây.","theLucLienQuan":["Nhung Tộc"],"nguon":["@c1734"]},{"id":"nga-tu-dan-den-dong-quat-cuoi","name":"Ngã tư dẫn đến động quật cuối","cn":"","capDo":"khac","parentId":"mat-dong-nhung-toc","blurb":"Nút giao thông đạo nằm trên đường dẫn đến nơi lưu giữ phần thạch bích linh văn cuối cùng.","detail":"Hàn Lập bố trí hơn một trăm trận kỳ và một tấm Cửu Cung Thiên Kiền phù tại đây để trì hoãn lực lượng Nhung Tộc quay lại chi viện.","theLucLienQuan":["Nhung Tộc"],"nguon":["@c1734"]},{"id":"dong-quat-quang-truong-tu-giac","name":"Động quật quảng trường tứ giác","cn":"","capDo":"khac","parentId":"mat-dong-nhung-toc","blurb":"Động quật rộng như một quảng trường nhỏ, được bốn tu sĩ Nhung Tộc trấn giữ.","detail":"Bốn góc quảng trường lần lượt có đại hán mang cự nhận, thanh niên mặc bì giáp, lão ông và mỹ phụ Nhung Tộc. Trung tâm là một ngân sắc quang tráo bao phủ thạch bích linh văn.","theLucLienQuan":["Nhung Tộc"],"nguon":["@c1735"]},{"id":"ngan-sac-quang-trao-trung-tam-quang-truong","name":"Ngân sắc quang tráo trung tâm quảng trường","cn":"","capDo":"khac","parentId":"dong-quat-quang-truong-tu-giac","blurb":"Quang tráo màu bạc nằm giữa quảng trường trong động quật.","detail":"Quang tráo lớn như một chiếc bát úp ngược, bao phủ phiến thạch bích có linh văn tương tự những phiến Hàn Lập từng gặp.","theLucLienQuan":["Nhung Tộc"],"nguon":["@c1735"]},{"id":"hap-coc-cat-giu-luyen-than-thuat","name":"Hạp cốc cất giữ Luyện thần thuật","cn":"","capDo":"khac","parentId":"nghiem-han-gioi","blurb":"Hạp cốc có quảng trường, vách đá khắc kim sắc linh văn và ngân sắc quang tráo bảo vệ.","detail":"Hàn Lập phá ngân sắc quang tráo, sao chép Luyện thần thuật trên vách đá rồi dùng Nguyên từ thần sơn đánh sập toàn bộ hạp cốc. Năm ngày sau, một đội Nhung Tộc trở lại kiểm tra hiện trường.","theLucLienQuan":["Nhung Tộc"],"nguon":["@c1737"]},{"id":"dong-phu-tam-thoi-truyen-thu-kim-trien-van","name":"Động phủ tạm thời truyền thụ Kim triện văn","cn":"","capDo":"khac","parentId":"nghiem-han-gioi","blurb":"Động phủ trong một ngọn núi cách hạp cốc không biết bao nhiêu vạn dặm.","detail":"Tư lão và Nguyệt tiên tử luân phiên truyền thụ kiến thức Kim triện văn cho Hàn Lập tại đây. Hàn Lập tiếp tục lĩnh hội trong nửa tháng trước khi hoàn thành giao dịch Luyện thần thuật.","theLucLienQuan":[],"nguon":["@c1737"]},{"id":"phap-tran-truyen-tong-tai-van-thanh","name":"Pháp trận truyền tống tại Vân Thành","cn":"","capDo":"khac","parentId":"van-thanh","blurb":"Điểm truyền tống đưa những người từ giới diện trở về Vân Thành giữa lúc chiến sự đang diễn ra.","detail":"Pháp trận vẫn tiếp tục vận hành dù phần lớn trận pháp và cấm chế xung quanh đã bị phá hủy. Quân Giác Xi Tộc đã xâm nhập khu vực, còn hộ vệ Thiên Vân cố duy trì phòng tuyến quanh pháp trận.","theLucLienQuan":["Giác Xi Tộc","Thiên Vân mười ba tộc","Hộ vệ Thiên Vân"],"nguon":["@c1739"]},{"id":"am-thu-gioi","name":"Ám Thú giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện nơi Hàn Lập giao chiến với Ám thú vương trước khi bị cưỡng ép truyền trả.","detail":"Khi thời gian lưu lại kết thúc, pháp tắc giới diện tạo ra ngũ sắc vân vụ và không gian dao động, cưỡng ép Hàn Lập rời khỏi nơi này. Ngay cả Minh Thanh Linh Mục cũng không thể nhìn xuyên ngũ sắc quang hà trong quá trình truyền tống.","theLucLienQuan":[],"nguon":["@c1739"]},{"id":"tong-bo-van-co-toc-tai-van-thanh","name":"Tổng bộ Vạn Cổ Tộc tại Vân thành","cn":"","capDo":"thanh","parentId":"bat-van-son","blurb":"Tòa thành nhỏ thuộc Vạn Cổ Tộc ở Bát Vân sơn, hiện là trung tâm chỉ huy việc phòng thủ Vân thành.","detail":"Tường thành bố trí tượng khôi lỗi, bên trong có nhân hình khôi lỗi tuần tra và nhiều kim chúc khôi lỗi cỡ lớn bảo vệ. Độn quang của người thuộc nhiều tộc liên tục ra vào nơi này.","theLucLienQuan":["Vạn Cổ Tộc","Thiên Vân mười ba tộc"],"nguon":["@c1740"]},{"id":"phuc-giao-thanh","name":"Phục Giao Thành","cn":"","capDo":"thanh","parentId":null,"blurb":"Điểm rút lui được thanh niên họ Ông chỉ định cho đoàn tu sĩ rời Vân Thành.","detail":"Trong mật điện của Phục Giao Thành có một siêu cấp Truyền Tống Trận đang bị phong bế. Thanh niên họ Ông hứa ra lệnh mở trận cho Hàn Lập sử dụng một lần.","theLucLienQuan":["Thiên Vân tộc"],"nguon":["@c1741","@c1745"]},{"id":"tinh-van-cac","name":"Tinh Vân các","cn":"","capDo":"khac","parentId":"phuc-giao-thanh","blurb":"Nơi các trưởng lão triệu tập những người vừa trở về từ Nghiễm Hàn giới.","detail":"Tinh Vân các là một quần thể lầu các bao quanh ngọn núi trong Phục Giao thành. Chính điện lớn nằm trên đỉnh núi, phía trước có biển hiệu viết bằng chữ cổ màu vàng kim; Thiên Cơ Tử đứng tại đây chờ Hàn Lập.","theLucLienQuan":["Thiên Vân mười ba tộc","Vạn Cổ Tộc"],"nguon":["@c1742"]},{"id":"thanh-ky-phong","name":"Thanh Kỳ phong","cn":"","capDo":"khac","parentId":"phuc-giao-thanh","blurb":"Ngọn núi ngoài Phục Giao thành được Hướng Chi Lễ chọn làm nơi gặp riêng Hàn Lập.","detail":"Thanh Kỳ phong nằm ngoài Phục Giao thành hơn trăm dặm. Hướng Chi Lễ hẹn Hàn Lập tới đây sau ba ngày để giao một vật và nói chuyện riêng.","theLucLienQuan":[],"nguon":["@c1742"]},{"id":"lau-cac-tai-trong-dia-thien-van-toc","name":"Lầu các tại trọng địa Thiên Vân tộc","cn":"","capDo":"khac","parentId":"thien-van","blurb":"Lầu các nơi Thiên Cơ Tử chờ Hàn Lập và tổ chức cuộc gặp kín với hai vị thánh giai khác.","detail":"Bên trong lầu các có ngân y thủ vệ, một căn phòng tầng một đặt các tiểu truyền tống trận và đại sảnh dùng để trao đổi Tiên giới linh dược.","theLucLienQuan":["Thiên Vân tộc","Vạn Cổ Tộc"],"nguon":["@c1743"]},{"id":"quang-han-gioi","name":"Quảng Hàn Giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Một giới vực nơi Hàn Lập từng thu gom lượng lớn linh dược quý hiếm.","detail":"Hơn trăm gốc linh dược Hàn Lập đưa ra trong cuộc giao dịch được lấy từ Quảng Hàn Giới. Trong số đó có nhiều loại đã tuyệt chủng tại Linh Giới và đạt tuổi dược vạn năm.","theLucLienQuan":[],"nguon":["@c1744"]},{"id":"thanh-giao-phong","name":"Thanh Giao Phong","cn":"","capDo":"khac","parentId":"phuc-giao-thanh","blurb":"Ngọn núi vắng vẻ nằm cách Phục Giao Thành hơn trăm dặm về phía tây, là nơi Hàn Lập hẹn gặp Hướng Chi Lễ.","detail":"Thanh Giao Phong quanh năm phủ cây xanh và có hình dáng như một con giao long sắp bay. Hàn Lập bố trí hơn chục trận kỳ quanh núi trước khi gặp Hướng Chi Lễ và bị Cự Linh phù cùng huyết ảnh tập kích.","theLucLienQuan":[],"nguon":["@c1745"]},{"id":"ngon-nui-ngoai-phuc-giao-thanh","name":"Ngọn núi ngoài Phục Giao Thành","cn":"","capDo":"khac","parentId":"phuc-giao-thanh","blurb":"Ngọn núi cách Phục Giao Thành hơn trăm dặm, nơi Hàn Lập giao chiến với huyết ảnh.","detail":"Hàn Lập bố trí trận kỳ quanh ngọn núi để che giấu linh khí dao động, tiêu diệt huyết ảnh tại đây rồi thiêu hủy hài cốt và thu hồi trận kỳ trước khi đội tuần tra tới.","theLucLienQuan":[],"nguon":["@c1746"]},{"id":"ngon-nui-cao-nhat-phuc-giao-thanh","name":"Ngọn núi cao nhất Phục Giao Thành","cn":"","capDo":"khac","parentId":"phuc-giao-thanh","blurb":"Ngọn núi cao nhất trong Phục Giao Thành, bên ngoài được thông báo đang sửa chữa các kiến trúc trọng yếu.","detail":"Hàn Lập tiến vào ngọn núi này để sử dụng pháp trận. Một tháng sau, cột sáng lớn từ lòng núi phóng lên trời, đánh dấu việc hắn rời Lôi Minh đại lục.","theLucLienQuan":[],"nguon":["@c1746"]},{"id":"dai-luc-bi-an-xa-loi-minh-dai-luc","name":"Đại lục bí ẩn xa Lôi Minh đại lục","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Một đại lục chưa rõ tên nằm rất xa Lôi Minh đại lục.","detail":"Tại một địa điểm bí ẩn trên đại lục này, cột sáng tương ứng với hiện tượng ở Phục Giao Thành xuất hiện, sau đó một nhân ảnh hiện ra giữa pháp trận lớn.","theLucLienQuan":[],"nguon":["@c1746"]}]};
